INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C1','kor',6,1,'u3',1,'토론이 필요한 상황 — 같은 일을 두고 찬성과 반대로 생각이 갈리는 문제에서 토론이 필요하며, 답이 이미 정해져 있거나 자료를 찾아보면 곧바로 확인되는 물음(학교가 문을 연 해 · 교실 온도)은 토론 주제가 되지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C2','kor',6,1,'u3',1,'토의와 토론의 다른 점 — 둘 다 문제를 해결하려고 함께 이야기하지만, 토의는 편을 나누지 않고 방법을 모으는 말하기이고 토론은 찬성 측과 반대 측으로 편이 갈리는 말하기로, 가르는 잣대는 「찬반으로 편이 갈리는가」 하나이다',ARRAY['6국01-07 듣기 · 말하기']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C3','kor',6,1,'u3',1,'토론의 뜻 — 어떤 문제를 두고 찬성 측과 반대 측으로 나뉘어 각자 근거를 들어 자기 주장이 옳음을 밝히는 말하기로, 목소리가 큰 쪽이 이기는 것이 아니라 타당한 이유와 근거를 내놓고 정해진 절차를 지켜 겨룬다',ARRAY['6국01-07 듣기 · 말하기']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C4','kor',6,1,'u3',1,'주장 · 이유 · 근거의 세 층 — 주장은 내가 옳다고 내세우는 생각, 이유는 그렇게 주장하는 까닭(내 머릿속에서 나온 문장), 근거는 이유를 뒷받침하는 객관적인 자료(밖에서 가져와 확인할 수 있는 것)이며, 세 층이 위아래로 맞물려야 말이 선다',ARRAY['6국01-02 듣기 · 말하기']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C5','kor',6,1,'u3',1,'토론의 네 단계 — 주장 펼치기(주장 · 이유 · 근거를 냄) → 반론하기(상대 허점을 짚고 답함) → 주장 다지기(남은 것을 추려 다시 세움) → 판정하기(기준을 밝히고 더 설득력 있는 쪽을 정함)의 차례로 나아가며, 각 단계에 지킬 규칙이 있다',ARRAY['6국01-07 듣기 · 말하기']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C6','kor',6,1,'u3',1,'경청하는 태도 — 상대 발언을 끝까지 듣고 메모한 뒤 말차례에 되받으며, 듣지 않으면 무엇을 되받을지도 알 수 없으므로 경청은 예의이면서 실력이다',ARRAY['6국01-07 듣기 · 말하기']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C7','kor',6,1,'u3',1,'토론의 목적 — 토론은 찬반으로 겨루는 방식이 맞지만 그렇게 겨루는 목적은 상대를 누르는 것이 아니라 더 합리적인 결정에 이르는 것이며, 근거를 겨누고 결과에 승복한다',ARRAY['6국01-07 듣기 · 말하기']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C8','kor',6,1,'u3',1,'토론 주제의 갈래 — 참인지 거짓인지 따지는 문제 · 좋고 나쁨을 따지는 문제 · 무엇을 하자고 정하는 문제가 있으나 셋을 딱 잘라 나눌 필요는 없으며, 우리가 바꿔 볼 수 있는 「무엇을 하자고 정하는 문제」가 교실 토론에 가장 잘 맞는다',ARRAY['6국01-07 듣기 · 말하기']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C9','kor',6,1,'u3',2,'주장 펼치기 — 양측이 차례로 주장 → 이유 → 근거를 함께 내놓는 단계로, 세 층이 다 있어야 주장 펼치기가 되며 사회자는 주제와 순서를 안내한다',ARRAY['6국01-07 듣기 · 말하기']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C10','kor',6,1,'u3',2,'근거가 될 수 있는 것 — 설문 조사 결과 · 통계 · 이름을 밝힌 전문가의 말처럼 밖에서 가져와 누가 언제 무엇을 조사했는지 확인할 수 있는 것이 근거이고, 「그렇게 느낀다 · 그럴 것 같다」로 끝나는 문장은 이유이다',ARRAY['6국01-02 듣기 · 말하기']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C11','kor',6,1,'u3',2,'반론의 뜻과 범위 — 반론은 상대 주장에 맞서 반대되는 자기 주장을 밝히는 말하기로, 주장 펼치기에서 나온 내용(주장 · 이유 · 근거)에 대해서만 되받고 새 이야기를 꺼내지 않으며, 정리할 때에는 발언을 그대로 옮기지 않고 핵심만 요약한다',ARRAY['6국01-07 듣기 · 말하기']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C12','kor',6,1,'u3',2,'반론에 답변하기 — 답변할 때에는 상대가 물은 그 지점에 곧바로 답하면서 그 반론이 타당하지 않음을 밝히거나, 인정할 것은 인정하고 자료로 다시 세우며, 같은 말을 되풀이하는 것(공평하니까 공평하다)은 답변이 아니다',ARRAY['6국01-07 듣기 · 말하기']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C13','kor',6,1,'u3',2,'반론은 사람을 겨누지 않는다 — 「그것도 모르십니까?」처럼 사람이나 말투를 겨눈 말은 반론이 아니고 「그 자료는 조사한 때가 나와 있지 않습니다」처럼 주장 · 이유 · 근거를 겨누어야 하며, 토론은 공식적인 말하기이므로 높임말을 쓰고 공격적인 말투로 흐르지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C14','kor',6,1,'u3',2,'주장 다지기 — 같은 말을 되풀이하는 단계가 아니라 앞 두 단계에서 확인된 것만 추려 자기편 주장을 다시 세우는 단계로, 짧은 문장 · 「요컨대 · 따라서」 같은 이어 주는 말 · 또박또박 힘 있는 목소리로 말하며 무너진 근거를 다시 꺼내지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C15','kor',6,1,'u3',2,'판정의 첫 조건 — 명확한 기준 — 판정할 때 가장 먼저 있어야 하는 것은 무엇을 보고 정할지 미리 밝혀 둔 명확한 기준(타당한 이유를 냈는가 · 믿을 수 있는 근거를 냈는가 등)이며, 기준이 없으면 판정이 아니라 취향이 된다',ARRAY['6국01-02 듣기 · 말하기']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C16','kor',6,1,'u3',2,'판정은 옳고 그름을 가리지 않는다 — 판정은 어느 쪽 생각이 옳은지 가려 주는 일이 아니라 정해 둔 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지를 정하는 일이라 기준이 달라지면 결과도 달라질 수 있으며, 토론자는 그 결과에 승복한다',ARRAY['6국01-02 듣기 · 말하기']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C17','kor',6,1,'u3',2,'토론 전 과정의 규칙 — 단계마다 다른 규칙 말고도 처음부터 끝까지 지킬 규칙이 있다 — 높임말을 쓰고 · 말차례를 지키고(끼어들지 않고) · 주제와 이어지는 말만 하고 · 상대를 존중한다',ARRAY['6국01-07 듣기 · 말하기']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C18','kor',6,1,'u3',4,'학급 토론 주제 고르기 — 친구들이 관심 있어 하고 · 찬성과 반대가 뚜렷하게 갈리고 · 양쪽 모두 근거를 찾을 수 있고 · 우리 힘으로 바꿔 볼 수 있는 문제를 고르며, 늘 그래 왔던 일에도 「꼭 그래야 할까」라고 물으면 좋은 주제가 나온다',ARRAY['6국01-07 듣기 · 말하기']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C19','kor',6,1,'u3',4,'입장 먼저, 역할은 나중 — 주제가 정해지면 먼저 모두가 자기 생각(찬성 · 반대)을 정하고 역할은 그다음에 나누며, 찬성과 반대가 비슷한 수로 갈려야 토론이 팽팽해진다',ARRAY['6국01-07 듣기 · 말하기']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C20','kor',6,1,'u3',4,'토론 준비표 — 준비표에는 주장 → 이유 → 이유마다 근거를 적고 예상 반론과 답변까지 덧붙이며, 이유는 두세 가지를 준비해 하나가 무너져도 남은 것으로 버틸 수 있게 한다',ARRAY['6국01-07 듣기 · 말하기']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C21','kor',6,1,'u3',4,'근거를 찾는 곳 — 믿을 만한 곳에서 낸 책과 누리집 자료 · 그 일을 오래 해 온 전문가의 의견(누구의 말인지 반드시 적음) · 우리 반이나 학년에 직접 물어 수를 센 설문 조사에서 근거를 찾고, 모은 자료는 같은 편끼리 바꾸어 읽어 본다',ARRAY['6국01-02 듣기 · 말하기']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C22','kor',6,1,'u3',4,'예상 반론과 답변 준비 — 상대가 무엇이라 되받을지 미리 적고 그에 대한 답변을 준비하며, 이 과정에서 내 근거의 약한 곳이 먼저 드러나므로 건너뛰지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C23','kor',6,1,'u3',4,'토론의 네 역할 — 사회자(주제와 규칙을 알리고 말차례를 이끎 · 주제에서 벗어나지 않게 함) · 토론자(근거를 들어 간결하고 분명하게 말하고 상대 말을 끝까지 들음) · 판정단(기준을 정해 공정하게 판정 · 자기 생각과 같은 편에 후하게 주지 않음) · 청중(메모하며 듣고 잘한 곳 · 인상 깊은 근거를 짚음)으로, 모두에게 할 일이 있다',ARRAY['6국01-07 듣기 · 말하기']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C24','kor',6,1,'u3',4,'진행 순서와 협의 시간 — 찬성 · 반대 주장 펼치기 → 반대 측 반론과 찬성 측 답변 → 찬성 측 반론과 반대 측 답변 → 찬성 · 반대 주장 다지기 → 판정단의 판정과 정리의 차례로 굴러가며, 단계 사이 협의 시간에 같은 편끼리 반론과 답변을 맞춘다',ARRAY['6국01-07 듣기 · 말하기']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C25','kor',6,1,'u3',4,'뜨거워질수록 침착하게 — 질문과 답이 빠르게 오가는 반론하기에서는 감정이 앞서기 쉬우므로 말차례를 기다리고 · 한 번에 한 가지만 되받고 · 졌다고 느껴질 때에도 침착하게 이어 가며, 지나치게 뜨거워지면 서로의 말이 들리지 않아 되받을 수도 없다',ARRAY['6국01-07 듣기 · 말하기']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C26','kor',6,1,'u3',6,'근거를 따지는 세 물음 — 근거가 타당한지는 「주장이나 이유와 관련 있는가(관련성) · 출처가 분명한가(신뢰성) · 언제 누구를 조사했는지 충분히 구체적인가(충분성)」 세 물음으로 따지되, 셋을 딱 잘라 나누기보다 한 번씩 던져 보고 전체적으로 타당한지 본다 — 내 근거를 다듬을 때도, 상대 근거에 반론할 때도 쓴다',ARRAY['6국01-02 듣기 · 말하기']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C27','kor',6,1,'u3',6,'힘을 내지 못하는 근거 — 「어떤 동영상에서 봤는데」(누가 만든 무엇인지 모름) · 「많은 사람이 그렇게 답했다」(언제 몇 명에게 물었는지 없음) · 이유와 이어지지 않는 다른 이야기처럼, 세 물음 가운데 하나만 걸려도 근거는 흔들린다',ARRAY['6국01-02 듣기 · 말하기']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C28','kor',6,1,'u3',6,'충분성은 자료 개수가 아니다 — 자료를 다섯 개나 내도 각각이 흐릿하면 그대로이며, 충분하다는 것은 자료 하나가 언제 · 누구를 · 어떻게 조사한 것인지 밝혀져 있다는 뜻이라 자세한 자료 하나로도 충분할 수 있다',ARRAY['6국01-02 듣기 · 말하기']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C29','kor',6,1,'u3',6,'경험도 근거가 될 수 있다 — 나에게만 일어난 지나치게 드문 일(운동장에서 지갑을 주웠다)은 근거가 되기 어렵지만, 여러 사람이 그럴 만하다고 여길 일을 느낌으로 두지 않고 세거나 재어서 정리하면(한 시간 동안 출입을 세었더니) 근거가 될 수 있다',ARRAY['6국01-02 듣기 · 말하기']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C30','kor',6,1,'u3',6,'믿을 만한 자료 고르기 — 공신력 있는 곳(정부 기관 · 대학 · 연구소 · 언론사)에서 · 가장 최근에 낸 · 주제와 직접 이어지는 · 한쪽에 치우치지 않은 자료를 고르며, 무언가를 팔려는 글이나 광고에 가까운 기사는 근거로 삼기 어렵다',ARRAY['6국01-02 듣기 · 말하기']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C31','kor',6,1,'u3',6,'근거를 내놓는 법 — 세부 사항을 모두 읽지 않고 중요한 내용만 추려 분명하게 전하고, 표나 그림으로 보이면 한눈에 들어오며, 말할 때 누가 언제 낸 자료인지를 먼저 밝힌다 — 「어디서 봤는데」로 시작하면 좋은 자료도 흔들린다',ARRAY['6국01-07 듣기 · 말하기']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C32','kor',6,1,'u3',8,'사회 문제로 주제 정하기 — 늘 그래 왔던 일에 「꼭 그래야 할까」라고 묻고 많은 친구가 관심 있어 할 문제를 고르되, 사회 문제는 아는 것이 적으면 겉돌기 쉬우므로 주제를 정한 뒤 먼저 알려진 사실(지금 제한 속도 · 사고 건수)부터 함께 맞춰 본다',ARRAY['6국01-07 듣기 · 말하기']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C33','kor',6,1,'u3',8,'판정단의 공정함 — 판정단은 판정 기준을 미리 정해 적어 두고, 토론에서 실제로 나온 말과 자료만으로 판정하며, 평소 자기 생각과 같은 편이나 친한 친구가 있는 편에 후하게 주지 않는다',ARRAY['6국01-02 듣기 · 말하기']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C34','kor',6,1,'u3',8,'메모하며 듣기 — 주장 펼치기는 준비한 대로 말하면 되지만 반론하기는 그 순간에 들은 것으로만 할 수 있어 승패가 여기서 갈리므로, 원고를 다시 읽지 말고 상대측 주장(한 문장) · 이유의 개수 · 근거의 출처 · 답이 닿지 않은 물음을 핵심만 짧게 메모해 가장 약한 한 곳을 되받는다',ARRAY['6국01-02 듣기 · 말하기']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C35','kor',6,1,'u3',8,'판정 기준 네 갈래 — 주장 펼치기(주장이 설득력 있고 이유와 근거가 타당한가) · 반론하기(상대 이유나 근거의 문제를 찾아 되받고 반론에 알맞게 답했는가) · 주장 다지기(다시 정리해 분명히 했는가) · 태도(규칙을 지키고 경청하며 예의 바르게 참여했는가)로 본다',ARRAY['6국01-02 듣기 · 말하기']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C36','kor',6,1,'u3',8,'판정 뒤의 마무리 — 「우리가 이겼다 · 판정이 이상하다」로 끝내면 남는 것이 승패뿐이므로 판정 결과에는 승복하고 「저 근거는 나도 다시 찾아봐야겠다」처럼 생각을 남기며, 토론 뒤 생각이 바뀌거나 더 굳어지는 것은 부끄러운 일이 아니라 토론을 제대로 한 표시이다',ARRAY['6국01-07 듣기 · 말하기']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C37','kor',6,1,'u3',11,'실천 토론 주제 고르기 — 역사 · 환경 · 생활 어느 갈래에서 찾든 찬반이 갈리고 양쪽 모두 근거를 찾을 수 있어야 하며, 연도나 이름처럼 자료를 찾으면 답이 하나로 나오는 물음은 토론 주제가 아니다',ARRAY['6국01-07 듣기 · 말하기']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C38','kor',6,1,'u3',11,'근거는 나누어 모으고 골라 쓴다 — 모둠 안에서 찾을 영역(통계 · 전문가의 말 · 다른 고장 사례)을 나누고, 누가 언제 낸 자료인지 함께 적고, 같은 편끼리 바꾸어 읽으며 세 물음을 던진 뒤 가장 센 두 가지만 골라 준비표에 옮긴다',ARRAY['6국01-02 듣기 · 말하기']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C39','kor',6,1,'u3',11,'원탁 토론 — 찬반 토론이 편을 나누어 정해진 단계대로 겨루고 사회자와 판정단을 두는 것과 달리, 원탁 토론은 편을 나누지 않고 모두가 대등하게 한 차례에 한 번씩 돌아가며 말하며 답이 둘로 갈리지 않는 문제에 알맞다 — 어느 쪽이든 근거를 들어 말한다는 점은 같다',ARRAY['6국01-07 듣기 · 말하기']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C40','kor',6,1,'u3',11,'역사 논쟁은 관점의 차이 — 역사에 관한 논쟁에는 옳고 그름이 있는 것이 아니라 무엇을 더 중요하게 여겼는지 서로 다른 관점이 있으므로(배움의 기회 · 남은 것의 진짜 모습), 한쪽을 틀린 편으로 만들지 않고 판정 뒤에도 상대 생각을 낮추어 말하지 않는다',ARRAY['6국01-07 듣기 · 말하기']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C41','kor',6,1,'u3',11,'토론 뒤 나눌 이야기 — 토론은 끝났을 때가 아니라 새롭게 알게 된 사실 · 다른 역할을 맡았던 친구 가운데 잘한 사람과 그 까닭 · 생각이 바뀌었거나 더 굳어진 곳을 나눌 때 비로소 마무리된다',ARRAY['6국01-07 듣기 · 말하기']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C42','kor',6,1,'u3',11,'토론자에게 필요한 힘 — 자기 주장을 타당한 이유와 근거로 뒷받침하는 힘 · 상대의 반론이나 질문에 알맞게 답하는 힘 · 상대 근거의 타당성을 따져 보는 힘 · 자신감 있게 그러면서도 예의 바르게 표현하는 힘이며, 말을 많이 하거나 크게 하는 것과 토론을 잘하는 것은 다르다',ARRAY['6국01-07 듣기 · 말하기']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K6-1-u3-C43','kor',6,1,'u3',11,'겹받침 읽기 — 겹받침은 뒤에 자음이 오면 두 자음 가운데 하나만 소리 나고 그 뒤의 ㄱ · ㄷ · ㅂ · ㅅ · ㅈ은 된소리가 된다 — ㄻ은 [ㅁ](젊다 [점따] · 옮기다 [옴기다]), ㄿ은 [ㅂ](읊다 [읍따] · 가락을 붙여 시를 읽거나 외다), ㄺ은 [ㄱ](굵다 [국따] · 늙지 [늑찌])이되 ㄺ 뒤에 ㄱ이 오면 [ㄹ](굵고 [굴꼬]) (기초 다지기)',ARRAY['기초 다지기(겹받침)']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X01','kor',6,'u3',ARRAY['K6-1-u3-C1','K6-1-u3-C18','K6-1-u3-C32','K6-1-u3-C37']::text[],'답이 이미 정해져 있거나 자료를 찾아보면 곧바로 확인되는 물음(학생 수 · 연도 · 지켜야 할 규칙)도 토론 주제가 된다고 여긴다','찬반이 갈리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X02','kor',6,'u3',ARRAY['K6-1-u3-C2','K6-1-u3-C3']::text[],'편을 나누지 않고 방법을 모으는 토의와 찬반으로 편이 갈리는 토론을 헷갈린다','찬반으로 편이 갈리나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X03','kor',6,'u3',ARRAY['K6-1-u3-C3','K6-1-u3-C39']::text[],'토론을 한 사람이 여러 사람 앞에서 자기 생각을 알리는 말하기(연설 · 발표)로 여긴다','찬성 측과 반대 측') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X04','kor',6,'u3',ARRAY['K6-1-u3-C4','K6-1-u3-C10']::text[],'그렇게 주장하는 까닭(이유)과 밖에서 가져온 자료(근거)를 헷갈려, 내 느낌이나 생각을 근거로 여긴다','내 까닭? 밖의 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X05','kor',6,'u3',ARRAY['K6-1-u3-C9','K6-1-u3-C4']::text[],'주장만 내세우고 이유나 근거를 함께 내지 않는다','주장 → 이유 → 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X06','kor',6,'u3',ARRAY['K6-1-u3-C5','K6-1-u3-C24']::text[],'토론의 네 단계의 차례나 각 단계에서 하는 일을 헷갈린다','펼치기 → 반론 → 다지기 → 판정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X07','kor',6,'u3',ARRAY['K6-1-u3-C6','K6-1-u3-C17']::text[],'허점이 보이면 상대 말을 끊고 끼어들어 곧바로 되받는다','말차례를 기다려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X08','kor',6,'u3',ARRAY['K6-1-u3-C6','K6-1-u3-C34']::text[],'상대 말을 듣지 않고 준비한 원고를 그대로 읽는다','듣고 메모해야 되받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X09','kor',6,'u3',ARRAY['K6-1-u3-C7']::text[],'토론을 어떻게든 상대를 눌러 이겨야 하는 시합으로 여긴다','목적은 합리적인 결정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X10','kor',6,'u3',ARRAY['K6-1-u3-C8']::text[],'토론 주제의 갈래를 반드시 딱 잘라 나눌 수 있어야 토론할 수 있다고 여긴다','딱 잘라 나눌 필요는 없어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X11','kor',6,'u3',ARRAY['K6-1-u3-C11','K6-1-u3-C17']::text[],'반론이나 답변에서 주장 펼치기에 나오지 않은, 주제와 상관없는 새 이야기를 꺼낸다','펼친 내용에 대해서만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X12','kor',6,'u3',ARRAY['K6-1-u3-C11','K6-1-u3-C34']::text[],'반론을 정리하거나 메모할 때 상대 발언을 한 글자도 빠짐없이 그대로 옮겨 적는다','핵심만 짧게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X13','kor',6,'u3',ARRAY['K6-1-u3-C12']::text[],'반론에 답할 때 상대가 물은 것에 답하지 않고 같은 말을 되풀이한다(공평하니까 공평합니다)','물은 그 지점에 답하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X14','kor',6,'u3',ARRAY['K6-1-u3-C13']::text[],'반론에서 주장 · 이유 · 근거가 아니라 사람이나 말투를 겨누거나, 반말 · 공격적인 말투를 쓴다','근거를 겨눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X15','kor',6,'u3',ARRAY['K6-1-u3-C14']::text[],'주장 다지기를 처음 한 말을 그대로 되풀이하는 단계로 여기거나, 반론에서 무너진 근거를 다시 꺼낸다','남은 것만 추려 다시') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X16','kor',6,'u3',ARRAY['K6-1-u3-C15','K6-1-u3-C35']::text[],'판정을 미리 밝힌 기준 없이 목소리 크기 · 말한 길이 · 평소 생각 같은 것으로 한다','기준이 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X17','kor',6,'u3',ARRAY['K6-1-u3-C16']::text[],'판정 결과가 어느 쪽 생각이 옳은지를 가려 준다고 여긴다','더 설득력 있게 말한 쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X18','kor',6,'u3',ARRAY['K6-1-u3-C16','K6-1-u3-C36']::text[],'판정 결과가 마음에 들지 않으면 승복하지 않고 판정단 탓을 한다','결과에 승복해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X19','kor',6,'u3',ARRAY['K6-1-u3-C18','K6-1-u3-C37']::text[],'친구들이 관심 없거나 우리 힘으로 바꿀 수 없는 문제를 토론 주제로 고른다','관심 · 바꿔 볼 수 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X20','kor',6,'u3',ARRAY['K6-1-u3-C19']::text[],'모두가 자기 생각을 정하기 전에 역할부터 나누거나, 찬반을 한쪽으로 기울게 나눈다','생각 먼저, 역할은 나중') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X21','kor',6,'u3',ARRAY['K6-1-u3-C20']::text[],'이유를 하나만 준비해 그것이 무너지면 버틸 것이 없다','이유는 두세 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X22','kor',6,'u3',ARRAY['K6-1-u3-C21','K6-1-u3-C38']::text[],'전문가의 말이나 찾은 자료를 쓸 때 누구의 말인지 · 어디서 낸 자료인지 적지 않는다','누구의 말인지 적기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X23','kor',6,'u3',ARRAY['K6-1-u3-C22']::text[],'예상 반론과 답변을 미리 적어 보는 준비를 건너뛰어도 된다고 여긴다','약한 곳이 먼저 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X24','kor',6,'u3',ARRAY['K6-1-u3-C23','K6-1-u3-C33']::text[],'판정단이 자기 생각과 같은 편이나 친한 친구가 있는 편에 후하게 준다','나온 말과 자료만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X25','kor',6,'u3',ARRAY['K6-1-u3-C23']::text[],'사회자 · 토론자 · 판정단 · 청중이 할 일을 서로 헷갈린다','이끎 · 말함 · 정함 · 들음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X26','kor',6,'u3',ARRAY['K6-1-u3-C25']::text[],'반론하기에서 감정이 앞서 목소리를 높이거나 한꺼번에 여러 가지를 몰아친다','한 번에 한 가지, 침착하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X27','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'주장이나 이유와 이어지지 않는 자료도 근거로 쓸 수 있다고 여긴다','이유와 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X28','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'어디서 나왔는지 확인할 수 없는 자료(어떤 누리집 · 어떤 동영상)를 근거로 쓴다','출처가 분명한가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X29','kor',6,'u3',ARRAY['K6-1-u3-C26','K6-1-u3-C27']::text[],'「많은 사람 · 다들」처럼 언제 몇 명에게 물었는지 없는 흐릿한 자료를 근거로 쓴다','언제 · 누구를?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X30','kor',6,'u3',ARRAY['K6-1-u3-C28']::text[],'자료의 개수가 많거나 길면 충분한 근거라고 여긴다','개수가 아니라 구체성') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X31','kor',6,'u3',ARRAY['K6-1-u3-C21','K6-1-u3-C29']::text[],'전문가의 말이나 내가 겪은 일, 사람에게 물은 자료는 무조건 근거가 될 수 없다고 여긴다','확인되고 정리되면 근거') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X32','kor',6,'u3',ARRAY['K6-1-u3-C29']::text[],'나에게만 일어난 드문 일이나 느낌을 세거나 재지 않고 그대로 근거로 쓴다','세거나 재어서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X33','kor',6,'u3',ARRAY['K6-1-u3-C30']::text[],'오래된 자료나 무언가를 팔려는 광고 글, 한쪽에 치우친 자료를 근거로 쓴다','공신력 · 최근 · 치우침 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X34','kor',6,'u3',ARRAY['K6-1-u3-C31']::text[],'근거를 내놓을 때 세부 사항을 모두 읽거나, 누가 언제 낸 자료인지 밝히지 않고 「어디서 봤는데」로 시작한다','출처를 먼저 밝혀요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X35','kor',6,'u3',ARRAY['K6-1-u3-C26']::text[],'근거를 세 물음으로 따지지 않고 숫자가 있는지 · 그럴듯해 보이는지만 보거나, 세 물음 가운데 하나만 통과하면 된다고 여긴다','세 물음을 한 번씩') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X36','kor',6,'u3',ARRAY['K6-1-u3-C32']::text[],'사회 문제를 주제로 정하고 알려진 사실을 함께 맞춰 보지 않은 채 토론한다','사실부터 함께 맞춰요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X37','kor',6,'u3',ARRAY['K6-1-u3-C23']::text[],'청중은 토론에서 할 일이 없다고 여긴다','메모하고 짚어 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X38','kor',6,'u3',ARRAY['K6-1-u3-C34']::text[],'토론 중에 상대의 말투 · 목소리 크기 · 옷차림처럼 되받을 거리가 아닌 것을 메모한다','되받을 거리를 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X39','kor',6,'u3',ARRAY['K6-1-u3-C36']::text[],'토론 중이나 뒤에 생각이 바뀌면 진 것이라 여겨 무너진 근거를 끝까지 붙잡는다','바뀌어도 괜찮아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X40','kor',6,'u3',ARRAY['K6-1-u3-C36','K6-1-u3-C41']::text[],'토론이 끝난 뒤 승패만 말하거나 상대의 준비를 깎아내린다','배운 것을 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X41','kor',6,'u3',ARRAY['K6-1-u3-C39']::text[],'편을 나누지 않고 대등하게 말하는 원탁 토론과 편을 나누어 겨루는 찬반 토론을 헷갈린다','편을 나누나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X42','kor',6,'u3',ARRAY['K6-1-u3-C40']::text[],'역사에 관한 논쟁을 한쪽은 옳고 다른 쪽은 틀린 문제로 여긴다','무엇을 더 중요하게 여겼나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X43','kor',6,'u3',ARRAY['K6-1-u3-C38']::text[],'모은 근거를 같은 편끼리 바꾸어 읽거나 고르지 않고 모두 준비표에 옮긴다','가장 센 두 가지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X44','kor',6,'u3',ARRAY['K6-1-u3-C43']::text[],'겹받침의 두 자음을 모두 소리 내거나, 어느 자음이 소리 나는지 · 뒤 자음이 된소리가 되는지를 틀리게 읽는다(굵고 [국꼬])','ㄻ [ㅁ] · ㄿ [ㅂ] · ㄺ [ㄱ], ㄺ+ㄱ [ㄹ]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K6-1-u3-X45','kor',6,'u3',ARRAY['K6-1-u3-C42']::text[],'말을 많이 하거나 크게 하는 것을 토론을 잘하는 것으로 여긴다','근거 · 답변 · 예의') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#1','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C3',1,'mc','auto','「토론」의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03','K6-1-u3-X09']::text[],false,'{"seq":1,"concept":"K6-1-u3-C3","difficulty":1,"kind":"mc","stem":"「토론」의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기","correct":true},{"t":"편을 나누지 않고 여럿이 의견을 모아 방법을 찾는 말하기","mis":"K6-1-u3-X02"},{"t":"한 사람이 여러 사람 앞에서 자기 생각을 알리는 말하기","mis":"K6-1-u3-X03"},{"t":"목소리가 큰 쪽이 이기는 말하기","mis":"K6-1-u3-X09"}],"explanation":["편 없이 방법을 모으는 것은 토의예요.","혼자 알리는 말하기는 토론이 아니에요.","찬반으로 나뉘어 근거를 들어 겨뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#2','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C1',1,'mc','auto','다음 가운데 토론이 필요한 상황은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":2,"concept":"K6-1-u3-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 토론이 필요한 상황은 어느 것인가요?","options":[{"t":"학교 앞 도로에 과속 방지 턱을 더 놓을지 정하기","correct":true},{"t":"우리 학교가 문을 연 해가 언제인지 알아보기","mis":"K6-1-u3-X01"},{"t":"교실 온도가 몇 도인지 재어 보기","mis":"K6-1-u3-X01"},{"t":"불이 났을 때 대피하는 길 익히기","mis":"K6-1-u3-X01"}],"explanation":["문을 연 해는 찾아보면 확인돼요.","온도는 재면 알 수 있어요.","찬반으로 갈리는 문제라야 토론이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#3','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C4',1,'match','auto','말한 내용과 그 층을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K6-1-u3-C4","difficulty":1,"kind":"match","stem":"말한 내용과 그 층을 알맞게 이으세요.","pairs":[{"l":"학교 앞 도로의 제한 속도를 낮춰야 합니다","r":"주장"},{"l":"차가 빠르면 아이들이 피할 시간이 없기 때문입니다","r":"이유"},{"l":"우리 시가 지난해 낸 어린이 보행 사고 통계","r":"근거"}],"mis":"K6-1-u3-X04","explanation":["내세우는 생각은 주장이에요.","그렇게 생각한 까닭은 이유예요.","밖에서 가져온 자료는 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#4','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C2',1,'ox','auto','토의와 토론의 가장 큰 다른 점은 찬성과 반대로 편이 갈리는가예요.',ARRAY['K6-1-u3-X02']::text[],false,'{"seq":4,"concept":"K6-1-u3-C2","difficulty":1,"kind":"ox","stem":"토의와 토론의 가장 큰 다른 점은 찬성과 반대로 편이 갈리는가예요.","answer":"O","reason_options":[{"t":"토의는 편을 나누지 않고 방법을 모으고, 토론은 찬반으로 나뉘어 겨루기 때문에","correct":true},{"t":"토의는 혼자 하고 토론은 여럿이 하기 때문에","mis":"K6-1-u3-X02"}],"mis":"K6-1-u3-X02","explanation":["둘 다 여럿이 함께 이야기해요.","둘 다 문제를 해결하려고 해요.","다른 점은 찬반으로 편이 갈리는가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#5','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C5',2,'mc','auto','토론의 네 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":5,"concept":"K6-1-u3-C5","difficulty":2,"kind":"mc","stem":"토론의 네 단계를 차례대로 바르게 늘어놓은 것은 어느 것인가요?","options":[{"t":"주장 펼치기 → 반론하기 → 주장 다지기 → 판정하기","correct":true},{"t":"반론하기 → 주장 펼치기 → 판정하기 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"주장 펼치기 → 판정하기 → 반론하기 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기 → 주장 펼치기 → 반론하기 → 주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["먼저 주장을 내놓아야 되받을 수 있어요.","다지기는 반론 뒤에 해요.","판정은 맨 마지막이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#6','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C6',2,'mc','auto','토론에 참여하는 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X07','K6-1-u3-X08','K6-1-u3-X14']::text[],false,'{"seq":6,"concept":"K6-1-u3-C6","difficulty":2,"kind":"mc","stem":"토론에 참여하는 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 발언을 끝까지 듣고 메모한 뒤 말차례에 되받는다","correct":true},{"t":"허점이 보이면 말을 끊고 곧바로 지적한다","mis":"K6-1-u3-X07"},{"t":"상대가 무슨 말을 하든 준비한 원고를 그대로 읽는다","mis":"K6-1-u3-X08"},{"t":"상대 말투가 거슬리면 그 점부터 짚는다","mis":"K6-1-u3-X14"}],"explanation":["끼어들면 말차례가 무너져요.","듣지 않으면 되받을 수 없어요.","끝까지 듣고 메모한 뒤 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#7','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C1',2,'mc','auto','온유와 강토의 대화에서 토론이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X02','K6-1-u3-X09']::text[],false,'{"seq":7,"concept":"K6-1-u3-C1","difficulty":2,"kind":"mc","stem":"온유와 강토의 대화에서 토론이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 일을 두고 찬성과 반대로 생각이 갈리기 때문에","correct":true},{"t":"공원 넓이가 얼마인지 알아봐야 하기 때문에","mis":"K6-1-u3-X01"},{"t":"편을 나누지 않고 방법만 모으면 되기 때문에","mis":"K6-1-u3-X02"},{"t":"목소리가 큰 사람의 생각을 따르면 되기 때문에","mis":"K6-1-u3-X09"}],"explanation":["넓이는 재어 보면 알 수 있어요.","두 사람은 생각이 갈렸어요.","찬반으로 갈리면 토론이 필요해요."],"asset":{"type":"speech","turns":[{"who":"온유","text":"마을 공원 한쪽에 반려견 놀이터를 만들면 좋겠어. 목줄을 풀고 뛸 곳이 없어서 개들이 인도까지 나오잖아."},{"who":"강토","text":"나는 반대야. 공원은 모두가 쓰는 곳인데 한쪽을 떼어 주면 아이들이 뛸 곳이 줄어들어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#8','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C7',2,'ox','auto','토론은 상대를 어떻게든 눌러 이기는 것이 목적이에요.',ARRAY['K6-1-u3-X09']::text[],false,'{"seq":8,"concept":"K6-1-u3-C7","difficulty":2,"kind":"ox","stem":"토론은 상대를 어떻게든 눌러 이기는 것이 목적이에요.","answer":"X","reason_options":[{"t":"겨루는 방식이지만 목적은 더 합리적인 결정에 이르는 것이기 때문에","correct":true},{"t":"토론은 이기고 지는 것이 전부이기 때문에","mis":"K6-1-u3-X09"}],"mis":"K6-1-u3-X09","explanation":["토론은 찬반으로 겨뤄요.","그러나 누르는 것이 목적이 아니에요.","더 나은 답을 찾고 결과에 승복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#9','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C4',2,'mc','auto','「우리 구청이 낸 지난해 안전사고 통계입니다.」는 주장 · 이유 · 근거 가운데 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":9,"concept":"K6-1-u3-C4","difficulty":2,"kind":"mc","stem":"「우리 구청이 낸 지난해 안전사고 통계입니다.」는 주장 · 이유 · 근거 가운데 무엇인가요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"판정","mis":"K6-1-u3-X06"}],"explanation":["내세우는 생각이 아니에요.","내가 생각한 까닭도 아니에요.","밖에서 가져온 자료는 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_basic#10','kor',6,1,'u3','L01','g6_1_kor_u3_L01_basic','lesson_basic','K6-1-u3-C8',3,'mc','auto','교실 토론 주제로 가장 잘 맞는 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X10']::text[],false,'{"seq":10,"concept":"K6-1-u3-C8","difficulty":3,"kind":"mc","stem":"교실 토론 주제로 가장 잘 맞는 것은 어느 것인가요?","options":[{"t":"「우리 반 앉는 곳을 한 달마다 바꾸어야 한다.」처럼 무엇을 하자고 정하는 문제","correct":true},{"t":"「이 자료는 언제 만들어졌는가」처럼 찾아보면 곧바로 확인되는 물음","mis":"K6-1-u3-X01"},{"t":"세 갈래 가운데 어느 것인지 딱 잘라 나눌 수 있어야만 쓸 수 있는 문제","mis":"K6-1-u3-X10"},{"t":"「복도에서 뛰지 않는다」처럼 이미 지키기로 정해진 규칙","mis":"K6-1-u3-X01"}],"explanation":["확인되는 물음은 토론이 안 돼요.","갈래를 딱 잘라 나눌 필요는 없어요.","우리가 바꿔 볼 수 있는 일이 잘 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#1','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C2',2,'mc','auto','「학예회에서 우리 반이 무엇을 할지 아이디어 모으기」에 알맞은 말하기는 어느 것인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":2,"kind":"mc","stem":"「학예회에서 우리 반이 무엇을 할지 아이디어 모으기」에 알맞은 말하기는 어느 것인가요?","options":[{"t":"토의 — 편을 나누지 않고 함께 방법을 찾는 일이므로","correct":true},{"t":"토론 — 여럿이 함께 이야기하므로","mis":"K6-1-u3-X02"},{"t":"토론 — 문제를 해결하려는 말하기이므로","mis":"K6-1-u3-X02"},{"t":"연설 — 한 사람이 정해서 알리므로","mis":"K6-1-u3-X03"}],"explanation":["여럿이 이야기하는 건 토의도 같아요.","문제를 해결하려는 것도 같아요.","편이 갈리지 않으니 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#2','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',2,'ox','auto','「목줄을 풀 곳이 없어 인도에서 사고가 나기 쉽기 때문입니다.」는 근거예요.',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":2,"kind":"ox","stem":"「목줄을 풀 곳이 없어 인도에서 사고가 나기 쉽기 때문입니다.」는 근거예요.","answer":"X","reason_options":[{"t":"그렇게 주장하는 까닭이므로 이유이고, 근거는 밖에서 가져온 객관적인 자료이기 때문에","correct":true},{"t":"까닭을 말하는 문장도 모두 근거이기 때문에","mis":"K6-1-u3-X04"}],"mis":"K6-1-u3-X04","explanation":["「~때문입니다」는 까닭이에요.","까닭은 이유예요.","근거는 확인할 수 있는 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#3','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C3',3,'error','auto','토론에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":3,"concept":"K6-1-u3-C3","difficulty":3,"kind":"error","stem":"토론에 대해 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"하율 — 「토론은 편을 나누지 않고 의견을 모아 더 나은 안을 만드는 말하기야.」","correct":true,"mis_target":"K6-1-u3-X02"},{"t":"서진 — 「토론은 찬반으로 나뉘어 근거를 들어 말해.」","mis":"K6-1-u3-X03"},{"t":"라온 — 「토의와 토론 모두 문제를 해결하려고 함께 이야기해.」","mis":"K6-1-u3-X02"}],"explanation":["서진은 토론의 뜻을 바르게 말했어요.","라온은 같은 점을 바르게 말했어요.","하율이 말한 것은 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#4','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C5',3,'mc','auto','상대 주장의 잘못된 곳을 짚고, 그에 답하는 단계는 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":4,"concept":"K6-1-u3-C5","difficulty":3,"kind":"mc","stem":"상대 주장의 잘못된 곳을 짚고, 그에 답하는 단계는 어느 것인가요?","options":[{"t":"반론하기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["주장 펼치기는 처음 내놓는 단계예요.","다지기는 다시 세우는 단계예요.","되받는 단계는 반론하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#5','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C6',3,'mc','auto','경청을 「예의이면서 실력」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X08','K6-1-u3-X07']::text[],false,'{"seq":5,"concept":"K6-1-u3-C6","difficulty":3,"kind":"mc","stem":"경청을 「예의이면서 실력」이라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"상대 말을 끝까지 들어야 무엇을 되받을지 알 수 있기 때문에","correct":true},{"t":"듣는 척만 해도 판정단이 좋게 보기 때문에","mis":"K6-1-u3-X16"},{"t":"준비한 원고만 잘 읽으면 되기 때문에","mis":"K6-1-u3-X08"},{"t":"상대 말이 끝나기 전에 끼어들어야 이기기 때문에","mis":"K6-1-u3-X07"}],"explanation":["판정은 기준으로 해요.","원고만 읽으면 되받을 수 없어요.","들어야 날카롭게 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#6','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C8',3,'mc','auto','어떤 문제가 토론 주제가 되는지에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X10','K6-1-u3-X01']::text[],false,'{"seq":6,"concept":"K6-1-u3-C8","difficulty":3,"kind":"mc","stem":"어떤 문제가 토론 주제가 되는지에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"갈래를 딱 잘라 나눌 필요는 없고, 무엇을 하자고 정하는 문제가 교실 토론에 잘 맞는다","correct":true},{"t":"갈래를 반드시 딱 잘라 나눌 수 있어야 토론할 수 있다","mis":"K6-1-u3-X10"},{"t":"자료를 찾으면 곧바로 답이 나오는 물음이 가장 좋은 주제다","mis":"K6-1-u3-X01"},{"t":"답이 이미 정해진 규칙일수록 토론하기 좋다","mis":"K6-1-u3-X01"}],"explanation":["갈래는 딱 잘라 나누지 않아도 돼요.","확인되는 물음은 토론이 안 돼요.","우리가 바꿔 볼 수 있는 일이 잘 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#7','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C7',3,'mc','auto','「서로 겨루어 보면 더 나은 답이 드러난다」라고 여기는 사람의 행동으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X14','K6-1-u3-X18']::text[],false,'{"seq":7,"concept":"K6-1-u3-C7","difficulty":3,"kind":"mc","stem":"「서로 겨루어 보면 더 나은 답이 드러난다」라고 여기는 사람의 행동으로 알맞은 것은 어느 것인가요?","options":[{"t":"근거를 겨누고, 판정 결과에 승복한다","correct":true},{"t":"말이 거칠어져도 상대를 끝까지 누른다","mis":"K6-1-u3-X09"},{"t":"상대의 말투를 짚어 기를 꺾는다","mis":"K6-1-u3-X14"},{"t":"판정이 마음에 들지 않으면 따르지 않는다","mis":"K6-1-u3-X18"}],"explanation":["누르려 하면 말이 거칠어져요.","말투가 아니라 근거를 겨눠요.","결과에 승복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#8','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',4,'mc','auto','온유의 주장에 붙일 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05','K6-1-u3-X28']::text[],false,'{"seq":8,"concept":"K6-1-u3-C4","difficulty":4,"kind":"mc","stem":"온유의 주장에 붙일 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"구청이 지난해 낸 공원 주변 반려견 안전사고 자료","correct":true},{"t":"개들이 뛰어놀면 귀여울 것 같다는 내 느낌","mis":"K6-1-u3-X04"},{"t":"반려견 놀이터를 만들어야 한다는 말을 한 번 더 하기","mis":"K6-1-u3-X05"},{"t":"어디서 봤는지 모르는 동영상 이야기","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","주장을 되풀이한 것은 근거가 아니에요.","누가 언제 낸 자료인지 확인돼야 해요."],"asset":{"type":"speech","turns":[{"who":"온유","text":"마을 공원 한쪽에 반려견 놀이터를 만들면 좋겠어. 목줄을 풀고 뛸 곳이 없어서 개들이 인도까지 나오잖아."},{"who":"강토","text":"나는 반대야. 공원은 모두가 쓰는 곳인데 한쪽을 떼어 주면 아이들이 뛸 곳이 줄어들어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#9','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C2',4,'essay','teacher','토의와 토론이 어떻게 같고 어떻게 다른지 쓰고, 각각에 알맞은 예를 하나씩 드세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C2","difficulty":4,"kind":"essay","stem":"토의와 토론이 어떻게 같고 어떻게 다른지 쓰고, 각각에 알맞은 예를 하나씩 드세요.","answer_guide":{"answer":"예: 토의와 토론은 둘 다 문제를 해결하려고 여럿이 함께 이야기한다는 점이 같다. 다른 점은 찬반으로 편이 갈리는가이다. 토의는 편을 나누지 않고 의견을 모아 더 나은 방법을 찾는다. 예를 들어 학예회에서 우리 반이 무엇을 할지 아이디어를 모으는 일이다. 토론은 찬성 측과 반대 측으로 나뉘어 근거를 들어 자기 주장이 옳음을 밝힌다. 예를 들어 공원에 반려견 놀이터를 만들어야 하는가를 두고 겨루는 일이다.","scoring_points":["같은 점을 썼는가","찬반으로 편이 갈리는가로 다른 점을 썼는가","토의와 토론의 예를 하나씩 알맞게 들었는가"]},"explanation":["함께 이야기한다는 점은 같아요.","편이 갈리는지 살펴요.","예를 하나씩 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L01_challenge#10','kor',6,1,'u3','L01','g6_1_kor_u3_L01_challenge','lesson_challenge','K6-1-u3-C4',4,'essay','teacher','「공원에 반려견 놀이터를 만들어야 한다」라는 주장에 이유와 근거를 하나씩 붙여 쓰고, 이유와 근거가 어떻게 다른지 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C4","difficulty":4,"kind":"essay","stem":"「공원에 반려견 놀이터를 만들어야 한다」라는 주장에 이유와 근거를 하나씩 붙여 쓰고, 이유와 근거가 어떻게 다른지 설명하세요.","answer_guide":{"answer":"예: 이유 — 목줄을 풀 곳이 없어 개들이 인도까지 나와 사고가 나기 쉽기 때문이다. 근거 — 우리 구청이 지난해 낸 공원 주변 안전사고 통계이다. 이유는 그렇게 주장하는 까닭으로 내 머릿속에서 나온 문장이고, 근거는 그 이유를 뒷받침하는 객관적인 자료로 밖에서 가져와 누가 언제 냈는지 확인할 수 있는 것이다.","scoring_points":["주장에 이어지는 이유를 썼는가","확인할 수 있는 근거를 썼는가","이유와 근거의 차이를 바르게 설명했는가"]},"explanation":["까닭을 먼저 써요.","밖에서 가져온 자료를 붙여요.","내 까닭과 밖의 자료로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#1','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C9',1,'mc','auto','주장 펼치기에서 함께 내야 하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X06']::text[],false,'{"seq":1,"concept":"K6-1-u3-C9","difficulty":1,"kind":"mc","stem":"주장 펼치기에서 함께 내야 하는 것은 어느 것인가요?","options":[{"t":"주장 · 이유 · 근거","correct":true},{"t":"주장만","mis":"K6-1-u3-X05"},{"t":"반론과 답변","mis":"K6-1-u3-X06"},{"t":"판정 기준","mis":"K6-1-u3-X06"}],"explanation":["주장만 내면 확인할 수 없어요.","반론은 다음 단계예요.","세 층이 다 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#2','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C10',1,'mc','auto','근거가 될 수 있는 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":2,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"근거가 될 수 있는 것은 어느 것인가요?","options":[{"t":"우리 학교 고학년 백스무 명에게 물은 설문 결과","correct":true},{"t":"운동장이 좁아서 답답하다고 느낀다","mis":"K6-1-u3-X04"},{"t":"나누어 쓰면 더 재미없을 것 같다","mis":"K6-1-u3-X04"},{"t":"운동장은 나누어 써야 한다","mis":"K6-1-u3-X05"}],"explanation":["느낌은 이유에 가까워요.","「같다」로 끝나는 말은 근거가 아니에요.","확인할 수 있는 설문은 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#3','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C13',1,'ox','auto','반론할 때에는 「그것도 모르십니까?」처럼 말해도 돼요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":3,"concept":"K6-1-u3-C13","difficulty":1,"kind":"ox","stem":"반론할 때에는 「그것도 모르십니까?」처럼 말해도 돼요.","answer":"X","reason_options":[{"t":"반론은 사람이 아니라 주장 · 이유 · 근거를 겨누어야 하기 때문에","correct":true},{"t":"날카롭게 말해야 반론이 세지기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["그 말은 사람을 겨눠요.","토론은 공식적인 말하기예요.","근거를 겨누어 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#4','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C15',1,'mc','auto','판정할 때 가장 먼저 있어야 하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X16']::text[],false,'{"seq":4,"concept":"K6-1-u3-C15","difficulty":1,"kind":"mc","stem":"판정할 때 가장 먼저 있어야 하는 것은 어느 것인가요?","options":[{"t":"무엇을 보고 정할지 미리 밝혀 둔 명확한 판정 기준","correct":true},{"t":"판정단이 평소 어느 쪽 생각에 가까웠는지","mis":"K6-1-u3-X16"},{"t":"어느 쪽이 더 큰 목소리로 말했는지","mis":"K6-1-u3-X16"},{"t":"어느 쪽 토론자 수가 더 많은지","mis":"K6-1-u3-X16"}],"explanation":["평소 생각은 판정과 관계없어요.","목소리 크기는 기준이 아니에요.","기준이 없으면 판정이 아니라 취향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#5','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C10',2,'match','auto','운동장 토론의 발언을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u3-C10","difficulty":2,"kind":"match","stem":"운동장 토론의 발언을 알맞게 이으세요.","pairs":[{"l":"부딪히는 사고가 자주 일어난다","r":"찬성 측 이유"},{"l":"학생 회의가 조사한 보건실 이용 자료","r":"찬성 측 근거"},{"l":"학년이 섞여 노는 놀이가 사라진다","r":"반대 측 이유"},{"l":"이름을 밝히지 않은 선생님의 말","r":"반대 측 근거"}],"mis":"K6-1-u3-X04","explanation":["까닭인지 자료인지 먼저 나눠요.","그다음 찬반을 갈라요.","이유 아래에 근거가 놓여요."],"asset":{"type":"speech","turns":[{"who":"사회자 라온","text":"지금부터 「점심시간 운동장은 학년별로 나누어 써야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 벼리","text":"점심시간 운동장은 학년별로 나누어 써야 합니다. 모든 학년이 한꺼번에 나오면 부딪히는 사고가 자주 일어나기 때문입니다. 학생 회의가 지난 학기에 조사한 보건실 이용 자료를 보면, 운동장에서 부딪혀 다친 학생이 예순두 명이었습니다."},{"who":"반대 측 새얀","text":"운동장을 학년별로 나누어서는 안 됩니다. 학년이 섞여 노는 놀이가 사라지기 때문입니다. 저희가 만난 어느 선생님께서도 학년이 섞여 놀 때 아이들이 서로 배우는 것이 많다고 하셨습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#6','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C11',2,'mc','auto','새얀이의 첫 반론이 겨눈 곳은 어디인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X11','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"새얀이의 첫 반론이 겨눈 곳은 어디인가요?","options":[{"t":"찬성 측 근거 — 보건실 자료만으로는 학년이 섞였기 때문인지 알 수 없다는 점","correct":true},{"t":"벼리의 말투","mis":"K6-1-u3-X14"},{"t":"급식실 이야기","mis":"K6-1-u3-X11"},{"t":"반대 측 자신의 주장","mis":"K6-1-u3-X06"}],"explanation":["말투를 겨누지 않았어요.","새 이야기를 꺼내지 않았어요.","찬성 측 근거를 겨누었어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#7','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C14',2,'mc','auto','주장 다지기에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X06']::text[],false,'{"seq":7,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"주장 다지기에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"앞 두 단계에서 남은 것을 추려 자기편 주장을 다시 세운다","correct":true},{"t":"주장 펼치기에서 한 말을 그대로 되풀이한다","mis":"K6-1-u3-X15"},{"t":"반론에서 무너진 근거도 다시 꺼내 힘준다","mis":"K6-1-u3-X15"},{"t":"상대 주장을 처음으로 되받는다","mis":"K6-1-u3-X06"}],"explanation":["되풀이하는 단계가 아니에요.","무너진 근거를 꺼내면 약해져요.","남은 것을 추려 다시 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#8','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C17',2,'mc','auto','토론에서 해도 되는 말은 어느 것인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X11','K6-1-u3-X07']::text[],false,'{"seq":8,"concept":"K6-1-u3-C17","difficulty":2,"kind":"mc","stem":"토론에서 해도 되는 말은 어느 것인가요?","options":[{"t":"「말씀 잘 들었습니다. 다만 한 가지 여쭙겠습니다.」","correct":true},{"t":"「운동장 나누자고? 말도 안 돼.」","mis":"K6-1-u3-X14"},{"t":"「그런데 저는 요즘 급식이 더 문제라고 봅니다.」","mis":"K6-1-u3-X11"},{"t":"상대가 말하는 중간에 끼어들어 되받는 말","mis":"K6-1-u3-X07"}],"explanation":["반말로 깎아내리면 안 돼요.","주제와 상관없는 말이에요.","말차례를 지키고 높임말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#9','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C16',2,'ox','auto','판정 결과는 어느 쪽 생각이 옳은지를 가려 주는 것이에요.',ARRAY['K6-1-u3-X17']::text[],false,'{"seq":9,"concept":"K6-1-u3-C16","difficulty":2,"kind":"ox","stem":"판정 결과는 어느 쪽 생각이 옳은지를 가려 주는 것이에요.","answer":"X","reason_options":[{"t":"정해 둔 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지를 정하는 일이기 때문에","correct":true},{"t":"판정단은 언제나 옳은 답을 알기 때문에","mis":"K6-1-u3-X17"}],"mis":"K6-1-u3-X17","explanation":["토론이 끝나도 두 생각은 남아요.","기준이 달라지면 결과도 달라져요.","더 설득력 있게 말한 쪽을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_basic#10','kor',6,1,'u3','L02','g6_1_kor_u3_L02_basic','lesson_basic','K6-1-u3-C12',3,'mc','auto','벼리가 새얀이의 반론에 답한 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"벼리가 새얀이의 반론에 답한 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"인정할 것은 인정하고, 서로 다른 학년 사이 마흔한 건이라는 자료로 다시 세웠다","correct":true},{"t":"물은 것에 답하지 않고 「안전하니까 나눠야 합니다」만 되풀이했다","mis":"K6-1-u3-X13"},{"t":"새얀이의 말투를 문제 삼았다","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼내 말을 돌렸다","mis":"K6-1-u3-X11"}],"explanation":["벼리는 물은 것에 곧바로 답했어요.","사람을 겨누지 않았어요.","인정하고 자료로 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#1','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C11',2,'mc','auto','반론하기에서 오간 말을 정리하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X11','K6-1-u3-X38']::text[],false,'{"seq":1,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"반론하기에서 오간 말을 정리하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"발언을 그대로 옮기지 않고 핵심만 요약한다","correct":true},{"t":"상대 발언을 한 글자도 빠짐없이 옮겨 적는다","mis":"K6-1-u3-X12"},{"t":"주장 펼치기에 나오지 않은 새 이야기도 함께 되받는다","mis":"K6-1-u3-X11"},{"t":"상대의 표정까지 자세히 적는다","mis":"K6-1-u3-X38"}],"explanation":["다 옮기면 다음 말을 놓쳐요.","펼친 내용에 대해서만 되받아요.","핵심만 요약해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#2','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C14',2,'ox','auto','주장 다지기에서는 「요컨대」, 「따라서」 같은 말을 써서 짧고 힘 있게 말하면 좋아요.',ARRAY['K6-1-u3-X15']::text[],false,'{"seq":2,"concept":"K6-1-u3-C14","difficulty":2,"kind":"ox","stem":"주장 다지기에서는 「요컨대」, 「따라서」 같은 말을 써서 짧고 힘 있게 말하면 좋아요.","answer":"O","reason_options":[{"t":"정리하는 단계라는 표시가 되고 중심이 또렷해지기 때문에","correct":true},{"t":"같은 말을 여러 번 되풀이할수록 설득력이 커지기 때문에","mis":"K6-1-u3-X15"}],"mis":"K6-1-u3-X15","explanation":["이어 주는 말은 정리의 표시예요.","짧게 말하면 중심이 또렷해요.","되풀이가 아니라 다시 세우기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#3','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C16',3,'mc','auto','윤재의 판정에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X18','K6-1-u3-X16']::text[],false,'{"seq":3,"concept":"K6-1-u3-C16","difficulty":3,"kind":"mc","stem":"윤재의 판정에서 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"정한 두 기준으로 보아 찬성 측이 더 설득력 있었다는 것이지, 반대 측 생각이 틀렸다는 뜻은 아니다","correct":true},{"t":"반대 측 생각은 틀렸으니 버려야 한다","mis":"K6-1-u3-X17"},{"t":"판정이 마음에 들지 않으면 반대 측은 따르지 않아도 된다","mis":"K6-1-u3-X18"},{"t":"윤재가 평소 찬성 측 생각이어서 찬성 측을 골랐다","mis":"K6-1-u3-X16"}],"explanation":["판정은 옳고 그름을 가리지 않아요.","결과에 승복해요.","윤재는 기준을 밝히고 정했어요."],"asset":{"type":"speech","turns":[{"who":"판정단 윤재","text":"저희는 두 가지 기준으로 보았습니다. 첫째, 주장에 대한 타당한 이유를 냈는가. 둘째, 객관적이고 믿을 수 있는 근거를 냈는가."},{"who":"판정단 윤재","text":"두 기준으로 볼 때 찬성 측이 조금 더 설득력 있었다고 판정합니다. 반대 측의 이유는 충분히 공감이 갔지만 근거로 든 말의 출처가 확인되지 않았습니다. 반대 측이 안전을 다르게 지킬 방법을 낸 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#4','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C13',3,'error','auto','반론하는 말을 했어요. 알맞지 않은 말을 한 친구는 누구인가요?',ARRAY['K6-1-u3-X14','K6-1-u3-X29','K6-1-u3-X27']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":3,"kind":"error","stem":"반론하는 말을 했어요. 알맞지 않은 말을 한 친구는 누구인가요?","options":[{"t":"가온 — 「그렇게 준비도 안 하고 토론에 나온 것이 이해가 안 됩니다.」","correct":true,"mis_target":"K6-1-u3-X14"},{"t":"보미 — 「그 자료는 조사한 때가 나와 있지 않습니다.」","mis":"K6-1-u3-X29"},{"t":"지안 — 「그 이유는 주장과 이어지지 않아 보입니다.」","mis":"K6-1-u3-X27"}],"explanation":["보미는 근거를 겨누었어요.","지안은 이유를 겨누었어요.","가온은 사람을 겨누었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#5','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C12',3,'mc','auto','「그 자료는 언제 조사했는지 나와 있지 않습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":5,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"「그 자료는 언제 조사했는지 나와 있지 않습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「지난 학기에 학생 회의가 조사한 자료입니다. 조사한 때는 자료 맨 위에 적혀 있습니다.」","correct":true},{"t":"「어쨌든 저희 주장이 맞습니다.」","mis":"K6-1-u3-X13"},{"t":"「그런 것까지 따지는 건 예의가 아닙니다.」","mis":"K6-1-u3-X14"},{"t":"「그런데 요즘은 급식이 더 문제입니다.」","mis":"K6-1-u3-X11"}],"explanation":["되풀이는 답변이 아니에요.","반론한 사람을 겨누면 안 돼요.","물은 그 지점에 곧바로 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#6','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C10',3,'mc','auto','새얀이가 근거로 든 「어느 선생님」의 말이 힘을 잃은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X27','K6-1-u3-X16']::text[],false,'{"seq":6,"concept":"K6-1-u3-C10","difficulty":3,"kind":"mc","stem":"새얀이가 근거로 든 「어느 선생님」의 말이 힘을 잃은 까닭은 무엇인가요?","options":[{"t":"누구의 말인지 밝히지 않아 확인할 수 없기 때문에","correct":true},{"t":"선생님의 말은 언제나 근거로 쓸 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"반대 측 이유와 상관없는 이야기였기 때문에","mis":"K6-1-u3-X27"},{"t":"새얀이의 목소리가 작았기 때문에","mis":"K6-1-u3-X16"}],"explanation":["전문가의 말도 근거가 될 수 있어요.","이유와는 이어졌어요.","누구의 말인지 밝혀야 해요."],"asset":{"type":"speech","turns":[{"who":"반대 측 새얀","text":"보건실을 찾은 학생 수만으로는 학년이 섞였기 때문인지 알 수 없습니다. 같은 학년끼리 부딪힌 경우는 몇 건이었습니까?"},{"who":"찬성 측 벼리","text":"좋은 지적입니다. 같은 학년끼리 부딪힌 경우도 있었습니다. 다만 그 가운데 마흔한 건이 서로 다른 학년 사이에서 일어났습니다."},{"who":"찬성 측 벼리","text":"반대 측께 묻겠습니다. 근거로 드신 선생님이 어느 분인지 밝히지 않으셨습니다. 확인할 수 없는 말은 근거로 삼기 어렵지 않습니까?"},{"who":"반대 측 새얀","text":"성함까지 적어 두지는 못했습니다. 다만 여러 해 아이들을 보아 오신 분입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#7','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C5',3,'match','auto','단계와 그 단계에서 하는 일을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K6-1-u3-C5","difficulty":3,"kind":"match","stem":"단계와 그 단계에서 하는 일을 이으세요.","pairs":[{"l":"주장과 이유, 근거를 처음으로 내놓는다","r":"주장 펼치기"},{"l":"상대 근거의 허점을 짚고 그에 답한다","r":"반론하기"},{"l":"남은 것만 추려 자기편 주장을 다시 강조한다","r":"주장 다지기"},{"l":"기준을 밝히고 더 설득력 있는 쪽을 정한다","r":"판정하기"}],"mis":"K6-1-u3-X06","explanation":["처음 내놓는 단계부터 찾아요.","되받는 단계와 다시 세우는 단계를 갈라요.","정하는 단계는 맨 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#8','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C14',4,'mc','auto','벼리와 새얀이의 주장 다지기를 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14']::text[],false,'{"seq":8,"concept":"K6-1-u3-C14","difficulty":4,"kind":"mc","stem":"벼리와 새얀이의 주장 다지기를 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"벼리는 반론에서 확인된 마흔한 건을 추려 다시 세웠고, 새얀이는 안전을 지킬 다른 방법으로 자기 주장을 다졌다","correct":true},{"t":"두 사람 모두 처음 한 말을 그대로 되풀이했을 뿐이다","mis":"K6-1-u3-X15"},{"t":"새얀이는 확인되지 않은 선생님 말을 다시 꺼내 힘을 더했다","mis":"K6-1-u3-X15"},{"t":"주장 다지기에서는 상대 말투를 짚는 것이 가장 중요하다","mis":"K6-1-u3-X14"}],"explanation":["두 사람은 되풀이하지 않았어요.","새얀이는 무너진 근거를 꺼내지 않았어요.","남은 것을 추려 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"요컨대 문제는 안전입니다. 서로 다른 학년 사이에서 일어난 마흔한 건은 학년을 나누면 줄어듭니다. 따라서 점심시간 운동장은 학년별로 나누어 써야 합니다."},{"who":"반대 측 새얀","text":"저희가 지키려는 것은 함께 노는 시간입니다. 안전은 나누지 않고도 지킬 수 있습니다. 뛰는 곳과 공놀이하는 곳을 갈라 놓으면 됩니다. 따라서 운동장을 학년별로 나눌 필요는 없습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#9','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C13',4,'essay','teacher','반론이 「사람을 겨누지 않고 주장 · 이유 · 근거를 겨누어야 한다」는 것이 무슨 뜻인지 설명하고, 운동장 토론에서 반대 측 근거를 겨누는 반론을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C13","difficulty":4,"kind":"essay","stem":"반론이 「사람을 겨누지 않고 주장 · 이유 · 근거를 겨누어야 한다」는 것이 무슨 뜻인지 설명하고, 운동장 토론에서 반대 측 근거를 겨누는 반론을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 반론은 상대가 내놓은 주장이나 이유, 근거에서 잘못되거나 궁금한 곳을 짚는 것이지, 상대가 준비를 못 했다거나 말투가 거슬린다고 말하는 것이 아니다. 토론은 공식적인 말하기라 높임말을 쓰고 공격적인 말투를 피한다. 반론 — 「근거로 드신 선생님의 말은 어느 분이 언제 하신 말인지 밝혀지지 않아 확인하기 어렵습니다.」","scoring_points":["사람이 아니라 주장 · 이유 · 근거를 겨눈다는 뜻을 썼는가","높임말 · 존중하는 태도를 썼는가","반대 측 근거를 겨누는 반론을 높임말로 썼는가"]},"explanation":["겨누는 곳이 어디인지 써요.","공식적인 말하기임을 떠올려요.","근거의 허점을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L02_challenge#10','kor',6,1,'u3','L02','g6_1_kor_u3_L02_challenge','lesson_challenge','K6-1-u3-C15',4,'essay','teacher','판정할 때 명확한 기준이 왜 먼저 있어야 하는지 쓰고, 「판정 결과가 늘 옳은 것은 아니다」라는 말의 뜻을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C15","difficulty":4,"kind":"essay","stem":"판정할 때 명확한 기준이 왜 먼저 있어야 하는지 쓰고, 「판정 결과가 늘 옳은 것은 아니다」라는 말의 뜻을 설명하세요.","answer_guide":{"answer":"예: 무엇을 보고 정했는지 밝히지 않으면 판정이 판정단의 취향이 되어 토론자가 결과에 승복하기 어렵다. 그래서 「타당한 이유를 냈는가 · 믿을 수 있는 근거를 냈는가」처럼 기준을 먼저 밝혀야 한다. 판정은 어느 쪽 생각이 옳은지 가리는 일이 아니라 정한 기준으로 볼 때 어느 쪽이 더 설득력 있게 말했는지 정하는 일이다. 그래서 기준이 달라지면 결과도 달라질 수 있고, 판정 뒤에도 두 생각은 그대로 남는다.","scoring_points":["기준이 없으면 취향이 되고 승복하기 어렵다는 점을 썼는가","판정은 더 설득력 있게 말한 쪽을 정하는 일임을 썼는가","기준에 따라 결과가 달라질 수 있음을 썼는가"]},"explanation":["기준이 없을 때를 떠올려요.","판정이 무엇을 정하는지 써요.","기준이 바뀌면 어떻게 될지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#1','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C18',1,'mc','auto','우리 반 토론 주제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C18","difficulty":1,"kind":"mc","stem":"우리 반 토론 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"청소 당번을 제비뽑기로 정할 것인가","correct":true},{"t":"우리 반 학생 수가 몇 명인가","mis":"K6-1-u3-X01"},{"t":"지난주 급식 식단에 무엇이 나왔는가","mis":"K6-1-u3-X01"},{"t":"복도에서 뛰지 말아야 하는가","mis":"K6-1-u3-X01"}],"explanation":["학생 수는 세어 보면 알아요.","식단은 찾아보면 확인돼요.","찬반이 갈리고 우리가 바꿔 볼 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#2','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C23',1,'match','auto','역할과 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K6-1-u3-C23","difficulty":1,"kind":"match","stem":"역할과 할 일을 알맞게 이으세요.","pairs":[{"l":"주제와 규칙을 알리고 말차례를 이끈다","r":"사회자"},{"l":"근거를 들어 간결하고 분명하게 주장한다","r":"토론자"},{"l":"기준을 정해 공정하게 판정한다","r":"판정단"},{"l":"메모하며 듣고 잘한 곳을 짚어 준다","r":"청중"}],"mis":"K6-1-u3-X25","explanation":["이끄는 사람은 사회자예요.","말하는 사람은 토론자예요.","정하는 사람은 판정단, 듣고 짚는 사람은 청중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#3','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C22',1,'ox','auto','예상되는 상대측 반론과 답변을 미리 적어 보는 일은 건너뛰어도 돼요.',ARRAY['K6-1-u3-X23']::text[],false,'{"seq":3,"concept":"K6-1-u3-C22","difficulty":1,"kind":"ox","stem":"예상되는 상대측 반론과 답변을 미리 적어 보는 일은 건너뛰어도 돼요.","answer":"X","reason_options":[{"t":"적어 보는 동안 내 근거의 약한 곳이 먼저 보이기 때문에","correct":true},{"t":"토론에서는 그때그때 떠오르는 대로 답하면 되기 때문에","mis":"K6-1-u3-X23"}],"mis":"K6-1-u3-X23","explanation":["상대의 반론을 미리 떠올려요.","내 근거의 약한 곳이 보여요.","그래서 건너뛰지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#4','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C21',1,'mc','auto','전문가의 의견을 근거로 쓸 때 반드시 함께 적어 둘 것은 어느 것인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X04','K6-1-u3-X22']::text[],false,'{"seq":4,"concept":"K6-1-u3-C21","difficulty":1,"kind":"mc","stem":"전문가의 의견을 근거로 쓸 때 반드시 함께 적어 둘 것은 어느 것인가요?","options":[{"t":"누구의 말인지","correct":true},{"t":"그 사람의 목소리","mis":"K6-1-u3-X38"},{"t":"내가 그 말을 좋아하는지","mis":"K6-1-u3-X04"},{"t":"아무것도 적지 않아도 된다","mis":"K6-1-u3-X22"}],"explanation":["목소리는 근거와 상관없어요.","내 마음은 근거가 아니에요.","누구의 말인지 적어야 확인돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#5','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C20',2,'mc','auto','준비표의 「우리 반 스물여섯 명에게 물어보니 …」는 어느 층인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X04','K6-1-u3-X13']::text[],false,'{"seq":5,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"준비표의 「우리 반 스물여섯 명에게 물어보니 …」는 어느 층인가요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X05"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"우리 측 답변","mis":"K6-1-u3-X13"}],"explanation":["하자고 내세운 말이 아니에요.","까닭을 말한 문장도 아니에요.","물어서 센 자료는 근거예요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 청소 당번은 제비뽑기로 정해야 한다.","주장 — 청소 당번은 제비뽑기로 정해야 합니다.","이유 — 힘든 곳을 늘 같은 사람이 맡게 되는 일을 막을 수 있기 때문입니다.","근거 — 우리 반 스물여섯 명에게 물어보니, 지난 학기에 화장실 청소를","세 번 넘게 맡은 학생이 아홉 명이었습니다.","예상 반론 — 제비뽑기는 잘 맞는 일을 못 살립니다.","우리 측 답변 — 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다."],"title":"찬성 측 토론 준비표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#6','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C19',2,'mc','auto','토론 주제가 정해진 뒤 가장 먼저 할 일은 어느 것인가요?',ARRAY['K6-1-u3-X20','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C19","difficulty":2,"kind":"mc","stem":"토론 주제가 정해진 뒤 가장 먼저 할 일은 어느 것인가요?","options":[{"t":"모두가 자기 생각을 먼저 정한다","correct":true},{"t":"사회자와 판정단부터 뽑는다","mis":"K6-1-u3-X20"},{"t":"친한 친구끼리 한편이 된다","mis":"K6-1-u3-X20"},{"t":"곧바로 판정 기준을 발표한다","mis":"K6-1-u3-X06"}],"explanation":["역할은 그다음에 나눠요.","친한 사이로 편을 정하지 않아요.","먼저 모두가 자기 생각을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#7','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C22',2,'mc','auto','준비표의 「우리 측 답변」이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"준비표의 「우리 측 답변」이 알맞은 까닭은 무엇인가요?","options":[{"t":"「잘 맞는 일을 못 살린다」는 반론에 서로 바꿀 수 있게 하는 방법으로 곧바로 답했기 때문에","correct":true},{"t":"「어쨌든 공평하다」고만 했기 때문에","mis":"K6-1-u3-X13"},{"t":"반론과 상관없는 이야기를 했기 때문에","mis":"K6-1-u3-X11"},{"t":"반론한 친구의 말투를 짚었기 때문에","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답변이 아니에요.","반론과 이어지게 답해요.","물은 그 지점에 곧바로 답했어요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 청소 당번은 제비뽑기로 정해야 한다.","주장 — 청소 당번은 제비뽑기로 정해야 합니다.","이유 — 힘든 곳을 늘 같은 사람이 맡게 되는 일을 막을 수 있기 때문입니다.","근거 — 우리 반 스물여섯 명에게 물어보니, 지난 학기에 화장실 청소를","세 번 넘게 맡은 학생이 아홉 명이었습니다.","예상 반론 — 제비뽑기는 잘 맞는 일을 못 살립니다.","우리 측 답변 — 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다."],"title":"찬성 측 토론 준비표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#8','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C25',2,'ox','auto','반론하기에서 감정이 앞설 때일수록 말차례를 기다리고 한 번에 한 가지만 되받아요.',ARRAY['K6-1-u3-X26']::text[],false,'{"seq":8,"concept":"K6-1-u3-C25","difficulty":2,"kind":"ox","stem":"반론하기에서 감정이 앞설 때일수록 말차례를 기다리고 한 번에 한 가지만 되받아요.","answer":"O","reason_options":[{"t":"지나치게 뜨거워지면 서로의 말이 들리지 않아 되받을 수도 없기 때문에","correct":true},{"t":"목소리를 높여야 상대가 물러서기 때문에","mis":"K6-1-u3-X26"}],"mis":"K6-1-u3-X26","explanation":["반론하기는 뜨거워지기 쉬워요.","듣지 못하면 되받을 수 없어요.","침착하게 한 가지씩 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#9','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C24',2,'mc','auto','진행 순서에서 「반대 측 반론과 찬성 측 답변」 바로 다음에 오는 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":9,"concept":"K6-1-u3-C24","difficulty":2,"kind":"mc","stem":"진행 순서에서 「반대 측 반론과 찬성 측 답변」 바로 다음에 오는 것은 어느 것인가요?","options":[{"t":"찬성 측 반론과 반대 측 답변","correct":true},{"t":"찬성 측 주장 펼치기","mis":"K6-1-u3-X06"},{"t":"판정단의 판정","mis":"K6-1-u3-X06"},{"t":"반대 측 주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["주장 펼치기는 이미 끝났어요.","판정은 맨 끝이에요.","이번에는 찬성 측이 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_basic#10','kor',6,1,'u3','L04','g6_1_kor_u3_L04_basic','lesson_basic','K6-1-u3-C18',3,'mc','auto','「늘 그래 왔던 일에도 꼭 그래야 할까」라고 물어보라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X01','K6-1-u3-X19']::text[],false,'{"seq":10,"concept":"K6-1-u3-C18","difficulty":3,"kind":"mc","stem":"「늘 그래 왔던 일에도 꼭 그래야 할까」라고 물어보라고 하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"당연해 보이던 곳에서 찬반이 갈리는 좋은 주제가 나오기 때문에","correct":true},{"t":"늘 하던 일은 모두 잘못된 일이기 때문에","mis":"K6-1-u3-X09"},{"t":"답이 정해진 일이 가장 좋은 주제이기 때문에","mis":"K6-1-u3-X01"},{"t":"우리가 바꿀 수 없는 일일수록 토론이 재미있기 때문에","mis":"K6-1-u3-X19"}],"explanation":["늘 하던 일이 모두 잘못된 것은 아니에요.","답이 정해진 일은 토론이 안 돼요.","당연한 곳에서 좋은 주제가 나와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#1','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C20',2,'mc','auto','토론 준비표에 이유를 두세 가지 준비하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X05','K6-1-u3-X15']::text[],false,'{"seq":1,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"토론 준비표에 이유를 두세 가지 준비하는 까닭은 무엇인가요?","options":[{"t":"하나가 무너져도 남은 것으로 버틸 수 있기 때문에","correct":true},{"t":"이유가 많을수록 판정단이 무조건 점수를 주기 때문에","mis":"K6-1-u3-X30"},{"t":"이유가 많으면 근거를 찾지 않아도 되기 때문에","mis":"K6-1-u3-X05"},{"t":"같은 이유를 여러 번 말하기 위해서","mis":"K6-1-u3-X15"}],"explanation":["개수만으로 점수를 받지 않아요.","이유마다 근거가 필요해요.","하나가 무너져도 버틸 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#2','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',2,'ox','auto','판정단은 자기 생각과 같은 편이면 점수를 조금 더 줘도 돼요.',ARRAY['K6-1-u3-X24']::text[],false,'{"seq":2,"concept":"K6-1-u3-C23","difficulty":2,"kind":"ox","stem":"판정단은 자기 생각과 같은 편이면 점수를 조금 더 줘도 돼요.","answer":"X","reason_options":[{"t":"판정단은 정한 기준으로 공정하게 판정해야 하기 때문에","correct":true},{"t":"판정단도 자기 생각이 있기 때문에","mis":"K6-1-u3-X24"}],"mis":"K6-1-u3-X24","explanation":["판정단도 생각이 있을 수 있어요.","그러나 판정은 기준으로 해요.","같은 편이라고 후하게 주지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#3','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C21',3,'mc','auto','「힘든 곳을 늘 같은 사람이 맡게 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X29','K6-1-u3-X27']::text[],false,'{"seq":3,"concept":"K6-1-u3-C21","difficulty":3,"kind":"mc","stem":"「힘든 곳을 늘 같은 사람이 맡게 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"지난 학기 청소 점검표에 남은, 학생별 화장실 청소 횟수 기록","correct":true},{"t":"청소가 귀찮다고 느낀 적이 있다는 내 생각","mis":"K6-1-u3-X04"},{"t":"제비뽑기가 재미있어 보인다는 친구 한 명의 말","mis":"K6-1-u3-X29"},{"t":"점심시간 운동장 사고 자료","mis":"K6-1-u3-X27"}],"explanation":["내 생각은 근거가 아니에요.","친구 한 명의 말은 흐릿해요.","이유와 곧바로 이어지는 기록이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#4','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C22',3,'mc','auto','「제비뽑기를 하면 힘이 센 학생이 가벼운 구역을 뽑을 수도 있습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X08','K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C22","difficulty":3,"kind":"mc","stem":"「제비뽑기를 하면 힘이 센 학생이 가벼운 구역을 뽑을 수도 있습니다.」라는 반론에 대한 답변으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그 점은 뽑은 뒤 서로 바꿀 수 있게 하면 풀립니다. 처음 나누는 방법이 공평해야 바꾸는 일도 공평해집니다.」","correct":true},{"t":"「어쨌든 제비뽑기가 공평합니다. 공평하니까 공평합니다.」","mis":"K6-1-u3-X13"},{"t":"「그 이야기는 들을 필요가 없습니다.」","mis":"K6-1-u3-X08"},{"t":"「힘센 사람이 양보하면 되는데 그것도 모르십니까?」","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답이 아니에요.","반론을 듣고 답해야 해요.","물은 점을 풀어 주며 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#5','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',3,'error','auto','토론에서 맡은 일을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X37','K6-1-u3-X25','K6-1-u3-X24']::text[],false,'{"seq":5,"concept":"K6-1-u3-C23","difficulty":3,"kind":"error","stem":"토론에서 맡은 일을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"다온(청중) — 「청중은 할 일이 없으니 쉬면서 들으면 돼.」","correct":true,"mis_target":"K6-1-u3-X37"},{"t":"이준(사회자) — 「주제에서 벗어나면 다시 주제로 이끌게.」","mis":"K6-1-u3-X25"},{"t":"하린(판정단) — 「내 생각과 같은 편이라고 후하게 주지 않을게.」","mis":"K6-1-u3-X24"}],"explanation":["이준은 사회자의 일을 바르게 말했어요.","하린은 판정단의 일을 바르게 말했어요.","청중도 메모하고 잘한 곳을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#6','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C24',3,'mc','auto','토론 단계 사이에 협의 시간을 두는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X16','K6-1-u3-X06']::text[],false,'{"seq":6,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"토론 단계 사이에 협의 시간을 두는 까닭은 무엇인가요?","options":[{"t":"같은 편끼리 반론과 답변을 맞춰 두기 위해서","correct":true},{"t":"상대 편 원고를 몰래 보기 위해서","mis":"K6-1-u3-X09"},{"t":"판정단이 미리 승패를 정하기 위해서","mis":"K6-1-u3-X16"},{"t":"토론을 빨리 끝내기 위해서","mis":"K6-1-u3-X06"}],"explanation":["몰래 보는 것은 규칙을 어겨요.","판정은 끝난 뒤 기준으로 해요.","같은 편끼리 맞춰 두는 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#7','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C19',3,'mc','auto','찬성과 반대를 비슷한 수로 나누는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X20','K6-1-u3-X16']::text[],false,'{"seq":7,"concept":"K6-1-u3-C19","difficulty":3,"kind":"mc","stem":"찬성과 반대를 비슷한 수로 나누는 까닭은 무엇인가요?","options":[{"t":"한쪽이 얇으면 토론이 기울어 팽팽하게 겨룰 수 없기 때문에","correct":true},{"t":"많은 쪽이 무조건 이기게 하려고","mis":"K6-1-u3-X09"},{"t":"역할을 먼저 정해야 하기 때문에","mis":"K6-1-u3-X20"},{"t":"판정단이 수를 세어 판정하기 때문에","mis":"K6-1-u3-X16"}],"explanation":["수로 이기는 것이 아니에요.","역할은 생각을 정한 다음이에요.","팽팽해야 토론이 살아나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#8','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C25',4,'mc','auto','반론하기에서 말이 겹치고 목소리가 커지기 시작했어요. 토론자가 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X26','K6-1-u3-X14','K6-1-u3-X08']::text[],false,'{"seq":8,"concept":"K6-1-u3-C25","difficulty":4,"kind":"mc","stem":"반론하기에서 말이 겹치고 목소리가 커지기 시작했어요. 토론자가 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"말차례를 기다렸다가 상대 근거의 가장 약한 한 곳만 침착하게 되받는다","correct":true},{"t":"더 큰 목소리로 한꺼번에 여러 가지를 몰아친다","mis":"K6-1-u3-X26"},{"t":"상대 말투가 거칠다고 맞받아친다","mis":"K6-1-u3-X14"},{"t":"준비한 원고를 처음부터 다시 읽는다","mis":"K6-1-u3-X08"}],"explanation":["몰아치면 서로 들리지 않아요.","말투가 아니라 근거를 겨눠요.","침착하게 한 가지씩 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#9','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C20',4,'essay','teacher','「우리 반 앉는 곳을 한 달마다 바꾸어야 한다」를 주제로 찬성이나 반대 가운데 하나를 골라 토론 준비표(주장 · 이유 · 근거)를 쓰고, 예상 반론과 답변을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C20","difficulty":4,"kind":"essay","stem":"「우리 반 앉는 곳을 한 달마다 바꾸어야 한다」를 주제로 찬성이나 반대 가운데 하나를 골라 토론 준비표(주장 · 이유 · 근거)를 쓰고, 예상 반론과 답변을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 주장 — 앉는 곳을 한 달마다 바꾸어야 한다. 이유 — 여러 친구와 가까워질 기회가 생기기 때문이다. 근거 — 우리 반 스물여섯 명에게 지난주에 물어보니 열여덟 명이 「옆자리 친구와 더 친해졌다」고 답했다. 예상 반론 — 자주 바꾸면 수업에 집중하기 어렵다. 답변 — 한 달은 새 자리에 익숙해지기에 충분한 시간이고, 설문에서 집중이 어려웠다고 답한 사람은 적었다.","scoring_points":["주장 · 이유 · 근거를 층에 맞게 썼는가","근거에 누구에게 언제 물었는지 밝혔는가","예상 반론에 곧바로 답하는 답변을 썼는가"]},"explanation":["주장 · 이유 · 근거를 차례로 써요.","확인할 수 있는 근거를 써요.","반론에 곧바로 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L04_challenge#10','kor',6,1,'u3','L04','g6_1_kor_u3_L04_challenge','lesson_challenge','K6-1-u3-C23',4,'essay','teacher','토론의 네 역할 가운데 두 가지를 골라 각 역할이 할 일과 지켜야 할 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C23","difficulty":4,"kind":"essay","stem":"토론의 네 역할 가운데 두 가지를 골라 각 역할이 할 일과 지켜야 할 점을 쓰세요.","answer_guide":{"answer":"예: 사회자는 토론 주제와 규칙을 알리고 말차례를 이끌며, 토론이 주제에서 벗어나지 않게 한다. 어느 쪽에도 기울지 않아야 한다. 판정단은 판정 기준을 미리 정해 적어 두고, 토론에서 나온 말과 자료로 공정하게 판정한다. 자기 생각과 같은 편이라고 후하게 주지 않아야 한다.","scoring_points":["두 역할을 골랐는가","각 역할이 할 일을 썼는가","각 역할이 지켜야 할 점을 썼는가"]},"explanation":["네 역할 가운데 둘을 골라요.","할 일을 써요.","지켜야 할 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#1','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C26',1,'match','auto','근거를 따지는 기준과 확인하는 물음을 이으세요.','{}'::text[],false,'{"seq":1,"concept":"K6-1-u3-C26","difficulty":1,"kind":"match","stem":"근거를 따지는 기준과 확인하는 물음을 이으세요.","pairs":[{"l":"주장이나 이유와 가깝게 이어지는가?","r":"관련성"},{"l":"어디서 나온 자료인지 확인할 수 있는가?","r":"신뢰성"},{"l":"언제 누구를 조사했는지 밝혀져 있는가?","r":"충분성"}],"mis":"K6-1-u3-X35","explanation":["가까운지 묻는 물음이 있어요.","어디서 왔는지 묻는 물음이 있어요.","얼마나 자세한지 묻는 물음이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#2','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C4',1,'mc','auto','글 ㉮의 주장은 무엇인가요?',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"글 ㉮의 주장은 무엇인가요?","options":[{"t":"학교 운동장은 저녁에도 마을 사람들에게 열어야 한다","correct":true},{"t":"동네에 마음 놓고 걷거나 뛸 곳이 마땅치 않다","mis":"K6-1-u3-X04"},{"t":"도시 계획과가 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X04"},{"t":"운동장은 저녁에 비어 있다","mis":"K6-1-u3-X04"}],"explanation":["뛸 곳이 마땅치 않다는 것은 이유예요.","조사는 근거예요.","하자고 내세운 생각이 주장이에요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에도 마을 사람들에게 열어야 합니다.","우리 동네에는 마음 놓고 걷거나 뛸 곳이 마땅치 않기 때문입니다.","지난해 우리 시 도시 계획과가 시민 사백 명에게 물은 조사를 보면,","열 명 가운데 일곱 명이 가까운 곳에 운동할 공간이 부족하다고 답했습니다.","운동장은 낮 동안만 쓰이고 저녁에는 비어 있습니다.","열어 두는 시간을 정하고 관리하는 분을 두면 학교와 마을 모두에 도움이 됩니다."],"title":"글 ㉮ 「학교 운동장은 저녁에도 마을에 열어야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#3','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C10',1,'mc','auto','글 ㉯가 든 근거는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":3,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"글 ㉯가 든 근거는 무엇인가요?","options":[{"t":"교육청이 올해 낸 학교 시설 개방 점검 자료","correct":true},{"t":"학교는 학생이 안전하게 지내야 하는 곳이다","mis":"K6-1-u3-X04"},{"t":"시에서 걷기 좋은 길을 새로 내는 쪽이 낫다","mis":"K6-1-u3-X04"},{"t":"학교 운동장은 저녁에는 닫아야 한다","mis":"K6-1-u3-X05"}],"explanation":["안전하게 지내야 한다는 것은 이유예요.","길을 내자는 것은 글쓴이의 생각이에요.","어느 기관이 언제 낸 자료인지 밝혀진 것이 근거예요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#4','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C28',1,'ox','auto','근거 자료를 다섯 개 넘게 내면 그것만으로 충분성을 갖춘 거예요.',ARRAY['K6-1-u3-X30']::text[],false,'{"seq":4,"concept":"K6-1-u3-C28","difficulty":1,"kind":"ox","stem":"근거 자료를 다섯 개 넘게 내면 그것만으로 충분성을 갖춘 거예요.","answer":"X","reason_options":[{"t":"충분하다는 것은 자료 하나가 언제 · 누구를 · 어떻게 조사했는지 밝혀져 있다는 뜻이기 때문에","correct":true},{"t":"자료는 많을수록 무조건 힘이 세기 때문에","mis":"K6-1-u3-X30"}],"mis":"K6-1-u3-X30","explanation":["개수를 늘려도 흐릿하면 그대로예요.","자세한지가 중요해요.","자료 하나라도 자세하면 충분할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#5','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C27',2,'mc','auto','근거로 삼기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X31']::text[],false,'{"seq":5,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"근거로 삼기 어려운 것은 어느 것인가요?","options":[{"t":"어디에서 봤는지 모르는 동영상에서 들은 이야기","correct":true},{"t":"우리 시가 지난해 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X35"},{"t":"교육청이 올해 낸 학교 시설 점검 자료","mis":"K6-1-u3-X35"},{"t":"모둠이 한 시간 동안 운동장 출입을 센 기록","mis":"K6-1-u3-X31"}],"explanation":["시의 조사는 출처와 때가 밝혀져 있어요.","교육청 자료도 확인할 수 있어요.","누가 만든 무엇인지 모르면 힘을 내지 못해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#6','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C29',2,'mc','auto','하윤이와 도겸이의 경험 가운데 근거로 쓰기에 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X31']::text[],false,'{"seq":6,"concept":"K6-1-u3-C29","difficulty":2,"kind":"mc","stem":"하윤이와 도겸이의 경험 가운데 근거로 쓰기에 알맞은 것은 어느 것인가요?","options":[{"t":"도겸 — 정한 시간 동안 출입을 세어 정리했기 때문에","correct":true},{"t":"하윤 — 직접 겪은 일이라 더 생생하기 때문에","mis":"K6-1-u3-X32"},{"t":"둘 다 아니다 — 경험은 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"둘 다 알맞다 — 경험이면 무엇이든 되기 때문에","mis":"K6-1-u3-X32"}],"explanation":["지갑을 주운 일은 드문 일이에요.","경험도 근거가 될 수 있어요.","세거나 재어 정리해야 해요."],"asset":{"type":"speech","turns":[{"who":"하윤","text":"저는 저녁 운동장에서 지갑을 주운 적이 있습니다. 그러니 저녁 운동장은 위험합니다."},{"who":"도겸","text":"저희 모둠이 저녁 여섯 시부터 한 시간 동안 운동장 출입을 세었더니 마흔두 명이었습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#7','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C30',2,'mc','auto','믿을 만한 자료를 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X33','K6-1-u3-X27']::text[],false,'{"seq":7,"concept":"K6-1-u3-C30","difficulty":2,"kind":"mc","stem":"믿을 만한 자료를 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"공신력 있는 곳에서 가장 최근에 낸, 주제와 직접 이어지는 자료를 고른다","correct":true},{"t":"무언가를 팔려는 광고 글도 숫자가 있으면 쓴다","mis":"K6-1-u3-X33"},{"t":"오래된 자료도 숫자가 크면 쓴다","mis":"K6-1-u3-X33"},{"t":"주제와 비슷해 보이는 다른 주제의 자료를 쓴다","mis":"K6-1-u3-X27"}],"explanation":["광고에 가까운 글은 피해요.","오래된 수치는 지금과 다를 수 있어요.","주제와 직접 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#8','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C31',2,'mc','auto','근거를 말할 때 먼저 밝히면 좋은 것은 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X30']::text[],false,'{"seq":8,"concept":"K6-1-u3-C31","difficulty":2,"kind":"mc","stem":"근거를 말할 때 먼저 밝히면 좋은 것은 어느 것인가요?","options":[{"t":"누가 언제 낸 자료인지","correct":true},{"t":"「어디서 봤는데」라는 말","mis":"K6-1-u3-X34"},{"t":"자료의 세부 사항 전부","mis":"K6-1-u3-X34"},{"t":"자료를 찾는 데 걸린 시간","mis":"K6-1-u3-X30"}],"explanation":["「어디서 봤는데」는 자료를 흔들어요.","세부 사항은 추려서 전해요.","출처를 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#9','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C29',2,'ox','auto','내가 겪은 일은 어떤 경우에도 근거가 될 수 없어요.',ARRAY['K6-1-u3-X31']::text[],false,'{"seq":9,"concept":"K6-1-u3-C29","difficulty":2,"kind":"ox","stem":"내가 겪은 일은 어떤 경우에도 근거가 될 수 없어요.","answer":"X","reason_options":[{"t":"여러 사람이 그럴 만하다고 여길 일을 세거나 재어 정리하면 근거가 될 수 있기 때문에","correct":true},{"t":"경험은 모두 나에게만 일어난 일이기 때문에","mis":"K6-1-u3-X31"}],"mis":"K6-1-u3-X31","explanation":["드문 일은 근거가 되기 어려워요.","그러나 모든 경험이 그런 건 아니에요.","세거나 재어 정리하면 근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_basic#10','kor',6,1,'u3','L06','g6_1_kor_u3_L06_basic','lesson_basic','K6-1-u3-C26',3,'mc','auto','글 ㉮의 근거를 세 물음으로 따져 본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X27']::text[],false,'{"seq":10,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"글 ㉮의 근거를 세 물음으로 따져 본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"뛸 곳이 마땅치 않다는 이유와 이어지고, 도시 계획과라는 출처와 지난해 · 시민 사백 명이라는 조사 대상이 밝혀져 있다","correct":true},{"t":"숫자가 나왔으니 따져 볼 필요 없이 타당하다","mis":"K6-1-u3-X35"},{"t":"조사한 사람이 사백 명뿐이라 근거가 될 수 없다","mis":"K6-1-u3-X30"},{"t":"운동장 이야기라서 이유와 관련이 없다","mis":"K6-1-u3-X27"}],"explanation":["숫자만 보고 넘어가지 않아요.","사람 수만으로 따지지 않아요.","세 물음을 한 번씩 던져 봐요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에도 마을 사람들에게 열어야 합니다.","우리 동네에는 마음 놓고 걷거나 뛸 곳이 마땅치 않기 때문입니다.","지난해 우리 시 도시 계획과가 시민 사백 명에게 물은 조사를 보면,","열 명 가운데 일곱 명이 가까운 곳에 운동할 공간이 부족하다고 답했습니다.","운동장은 낮 동안만 쓰이고 저녁에는 비어 있습니다.","열어 두는 시간을 정하고 관리하는 분을 두면 학교와 마을 모두에 도움이 됩니다."],"title":"글 ㉮ 「학교 운동장은 저녁에도 마을에 열어야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#1','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C27',2,'mc','auto','「많은 사람이 그렇게 답했습니다.」라는 근거가 힘을 내지 못하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X30','K6-1-u3-X27']::text[],false,'{"seq":1,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"「많은 사람이 그렇게 답했습니다.」라는 근거가 힘을 내지 못하는 까닭은 무엇인가요?","options":[{"t":"언제 몇 명에게 물었는지 없기 때문에","correct":true},{"t":"사람에게 물은 자료는 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"많은 사람이 답했으니 오히려 충분하기 때문에","mis":"K6-1-u3-X30"},{"t":"주장과 반대되는 말이기 때문에","mis":"K6-1-u3-X27"}],"explanation":["설문도 근거가 될 수 있어요.","「많은」은 흐릿한 말이에요.","언제 · 누구를이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#2','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',2,'ox','auto','세 물음 가운데 하나만 걸려도 근거는 흔들릴 수 있어요.',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":2,"concept":"K6-1-u3-C26","difficulty":2,"kind":"ox","stem":"세 물음 가운데 하나만 걸려도 근거는 흔들릴 수 있어요.","answer":"O","reason_options":[{"t":"이어지지 않거나 출처를 모르거나 흐릿하면 어느 쪽이든 이유를 제대로 뒷받침하지 못하기 때문에","correct":true},{"t":"세 물음 가운데 하나만 통과하면 충분하기 때문에","mis":"K6-1-u3-X35"}],"mis":"K6-1-u3-X35","explanation":["세 물음을 한 번씩 던져요.","하나만 걸려도 흔들려요.","전체적으로 타당한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#3','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C27',3,'error','auto','운동장을 저녁에 여는 문제로 근거를 냈어요. 근거로 알맞지 않은 것을 낸 친구는 누구인가요?',ARRAY['K6-1-u3-X27','K6-1-u3-X28','K6-1-u3-X29']::text[],false,'{"seq":3,"concept":"K6-1-u3-C27","difficulty":3,"kind":"error","stem":"운동장을 저녁에 여는 문제로 근거를 냈어요. 근거로 알맞지 않은 것을 낸 친구는 누구인가요?","options":[{"t":"수아 — 「운동장을 열면 학교가 유명해집니다.」","correct":true,"mis_target":"K6-1-u3-X27"},{"t":"민재 — 「교육청이 올해 스물여덟 곳을 점검한 자료입니다.」","mis":"K6-1-u3-X28"},{"t":"해솔 — 「우리 시가 지난해 시민 사백 명에게 물은 조사입니다.」","mis":"K6-1-u3-X29"}],"explanation":["민재는 출처와 때를 밝혔어요.","해솔도 누구를 언제 조사했는지 밝혔어요.","수아의 말은 이유와 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#4','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C28',3,'mc','auto','「열 명 가운데 일곱 명」보다 「지난해 우리 시가 시민 사백 명에게 물어 열 명 가운데 일곱 명」이 더 센 까닭은 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X34']::text[],false,'{"seq":4,"concept":"K6-1-u3-C28","difficulty":3,"kind":"mc","stem":"「열 명 가운데 일곱 명」보다 「지난해 우리 시가 시민 사백 명에게 물어 열 명 가운데 일곱 명」이 더 센 까닭은 무엇인가요?","options":[{"t":"언제 · 누구를 조사했는지가 밝혀져 있어 더 구체적이기 때문에","correct":true},{"t":"글자 수가 더 많기 때문에","mis":"K6-1-u3-X30"},{"t":"숫자가 하나 더 들어 있기 때문에","mis":"K6-1-u3-X30"},{"t":"듣기에 더 어려워 보이기 때문에","mis":"K6-1-u3-X34"}],"explanation":["길이로 세지는 것이 아니에요.","숫자 개수도 아니에요.","언제 · 누구를이 밝혀져 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#5','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C30',3,'mc','auto','신문 기사를 근거로 쓰려고 해요. 가장 먼저 살펴볼 것은 어느 것인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X35','K6-1-u3-X33']::text[],false,'{"seq":5,"concept":"K6-1-u3-C30","difficulty":3,"kind":"mc","stem":"신문 기사를 근거로 쓰려고 해요. 가장 먼저 살펴볼 것은 어느 것인가요?","options":[{"t":"광고에 가까운 글인지, 쓴 사람의 이름과 낸 때가 적혀 있는지","correct":true},{"t":"기사가 길고 어려운지","mis":"K6-1-u3-X30"},{"t":"사진이 많이 들어 있는지","mis":"K6-1-u3-X35"},{"t":"내 주장과 같은 말을 하는지만","mis":"K6-1-u3-X33"}],"explanation":["길고 어렵다고 믿을 만한 것은 아니에요.","사진 수로 판단하지 않아요.","광고인지 · 누가 언제 썼는지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#6','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C31',3,'mc','auto','근거를 내놓는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X28']::text[],false,'{"seq":6,"concept":"K6-1-u3-C31","difficulty":3,"kind":"mc","stem":"근거를 내놓는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"중요한 내용만 추리고, 필요하면 표나 그림으로 보이며, 누가 언제 낸 자료인지 먼저 밝힌다","correct":true},{"t":"자료의 세부 사항을 처음부터 끝까지 모두 읽는다","mis":"K6-1-u3-X34"},{"t":"「어디서 봤는데」로 시작해 친근하게 말한다","mis":"K6-1-u3-X34"},{"t":"출처는 상대가 물을 때만 말한다","mis":"K6-1-u3-X28"}],"explanation":["모두 읽으면 중심이 흐려져요.","「어디서 봤는데」는 자료를 흔들어요.","출처를 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#7','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',3,'mc','auto','글 ㉯의 근거를 따져 본 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X31']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"글 ㉯의 근거를 따져 본 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"교육청 · 올해 · 스물여덟 곳이 밝혀져 있고, 학생이 안전하게 지내야 한다는 이유와 이어진다","correct":true},{"t":"학교 이야기라서 따져 볼 것도 없이 타당하다","mis":"K6-1-u3-X35"},{"t":"자료가 하나뿐이라 충분하지 않다","mis":"K6-1-u3-X30"},{"t":"교육청 자료는 사람이 만든 것이라 믿을 수 없다","mis":"K6-1-u3-X31"}],"explanation":["따져 보지 않고 넘어가지 않아요.","하나라도 자세하면 충분할 수 있어요.","세 물음으로 보면 타당해요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#8','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C29',4,'mc','auto','「저녁 운동장은 관리가 어렵다」는 이유를 경험으로 뒷받침하려고 해요. 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X32','K6-1-u3-X28']::text[],false,'{"seq":8,"concept":"K6-1-u3-C29","difficulty":4,"kind":"mc","stem":"「저녁 운동장은 관리가 어렵다」는 이유를 경험으로 뒷받침하려고 해요. 가장 알맞은 것은 어느 것인가요?","options":[{"t":"모둠이 일주일 동안 저녁마다 운동장에 남은 쓰레기 수를 세어 정리한 기록","correct":true},{"t":"저녁 운동장이 무서웠던 내 느낌","mis":"K6-1-u3-X04"},{"t":"어느 날 운동장에서 넘어진 내 일 하나","mis":"K6-1-u3-X32"},{"t":"어떤 동영상에서 본 이야기","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","드문 일 하나는 힘이 약해요.","세어서 정리한 경험은 근거가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#9','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C26',4,'essay','teacher','글 ㉯의 근거를 세 물음으로 하나씩 따져 보고, 이 근거를 더 타당하게 만들려면 무엇을 더 밝히면 좋을지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C26","difficulty":4,"kind":"essay","stem":"글 ㉯의 근거를 세 물음으로 하나씩 따져 보고, 이 근거를 더 타당하게 만들려면 무엇을 더 밝히면 좋을지 쓰세요.","answer_guide":{"answer":"예: 이 자료는 쓰레기와 시설 파손 때문에 어려움을 겪는다는 내용이라 학생이 안전하게 지내야 한다는 이유와 이어진다. 교육청이 낸 자료라 출처가 분명하다. 올해, 운동장을 연 학교 스물여덟 곳을 점검했다고 밝혀 구체적이다. 더 타당하게 하려면 어떤 어려움이 몇 곳에서 있었는지, 그 학교들이 우리 학교와 비슷한 곳인지를 더 밝히면 좋겠다.","scoring_points":["관련성 · 신뢰성 · 충분성을 하나씩 따졌는가","글 ㉯의 내용으로 근거를 들어 따졌는가","더 밝힐 점을 알맞게 썼는가"]},"explanation":["세 물음을 한 번씩 던져요.","글의 내용으로 따져요.","더 밝힐 점을 찾아요."],"asset":{"type":"passage","lines":["학교 운동장은 저녁에는 닫아야 합니다.","학교는 무엇보다 학생이 안전하게 지내야 하는 곳이기 때문입니다.","저녁에 문을 열어 두면 누가 드나드는지 알기 어렵습니다.","우리 교육청이 올해 낸 학교 시설 개방 점검 자료를 보면,","저녁에 운동장을 연 학교 스물여덟 곳 가운데 열아홉 곳이","쓰레기와 시설 파손 때문에 어려움을 겪는다고 답했습니다.","시에서 걷기 좋은 길을 새로 내는 쪽이 낫습니다."],"title":"글 ㉯ 「학교 운동장은 저녁에는 닫아야 한다」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L06_challenge#10','kor',6,1,'u3','L06','g6_1_kor_u3_L06_challenge','lesson_challenge','K6-1-u3-C28',4,'essay','teacher','「충분성은 자료가 많다는 뜻이 아니다」라는 말을 예를 들어 설명하고, 내가 겪은 일을 근거로 쓰려면 어떻게 해야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C28","difficulty":4,"kind":"essay","stem":"「충분성은 자료가 많다는 뜻이 아니다」라는 말을 예를 들어 설명하고, 내가 겪은 일을 근거로 쓰려면 어떻게 해야 하는지 쓰세요.","answer_guide":{"answer":"예: 「많은 사람이 그렇다고 했다」는 자료를 다섯 개 모아도 언제 누구에게 물었는지 없으면 여전히 흐릿하다. 반대로 「지난해 우리 시가 시민 사백 명에게 물은 조사」처럼 하나라도 언제 · 누구를 · 어떻게 조사했는지 밝혀져 있으면 충분할 수 있다. 내가 겪은 일을 근거로 쓰려면 나에게만 일어난 드문 일이 아니라 여러 사람이 그럴 만하다고 여길 일을 골라, 느낌으로 두지 말고 세거나 재어서 정리해야 한다.","scoring_points":["충분성이 개수가 아니라 구체성임을 예와 함께 썼는가","드문 경험은 근거가 되기 어렵다는 점을 썼는가","세거나 재어 정리하는 방법을 썼는가"]},"explanation":["흐릿한 자료 여러 개와 자세한 하나를 견줘요.","어떤 경험이 근거가 되기 어려운지 써요.","세거나 재는 방법을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#1','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C32',1,'mc','auto','사회 문제 토론 주제로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C32","difficulty":1,"kind":"mc","stem":"사회 문제 토론 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"공공 도서관을 밤 열 시까지 열어야 하는가","correct":true},{"t":"우리 시의 인구가 몇 명인가","mis":"K6-1-u3-X01"},{"t":"신호등이 빨간불일 때 건너면 안 되는가","mis":"K6-1-u3-X01"},{"t":"어제 비가 몇 시에 왔는가","mis":"K6-1-u3-X01"}],"explanation":["인구는 찾아보면 확인돼요.","빨간불에 건너지 않는 것은 정해진 규칙이에요.","찬반이 갈리고 무엇을 하자고 정하는 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#2','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C27',1,'mc','auto','이 글의 근거에서 가장 큰 문제는 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X15','K6-1-u3-X35']::text[],false,'{"seq":2,"concept":"K6-1-u3-C27","difficulty":1,"kind":"mc","stem":"이 글의 근거에서 가장 큰 문제는 무엇인가요?","options":[{"t":"어디서 나온 자료인지 하나도 확인할 수 없다","correct":true},{"t":"글이 너무 짧다","mis":"K6-1-u3-X30"},{"t":"주장을 맨 앞과 맨 뒤에 두 번 썼다","mis":"K6-1-u3-X15"},{"t":"이모의 말에 높임말을 썼다","mis":"K6-1-u3-X35"}],"explanation":["길이는 문제가 아니에요.","주장을 다시 쓴 것은 큰 문제가 아니에요.","누리집 · 많은 사람 · 이모의 말 모두 확인할 수 없어요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#3','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C33',1,'ox','auto','판정단은 토론에서 실제로 나온 말과 자료만으로 판정해요.',ARRAY['K6-1-u3-X24']::text[],false,'{"seq":3,"concept":"K6-1-u3-C33","difficulty":1,"kind":"ox","stem":"판정단은 토론에서 실제로 나온 말과 자료만으로 판정해요.","answer":"O","reason_options":[{"t":"미리 정한 기준으로 공정하게 판정해야 하기 때문에","correct":true},{"t":"평소 자기 생각을 넣어야 판정이 정확해지기 때문에","mis":"K6-1-u3-X24"}],"mis":"K6-1-u3-X24","explanation":["평소 생각은 판정과 관계없어요.","미리 정한 기준으로 봐요.","나온 말과 자료만으로 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#4','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C34',1,'mc','auto','토론 중에 메모해 두면 좋은 것은 어느 것인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X12']::text[],false,'{"seq":4,"concept":"K6-1-u3-C34","difficulty":1,"kind":"mc","stem":"토론 중에 메모해 두면 좋은 것은 어느 것인가요?","options":[{"t":"상대가 근거로 든 자료의 출처","correct":true},{"t":"상대의 목소리 크기와 말투","mis":"K6-1-u3-X38"},{"t":"상대가 입은 옷차림","mis":"K6-1-u3-X38"},{"t":"상대 발언 전체를 한 글자도 빠짐없이","mis":"K6-1-u3-X12"}],"explanation":["말투는 되받을 거리가 아니에요.","옷차림도 아니에요.","되받을 거리를 핵심만 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#5','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C35',2,'mc','auto','판정 기준 가운데 「반론하기」에서 보는 것은 어느 것인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X16','K6-1-u3-X08']::text[],false,'{"seq":5,"concept":"K6-1-u3-C35","difficulty":2,"kind":"mc","stem":"판정 기준 가운데 「반론하기」에서 보는 것은 어느 것인가요?","options":[{"t":"상대 이유나 근거의 문제를 찾아 되받았는가, 반론에 알맞게 답했는가","correct":true},{"t":"주장과 이유를 처음으로 냈는가","mis":"K6-1-u3-X06"},{"t":"누구의 목소리가 더 컸는가","mis":"K6-1-u3-X16"},{"t":"준비한 원고를 끝까지 읽었는가","mis":"K6-1-u3-X08"}],"explanation":["처음 내는 것은 주장 펼치기예요.","목소리는 기준이 아니에요.","되받고 답한 것을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#6','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C32',2,'mc','auto','사회 문제를 주제로 정한 뒤 먼저 할 일로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X36','K6-1-u3-X16','K6-1-u3-X20']::text[],false,'{"seq":6,"concept":"K6-1-u3-C32","difficulty":2,"kind":"mc","stem":"사회 문제를 주제로 정한 뒤 먼저 할 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지금 제한 속도가 얼마인지, 사고가 몇 건이었는지처럼 알려진 사실부터 함께 맞춰 본다","correct":true},{"t":"아는 것이 적어도 곧바로 토론을 시작한다","mis":"K6-1-u3-X36"},{"t":"판정 결과부터 정해 둔다","mis":"K6-1-u3-X16"},{"t":"주제를 정하자마자 역할부터 나눈다","mis":"K6-1-u3-X20"}],"explanation":["아는 것이 적으면 겉돌기 쉬워요.","판정은 토론 뒤에 해요.","사실부터 함께 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#7','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C22',2,'mc','auto','제한 속도 준비표에서 예상 반론에 대한 답변이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"제한 속도 준비표에서 예상 반론에 대한 답변이 알맞은 까닭은 무엇인가요?","options":[{"t":"「속도 때문인지 알 수 없다」는 물음에 공사를 하지 않은 구역 자료로 곧바로 답했기 때문에","correct":true},{"t":"「어쨌든 속도를 낮추면 안전합니다」라고 되풀이했기 때문에","mis":"K6-1-u3-X13"},{"t":"자전거 사고 이야기로 넘어갔기 때문에","mis":"K6-1-u3-X11"},{"t":"상대가 준비를 안 했다고 짚었기 때문에","mis":"K6-1-u3-X14"}],"explanation":["되풀이는 답변이 아니에요.","다른 이야기로 넘어가지 않았어요.","물은 그 지점을 자료로 되받았어요."],"asset":{"type":"passage","lines":["주장 — 학교 주변 도로의 제한 속도를 더 낮춰야 합니다.","이유 — 속도가 낮을수록 멈추는 데 걸리는 거리가 짧아지기 때문입니다.","근거 — 우리 시 교통 안전과가 지난해 낸 어린이 보호 구역 사고 자료.","속도를 낮춘 구역에서 사고 건수가 줄었습니다.","예상 반론 — 줄어든 것이 속도 때문인지 공사 때문인지 알 수 없습니다.","우리 측 답변 — 같은 자료에 공사를 하지 않은 구역이 따로 나와 있고,","그 구역에서도 사고가 줄었습니다."],"title":"찬성 측 토론 준비표 (사회 문제)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#8','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C34',2,'ox','auto','반론하기에서는 상대 말을 듣기보다 준비한 원고를 그대로 다시 읽는 것이 안전해요.',ARRAY['K6-1-u3-X08']::text[],false,'{"seq":8,"concept":"K6-1-u3-C34","difficulty":2,"kind":"ox","stem":"반론하기에서는 상대 말을 듣기보다 준비한 원고를 그대로 다시 읽는 것이 안전해요.","answer":"X","reason_options":[{"t":"반론은 그 순간에 들은 것으로만 할 수 있어 메모하며 들어야 하기 때문에","correct":true},{"t":"원고를 읽으면 실수가 없기 때문에","mis":"K6-1-u3-X08"}],"mis":"K6-1-u3-X08","explanation":["원고를 읽으면 혼잣말이 돼요.","반론은 들은 것으로 해요.","메모하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#9','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C36',2,'mc','auto','판정이 나온 뒤에 할 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18','K6-1-u3-X39']::text[],false,'{"seq":9,"concept":"K6-1-u3-C36","difficulty":2,"kind":"mc","stem":"판정이 나온 뒤에 할 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「저 근거는 나도 다시 찾아봐야겠다.」","correct":true},{"t":"「우리가 이겼다. 더 할 말 없다.」","mis":"K6-1-u3-X40"},{"t":"「판정이 이상하다.」","mis":"K6-1-u3-X18"},{"t":"「생각이 바뀌면 지는 거야.」","mis":"K6-1-u3-X39"}],"explanation":["승패만 남기면 아쉬워요.","판정에는 승복해요.","생각을 남기는 마무리가 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_basic#10','kor',6,1,'u3','L08','g6_1_kor_u3_L08_basic','lesson_basic','K6-1-u3-C23',3,'mc','auto','청중이 많을 때 청중에게도 할 일을 주는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X37','K6-1-u3-X25']::text[],false,'{"seq":10,"concept":"K6-1-u3-C23","difficulty":3,"kind":"mc","stem":"청중이 많을 때 청중에게도 할 일을 주는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"청중이 메모하고 인상 깊은 근거를 말해야 토론이 살아나기 때문에","correct":true},{"t":"청중은 할 일이 없어 조용히 앉아 있으면 되기 때문에","mis":"K6-1-u3-X37"},{"t":"청중이 판정을 대신해야 하기 때문에","mis":"K6-1-u3-X25"},{"t":"청중이 토론자 대신 반론해야 하기 때문에","mis":"K6-1-u3-X25"}],"explanation":["청중에게도 할 일이 있어요.","판정은 판정단이 해요.","메모하고 인상 깊은 근거를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#1','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C33',2,'mc','auto','판정단이 판정의 바탕으로 삼을 것은 어느 것인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":1,"concept":"K6-1-u3-C33","difficulty":2,"kind":"mc","stem":"판정단이 판정의 바탕으로 삼을 것은 어느 것인가요?","options":[{"t":"미리 정한 기준으로, 토론에서 실제로 나온 말과 자료만 본다","correct":true},{"t":"평소 자기 생각과 같은 편에 후하게 준다","mis":"K6-1-u3-X24"},{"t":"친한 친구가 있는 편에 더 준다","mis":"K6-1-u3-X24"},{"t":"목소리가 큰 편을 고른다","mis":"K6-1-u3-X16"}],"explanation":["같은 편이라고 후하게 주지 않아요.","친한 사이는 판정과 관계없어요.","기준과 나온 내용만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#2','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C36',2,'ox','auto','토론이 끝난 뒤 생각이 조금 바뀌는 것은 부끄러운 일이에요.',ARRAY['K6-1-u3-X39']::text[],false,'{"seq":2,"concept":"K6-1-u3-C36","difficulty":2,"kind":"ox","stem":"토론이 끝난 뒤 생각이 조금 바뀌는 것은 부끄러운 일이에요.","answer":"X","reason_options":[{"t":"상대의 근거에서 배운 것이 있다는 뜻으로 토론을 한 보람이기 때문에","correct":true},{"t":"생각이 바뀌면 토론에서 진 것이기 때문에","mis":"K6-1-u3-X39"}],"mis":"K6-1-u3-X39","explanation":["판정에는 승복해요.","생각이 바뀌는 것은 진 것이 아니에요.","그것이 토론을 한 보람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#3','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',3,'mc','auto','메모할 때 발언을 그대로 옮기지 않고 핵심만 짧게 적는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X08','K6-1-u3-X38']::text[],false,'{"seq":3,"concept":"K6-1-u3-C34","difficulty":3,"kind":"mc","stem":"메모할 때 발언을 그대로 옮기지 않고 핵심만 짧게 적는 까닭은 무엇인가요?","options":[{"t":"다음 말을 놓치지 않고 되받을 거리를 찾기 위해서","correct":true},{"t":"발언은 모두 옮겨야 정확하지만 시간이 없어서","mis":"K6-1-u3-X12"},{"t":"상대 말은 어차피 중요하지 않기 때문에","mis":"K6-1-u3-X08"},{"t":"글씨를 예쁘게 쓰기 위해서","mis":"K6-1-u3-X38"}],"explanation":["다 옮기는 것이 좋은 메모가 아니에요.","상대 말을 들어야 되받아요.","핵심만 적어야 다음 말을 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#4','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C27',3,'mc','auto','이 글을 더 타당하게 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X30','K6-1-u3-X15']::text[],false,'{"seq":4,"concept":"K6-1-u3-C27","difficulty":3,"kind":"mc","stem":"이 글을 더 타당하게 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 기관이 언제 낸 사고 자료인지 밝히고, 이모의 말 대신 확인할 수 있는 자료를 든다","correct":true},{"t":"「많은 사람」을 「아주 많은 사람」으로 바꾼다","mis":"K6-1-u3-X29"},{"t":"누리집 이야기를 한 번 더 쓴다","mis":"K6-1-u3-X30"},{"t":"주장을 한 번 더 써서 힘준다","mis":"K6-1-u3-X15"}],"explanation":["「아주 많은」도 흐릿해요.","같은 이야기를 늘려도 그대로예요.","출처가 분명한 자료로 바꿔요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#5','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C35',3,'error','auto','판정단이 기준을 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X35','K6-1-u3-X17']::text[],false,'{"seq":5,"concept":"K6-1-u3-C35","difficulty":3,"kind":"error","stem":"판정단이 기준을 말했어요. 알맞지 않은 기준을 말한 친구는 누구인가요?","options":[{"t":"도윤 — 「더 오래 말한 쪽에 점수를 주겠습니다.」","correct":true,"mis_target":"K6-1-u3-X16"},{"t":"서하 — 「이유와 근거가 타당하고 믿을 만한가를 보겠습니다.」","mis":"K6-1-u3-X35"},{"t":"지후 — 「규칙을 지키고 예의 바르게 참여했는가를 보겠습니다.」","mis":"K6-1-u3-X17"}],"explanation":["서하는 주장 펼치기의 기준을 말했어요.","지후는 태도의 기준을 말했어요.","말한 길이는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#6','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C32',3,'mc','auto','사회 문제 주제를 찾을 때 던지면 좋은 물음은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X19','K6-1-u3-X20']::text[],false,'{"seq":6,"concept":"K6-1-u3-C32","difficulty":3,"kind":"mc","stem":"사회 문제 주제를 찾을 때 던지면 좋은 물음은 어느 것인가요?","options":[{"t":"「늘 그래 왔던 일인데 꼭 그래야 할까?」, 「많은 친구가 관심 있어 할까?」","correct":true},{"t":"「자료를 찾으면 곧바로 답이 나올까?」","mis":"K6-1-u3-X01"},{"t":"「아무도 관심 없는 일일까?」","mis":"K6-1-u3-X19"},{"t":"「한쪽 편만 있을까?」","mis":"K6-1-u3-X20"}],"explanation":["곧바로 답이 나오면 토론이 안 돼요.","관심 있어야 근거를 찾을 마음이 생겨요.","당연한 일에 물어보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#7','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',3,'mc','auto','토론의 승패가 반론하기에서 갈린다고 하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X08','K6-1-u3-X16']::text[],false,'{"seq":7,"concept":"K6-1-u3-C34","difficulty":3,"kind":"mc","stem":"토론의 승패가 반론하기에서 갈린다고 하는 까닭은 무엇인가요?","options":[{"t":"주장 펼치기는 준비한 대로 말하면 되지만, 반론은 그 순간 들은 것으로만 할 수 있기 때문에","correct":true},{"t":"반론하기에서 목소리를 가장 크게 내기 때문에","mis":"K6-1-u3-X45"},{"t":"반론하기에서 원고를 가장 길게 읽기 때문에","mis":"K6-1-u3-X08"},{"t":"판정단이 반론하기만 보기 때문에","mis":"K6-1-u3-X16"}],"explanation":["목소리 크기로 갈리지 않아요.","원고를 읽으면 혼잣말이 돼요.","그 순간 들은 것으로 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#8','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C36',4,'mc','auto','「판정이 이상하다」는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X18','K6-1-u3-X24','K6-1-u3-X39']::text[],false,'{"seq":8,"concept":"K6-1-u3-C36","difficulty":4,"kind":"mc","stem":"「판정이 이상하다」는 친구에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「판정은 정한 기준으로 본 결과니까 승복하자. 그리고 우리 근거에서 약했던 곳을 다시 찾아보자.」","correct":true},{"t":"「맞아, 우리가 옳았으니 판정은 무시하자.」","mis":"K6-1-u3-X18"},{"t":"「다음엔 판정단을 친한 친구로 하자.」","mis":"K6-1-u3-X24"},{"t":"「생각이 흔들리면 지는 거니까 절대 바꾸지 말자.」","mis":"K6-1-u3-X39"}],"explanation":["판정은 무시하지 않아요.","판정단은 공정해야 해요.","승복하고 배운 것을 남겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#9','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C34',4,'essay','teacher','토론 중에 메모해야 할 것 세 가지를 쓰고, 메모하며 듣는 것이 반론하기에 왜 중요한지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C34","difficulty":4,"kind":"essay","stem":"토론 중에 메모해야 할 것 세 가지를 쓰고, 메모하며 듣는 것이 반론하기에 왜 중요한지 쓰세요.","answer_guide":{"answer":"예: 상대측 주장을 한 문장으로, 상대가 든 이유의 개수와 내용, 상대가 근거로 든 자료의 출처(누가 언제 냈는지)를 메모한다. 주장 펼치기는 준비한 대로 말하면 되지만 반론하기는 그 순간 들은 것으로만 할 수 있다. 메모가 없으면 준비한 원고만 다시 읽게 되어 혼잣말이 되므로, 메모한 것 가운데 가장 약한 한 곳을 골라 되받아야 한다.","scoring_points":["되받을 거리가 되는 메모 세 가지를 썼는가","반론은 그 순간 들은 것으로 한다는 점을 썼는가","메모로 가장 약한 곳을 골라 되받는다는 점을 썼는가"]},"explanation":["되받을 거리를 떠올려요.","반론하기의 특징을 써요.","메모를 어떻게 쓰는지 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L08_challenge#10','kor',6,1,'u3','L08','g6_1_kor_u3_L08_challenge','lesson_challenge','K6-1-u3-C27',4,'essay','teacher','이 글의 근거가 왜 믿기 어려운지 세 물음으로 따져 쓰고, 근거를 알맞게 바꾸어 다시 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C27","difficulty":4,"kind":"essay","stem":"이 글의 근거가 왜 믿기 어려운지 세 물음으로 따져 쓰고, 근거를 알맞게 바꾸어 다시 쓰세요.","answer_guide":{"answer":"예: 「어떤 누리집」은 어디인지 몰라 출처가 분명하지 않다. 「많은 사람」은 언제 몇 명에게 물었는지 없어 구체적이지 않다. 이모가 답답하다고 한 말은 한 사람의 느낌이라 속도와 사고 사이의 관계와 이어지지 않는다. 고친 근거 — 「우리 시 교통 안전과가 지난해 낸 자료를 보면, 제한 속도를 낮춘 뒤에도 사고가 줄지 않은 구역이 있었습니다.」처럼 누가 언제 낸 자료인지 밝힌다.","scoring_points":["출처 문제를 짚었는가","구체성 문제와 관련성 문제를 짚었는가","누가 언제 낸 자료인지 밝힌 근거로 바꾸어 썼는가"]},"explanation":["누리집의 문제를 짚어요.","많은 사람 · 이모의 말을 따져요.","확인할 수 있는 근거로 바꿔요."],"asset":{"type":"passage","lines":["학교 주변 도로의 제한 속도를 더 낮춰서는 안 된다고 생각합니다.","어떤 누리집에서 봤는데, 속도를 낮추면 오히려 사고가 는다고 합니다.","많은 사람이 그렇게 말합니다.","게다가 저희 이모께서 운전할 때 답답하다고 하셨습니다.","따라서 제한 속도를 낮출 필요는 없습니다."],"title":"어느 학생이 쓴 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#1','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C37',1,'mc','auto','역사 갈래에서 토론 주제가 되는 것은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C37","difficulty":1,"kind":"mc","stem":"역사 갈래에서 토론 주제가 되는 것은 어느 것인가요?","options":[{"t":"우리 지역의 옛 성곽을 원래 모습으로 되살려야 하는가","correct":true},{"t":"그 성곽이 몇 해에 쌓였는가","mis":"K6-1-u3-X01"},{"t":"조선의 도읍이 어디였는가","mis":"K6-1-u3-X01"},{"t":"성곽의 길이가 얼마인가","mis":"K6-1-u3-X01"}],"explanation":["쌓은 해는 찾으면 나와요.","도읍은 자료로 확인돼요.","평가와 선택이 갈리는 물음이라야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#2','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C39',1,'mc','auto','원탁 토론에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X03']::text[],false,'{"seq":2,"concept":"K6-1-u3-C39","difficulty":1,"kind":"mc","stem":"원탁 토론에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"편을 나누지 않고 모두가 대등하게 돌아가며 말한다","correct":true},{"t":"찬성 측과 반대 측으로 나뉘어 정해진 단계대로 겨룬다","mis":"K6-1-u3-X41"},{"t":"사회자와 판정단이 꼭 있어야 한다","mis":"K6-1-u3-X41"},{"t":"한 사람만 계속 말한다","mis":"K6-1-u3-X03"}],"explanation":["편을 나누는 것은 찬반 토론이에요.","원탁 토론은 사회자를 따로 두지 않아요.","모두가 돌아가며 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#3','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C43',1,'mc','auto','「굵다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":3,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「굵다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[국따]","correct":true},{"t":"[굴따]","mis":"K6-1-u3-X44"},{"t":"[굵다]","mis":"K6-1-u3-X44"},{"t":"[구따]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄷ이 왔어요.","ㄺ은 [ㄱ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#4','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C40',1,'ox','auto','역사에 관한 논쟁에서는 한쪽이 옳고 다른 쪽은 틀렸다고 가려야 해요.',ARRAY['K6-1-u3-X42']::text[],false,'{"seq":4,"concept":"K6-1-u3-C40","difficulty":1,"kind":"ox","stem":"역사에 관한 논쟁에서는 한쪽이 옳고 다른 쪽은 틀렸다고 가려야 해요.","answer":"X","reason_options":[{"t":"옳고 그름이 아니라 무엇을 더 중요하게 여겼는지 관점이 다르기 때문에","correct":true},{"t":"역사에는 언제나 정답이 하나뿐이기 때문에","mis":"K6-1-u3-X42"}],"mis":"K6-1-u3-X42","explanation":["두 쪽 다 역사를 아낄 수 있어요.","아끼는 방법에 대한 생각이 달라요.","관점의 차이로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#5','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C4',2,'match','auto','성곽 토론의 발언을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K6-1-u3-C4","difficulty":2,"kind":"match","stem":"성곽 토론의 발언을 알맞게 이으세요.","pairs":[{"l":"모습을 갖춰야 고장의 역사를 배우는 곳이 된다","r":"찬성 측 이유"},{"l":"되살린 다른 고장 성곽의 방문자 기록","r":"찬성 측 근거"},{"l":"새로 만든 부분이 많으면 옛 성곽이라 하기 어렵다","r":"반대 측 이유"},{"l":"도청이 낸 복원 기준 안내 자료","r":"반대 측 근거"}],"mis":"K6-1-u3-X04","explanation":["까닭인지 자료인지 먼저 나눠요.","그다음 찬반을 갈라요.","같은 대상을 두고도 근거가 갈려요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#6','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C38',2,'mc','auto','모둠이 근거를 모으는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X43','K6-1-u3-X22']::text[],false,'{"seq":6,"concept":"K6-1-u3-C38","difficulty":2,"kind":"mc","stem":"모둠이 근거를 모으는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"찾을 영역을 나누고, 누가 언제 낸 자료인지 적고, 바꾸어 읽은 뒤 가장 센 두 가지를 고른다","correct":true},{"t":"모은 자료를 하나도 빼지 않고 모두 준비표에 옮긴다","mis":"K6-1-u3-X43"},{"t":"출처는 적지 않고 내용만 적는다","mis":"K6-1-u3-X22"},{"t":"한 사람이 모든 자료를 혼자 찾아 그대로 쓴다","mis":"K6-1-u3-X43"}],"explanation":["모두 옮기면 약한 것까지 들어가요.","출처를 함께 적어요.","나누어 찾고 골라 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#7','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C41',2,'mc','auto','토론을 마친 뒤 할 말로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18','K6-1-u3-X39']::text[],false,'{"seq":7,"concept":"K6-1-u3-C41","difficulty":2,"kind":"mc","stem":"토론을 마친 뒤 할 말로 알맞은 것은 어느 것인가요?","options":[{"t":"「사회를 맡은 친구가 말차례를 잘 지켜 줬어. 나는 성곽 기준 자료를 처음 알았어.」","correct":true},{"t":"「역시 우리 편이 이겼네. 상대는 준비가 부족했어.」","mis":"K6-1-u3-X40"},{"t":"「판정이 이상했어. 기준을 잘못 잡은 것 같아.」","mis":"K6-1-u3-X18"},{"t":"「생각이 바뀌었으니 내가 진 거야.」","mis":"K6-1-u3-X39"}],"explanation":["승패와 깎아내리기만 남기지 않아요.","판정에는 승복해요.","잘한 곳과 새로 안 것을 나눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#8','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C43',2,'mc','auto','「옮기다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":2,"kind":"mc","stem":"「옮기다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[옴기다]","correct":true},{"t":"[올기다]","mis":"K6-1-u3-X44"},{"t":"[오기다]","mis":"K6-1-u3-X44"},{"t":"[옮끼다]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 자음이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","[옴기다]로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#9','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C42',2,'mc','auto','토론을 잘하는 사람의 모습으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X07','K6-1-u3-X08']::text[],false,'{"seq":9,"concept":"K6-1-u3-C42","difficulty":2,"kind":"mc","stem":"토론을 잘하는 사람의 모습으로 알맞은 것은 어느 것인가요?","options":[{"t":"반론할 때 사람이 아니라 근거를 겨눈다","correct":true},{"t":"말을 가장 많이, 가장 크게 한다","mis":"K6-1-u3-X45"},{"t":"상대가 말할 때 끼어들어 되받는다","mis":"K6-1-u3-X07"},{"t":"준비한 원고를 처음부터 끝까지 읽는다","mis":"K6-1-u3-X08"}],"explanation":["많이 · 크게 말하는 것과 잘하는 것은 달라요.","말차례를 지켜요.","근거를 겨누어 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_basic#10','kor',6,1,'u3','L11','g6_1_kor_u3_L11_basic','lesson_basic','K6-1-u3-C26',3,'mc','auto','사물함 토론에서 어느 쪽 근거가 더 타당한가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X35','K6-1-u3-X31']::text[],false,'{"seq":10,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"사물함 토론에서 어느 쪽 근거가 더 타당한가요?","options":[{"t":"찬성 측 — 지난달에 백쉰 명에게 물어 조사한 때와 사람 수가 분명하다","correct":true},{"t":"반대 측 — 친구에게 직접 물어본 이야기라 더 생생하다","mis":"K6-1-u3-X32"},{"t":"둘 다 똑같다 — 사람에게 물어본 자료라는 점이 같다","mis":"K6-1-u3-X35"},{"t":"둘 다 근거가 아니다 — 사람에게 물은 것은 근거가 될 수 없다","mis":"K6-1-u3-X31"}],"explanation":["생생함보다 구체성을 봐요.","언제 · 몇 명에게 물었는지 견줘요.","백쉰 명과 두 명은 같은 무게가 아니에요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#1','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C39',2,'mc','auto','원탁 토론이 찬반 토론보다 알맞은 경우는 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X09','K6-1-u3-X05']::text[],false,'{"seq":1,"concept":"K6-1-u3-C39","difficulty":2,"kind":"mc","stem":"원탁 토론이 찬반 토론보다 알맞은 경우는 어느 것인가요?","options":[{"t":"답이 찬성과 반대 둘로 갈리지 않는 문제를 이야기할 때","correct":true},{"t":"판정단이 꼭 승패를 정해야 할 때","mis":"K6-1-u3-X41"},{"t":"한쪽 편이 반드시 이겨야 할 때","mis":"K6-1-u3-X09"},{"t":"근거 없이 말해도 될 때","mis":"K6-1-u3-X05"}],"explanation":["승패를 정하는 것은 찬반 토론이에요.","이기려는 것이 목적이 아니에요.","어느 토론이든 근거를 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#2','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',2,'ox','auto','「늙고」는 [늘꼬]로 읽어요.',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":2,"concept":"K6-1-u3-C43","difficulty":2,"kind":"ox","stem":"「늙고」는 [늘꼬]로 읽어요.","answer":"O","reason_options":[{"t":"ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나고 뒤의 ㄱ은 된소리가 되기 때문에","correct":true},{"t":"겹받침은 언제나 두 자음을 모두 소리 내기 때문에","mis":"K6-1-u3-X44"}],"mis":"K6-1-u3-X44","explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","[늘꼬]로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#3','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C40',3,'mc','auto','벼리와 윤재의 생각을 알맞게 정리한 말은 어느 것인가요?',ARRAY['K6-1-u3-X42','K6-1-u3-X02']::text[],false,'{"seq":3,"concept":"K6-1-u3-C40","difficulty":3,"kind":"mc","stem":"벼리와 윤재의 생각을 알맞게 정리한 말은 어느 것인가요?","options":[{"t":"한쪽은 배움의 기회를, 다른 쪽은 남은 것의 진짜 모습을 앞에 두었다","correct":true},{"t":"벼리는 역사를 아끼고 윤재는 역사를 아끼지 않는다","mis":"K6-1-u3-X42"},{"t":"되살리자는 쪽이 옳고 반대하는 쪽은 틀렸다","mis":"K6-1-u3-X42"},{"t":"두 사람은 편을 나누지 않고 같은 방법을 찾고 있다","mis":"K6-1-u3-X02"}],"explanation":["두 사람 다 역사를 아껴요.","옳고 그름으로 가르지 않아요.","무엇을 더 중요하게 여겼는지 봐요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#4','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C37',3,'mc','auto','실천 토론에서 주제를 고를 때의 조건으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X19','K6-1-u3-X01','K6-1-u3-X20']::text[],false,'{"seq":4,"concept":"K6-1-u3-C37","difficulty":3,"kind":"mc","stem":"실천 토론에서 주제를 고를 때의 조건으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 갈래든 찬반이 갈리고 양쪽 모두 근거를 찾을 수 있어야 한다","correct":true},{"t":"역사 갈래에서만 고를 수 있다","mis":"K6-1-u3-X19"},{"t":"연도나 이름처럼 답이 하나로 나오는 물음이 좋다","mis":"K6-1-u3-X01"},{"t":"한쪽 근거만 있으면 된다","mis":"K6-1-u3-X20"}],"explanation":["역사 · 환경 · 생활 어디서든 찾아요.","답이 하나로 나오면 토론이 안 돼요.","양쪽 모두 근거를 찾을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#5','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C38',3,'mc','auto','「모습을 갖춰야 역사를 배우는 곳이 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X27','K6-1-u3-X28']::text[],false,'{"seq":5,"concept":"K6-1-u3-C38","difficulty":3,"kind":"mc","stem":"「모습을 갖춰야 역사를 배우는 곳이 된다」는 이유를 뒷받침할 근거로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"되살린 다른 고장 성곽의 학생 단체 관람 수가 해마다 는 기록","correct":true},{"t":"돌담만 있으면 심심할 것 같다는 내 느낌","mis":"K6-1-u3-X04"},{"t":"공사에는 시간이 오래 걸린다는 일반적인 이야기","mis":"K6-1-u3-X27"},{"t":"어디서 봤는지 모르는 여행 동영상","mis":"K6-1-u3-X28"}],"explanation":["느낌은 근거가 아니에요.","공사 기간은 이유와 이어지지 않아요.","이유와 이어지고 확인할 수 있는 기록이에요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#6','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',3,'error','auto','겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":6,"concept":"K6-1-u3-C43","difficulty":3,"kind":"error","stem":"겹받침 낱말을 읽었어요. 잘못 읽은 친구는 누구인가요?","options":[{"t":"라온 — 「굵고」를 [국꼬]로 읽었다","correct":true,"mis_target":"K6-1-u3-X44"},{"t":"하율 — 「읊다」를 [읍따]로 읽었다","mis":"K6-1-u3-X44"},{"t":"서진 — 「젊지」를 [점찌]로 읽었다","mis":"K6-1-u3-X44"}],"explanation":["하율은 ㄿ을 [ㅂ]으로 읽었어요.","서진은 ㄻ을 [ㅁ]으로 읽었어요.","ㄺ 뒤에 ㄱ이 오면 [ㄹ] — [굴꼬]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#7','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C42',3,'mc','auto','「자신감 있게, 그러면서도 예의 바르게 표현하는 힘」이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X45','K6-1-u3-X05','K6-1-u3-X14']::text[],false,'{"seq":7,"concept":"K6-1-u3-C42","difficulty":3,"kind":"mc","stem":"「자신감 있게, 그러면서도 예의 바르게 표현하는 힘」이 필요한 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"근거가 좋아도 무례하게 말하면 듣는 사람이 받아들이기 어렵기 때문에","correct":true},{"t":"크게 말할수록 이기기 때문에","mis":"K6-1-u3-X45"},{"t":"예의만 지키면 근거는 없어도 되기 때문에","mis":"K6-1-u3-X05"},{"t":"상대 말투를 겨누기 위해서","mis":"K6-1-u3-X14"}],"explanation":["크게 말한다고 이기지 않아요.","근거도 함께 있어야 해요.","자신감과 예의가 함께 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#8','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C41',4,'mc','auto','토론 뒤 소감 나누기에서 가장 알맞게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X42','K6-1-u3-X39']::text[],false,'{"seq":8,"concept":"K6-1-u3-C41","difficulty":4,"kind":"mc","stem":"토론 뒤 소감 나누기에서 가장 알맞게 말한 것은 어느 것인가요?","options":[{"t":"「반대 측이 낸 복원 기준 자료를 듣고 되살릴 때 무엇을 지켜야 하는지 생각이 더 깊어졌어. 판정을 맡은 친구가 기준을 먼저 밝혀서 좋았어.」","correct":true},{"t":"「우리 편이 이겼으니 더 할 말이 없어.」","mis":"K6-1-u3-X40"},{"t":"「반대 측은 역사를 모르는 거야.」","mis":"K6-1-u3-X42"},{"t":"「생각이 바뀌면 진 거라 끝까지 안 바꿨어.」","mis":"K6-1-u3-X39"}],"explanation":["승패만 말하면 남는 것이 없어요.","상대 관점을 낮추지 않아요.","새로 안 것과 잘한 친구를 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#9','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C40',4,'essay','teacher','성곽 토론에서 찬성 측과 반대 측이 각각 무엇을 중요하게 여겼는지 쓰고, 역사 문제로 토론할 때 상대 생각을 어떻게 대해야 하는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K6-1-u3-C40","difficulty":4,"kind":"essay","stem":"성곽 토론에서 찬성 측과 반대 측이 각각 무엇을 중요하게 여겼는지 쓰고, 역사 문제로 토론할 때 상대 생각을 어떻게 대해야 하는지 쓰세요.","answer_guide":{"answer":"예: 찬성 측 벼리는 사람들이 고장의 역사를 배울 수 있는 기회를 중요하게 여겼다. 반대 측 윤재는 남아 있는 옛 성곽의 진짜 모습을 지키는 것을 중요하게 여겼다. 두 사람 다 역사를 아끼지만 아끼는 방법이 다르다. 역사에 관한 논쟁에는 옳고 그름이 아니라 관점의 차이가 있으므로, 한쪽을 틀린 편으로 만들지 않고 판정 뒤에도 상대 생각을 낮추어 말하지 않아야 한다.","scoring_points":["찬성 측이 중요하게 여긴 것을 썼는가","반대 측이 중요하게 여긴 것을 썼는가","관점의 차이로 보고 상대를 낮추지 않는 태도를 썼는가"]},"explanation":["벼리가 앞에 둔 것을 찾아요.","윤재가 앞에 둔 것을 찾아요.","옳고 그름 대신 관점으로 봐요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 벼리","text":"옛 성곽을 원래 모습으로 되살려야 합니다. 지금은 돌담 일부만 남아 있어 사람들이 그곳이 성곽이었는지도 모르고 지나갑니다. 모습을 갖춰야 고장의 역사를 배우는 곳이 됩니다."},{"who":"반대 측 윤재","text":"되살려서는 안 됩니다. 남아 있는 부분이 적어 되살리려면 대부분을 새로 만들어야 합니다. 새로 만든 부분이 많아지면 그것은 옛 성곽이 아니라 새 건물입니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_L11_challenge#10','kor',6,1,'u3','L11','g6_1_kor_u3_L11_challenge','lesson_challenge','K6-1-u3-C43',4,'essay','teacher','ㄻ · ㄿ · ㄺ 겹받침이 있는 낱말을 하나씩 골라 소리 나는 대로 쓰고, 겹받침을 읽는 규칙을 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"K6-1-u3-C43","difficulty":4,"kind":"essay","stem":"ㄻ · ㄿ · ㄺ 겹받침이 있는 낱말을 하나씩 골라 소리 나는 대로 쓰고, 겹받침을 읽는 규칙을 설명하세요.","answer_guide":{"answer":"예: 닮다 [담따] · 읊다 [읍따] · 붉다 [북따]. 겹받침 뒤에 자음이 오면 두 자음 가운데 하나만 소리 난다. ㄻ은 [ㅁ], ㄿ은 [ㅂ], ㄺ은 [ㄱ]으로 소리 나고, 그 뒤에 오는 ㄱ · ㄷ · ㅂ · ㅅ · ㅈ은 된소리가 된다. 다만 ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나서 「붉고」는 [불꼬]로 읽는다.","scoring_points":["세 겹받침 낱말을 하나씩 바르게 소리 나는 대로 썼는가","하나만 소리 나고 뒤 자음이 된소리가 된다는 규칙을 썼는가","ㄺ 뒤에 ㄱ이 올 때의 예외를 썼는가"]},"explanation":["세 겹받침을 하나씩 골라요.","어느 자음이 소리 나는지 써요.","ㄺ 뒤 ㄱ의 경우를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#1','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C3',1,'mc','auto','찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기를 무엇이라고 하나요?',ARRAY['K6-1-u3-X02','K6-1-u3-X03']::text[],false,'{"seq":1,"concept":"K6-1-u3-C3","difficulty":1,"kind":"mc","stem":"찬성과 반대로 나뉘어 근거를 들어 자기 주장이 옳음을 밝히는 말하기를 무엇이라고 하나요?","options":[{"t":"토론","correct":true},{"t":"토의","mis":"K6-1-u3-X02"},{"t":"연설","mis":"K6-1-u3-X03"},{"t":"대화","mis":"K6-1-u3-X02"}],"explanation":["토의는 편을 나누지 않아요.","연설은 한 사람이 알리는 말하기예요.","찬반으로 나뉘어 겨루면 토론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#2','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C4',1,'mc','auto','이유를 뒷받침하는 객관적인 자료를 무엇이라고 하나요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"이유를 뒷받침하는 객관적인 자료를 무엇이라고 하나요?","options":[{"t":"근거","correct":true},{"t":"주장","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"반론","mis":"K6-1-u3-X06"}],"explanation":["주장은 내세우는 생각이에요.","이유는 내 까닭이에요.","밖에서 가져온 자료가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#3','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C5',1,'mc','auto','토론의 첫 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"mc","stem":"토론의 첫 단계는 무엇인가요?","options":[{"t":"주장 펼치기","correct":true},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["반론은 주장을 들은 뒤에 해요.","다지기는 셋째 단계예요.","먼저 주장을 펼쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#4','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',1,'ox','auto','반론할 때에는 상대의 말투나 사람이 아니라 주장 · 이유 · 근거를 겨누어요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":1,"kind":"ox","stem":"반론할 때에는 상대의 말투나 사람이 아니라 주장 · 이유 · 근거를 겨누어요.","answer":"O","reason_options":[{"t":"토론은 근거를 겨루는 공식적인 말하기이기 때문에","correct":true},{"t":"사람을 겨누어야 상대가 물러서기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["사람을 겨누면 반론이 아니에요.","공식적인 말하기예요.","주장 · 이유 · 근거를 겨눠요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#5','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C15',1,'mc','auto','판정단이 판정하기 전에 먼저 밝혀야 하는 것은 무엇인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X24']::text[],false,'{"seq":5,"concept":"K6-1-u3-C15","difficulty":1,"kind":"mc","stem":"판정단이 판정하기 전에 먼저 밝혀야 하는 것은 무엇인가요?","options":[{"t":"판정 기준","correct":true},{"t":"평소 자기 생각","mis":"K6-1-u3-X16"},{"t":"친한 친구 이름","mis":"K6-1-u3-X24"},{"t":"좋아하는 편","mis":"K6-1-u3-X24"}],"explanation":["평소 생각은 판정과 관계없어요.","친한 사이도 관계없어요.","기준을 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#6','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C23',1,'mc','auto','주제와 규칙을 알리고 말차례를 이끄는 역할은 무엇인가요?',ARRAY['K6-1-u3-X25']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"mc","stem":"주제와 규칙을 알리고 말차례를 이끄는 역할은 무엇인가요?","options":[{"t":"사회자","correct":true},{"t":"토론자","mis":"K6-1-u3-X25"},{"t":"판정단","mis":"K6-1-u3-X25"},{"t":"청중","mis":"K6-1-u3-X25"}],"explanation":["토론자는 주장을 말해요.","판정단은 판정해요.","이끄는 사람은 사회자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#7','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C26',1,'mc','auto','근거를 따질 때 던지는 물음으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":1,"kind":"mc","stem":"근거를 따질 때 던지는 물음으로 알맞은 것은 어느 것인가요?","options":[{"t":"「출처가 분명한가?」","correct":true},{"t":"「글씨가 예쁜가?」","mis":"K6-1-u3-X35"},{"t":"「자료가 길고 어려운가?」","mis":"K6-1-u3-X30"},{"t":"「내 마음에 드는가?」","mis":"K6-1-u3-X35"}],"explanation":["글씨는 상관없어요.","길이도 상관없어요.","어디서 나왔는지 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#8','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C43',1,'mc','auto','「읊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「읊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[읍따]","correct":true},{"t":"[을따]","mis":"K6-1-u3-X44"},{"t":"[읊다]","mis":"K6-1-u3-X44"},{"t":"[으따]","mis":"K6-1-u3-X44"}],"explanation":["ㄿ 뒤에 ㄷ이 왔어요.","ㄿ은 [ㅂ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#9','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C9',2,'mc','auto','도담이가 주장 펼치기에서 낸 근거는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05','K6-1-u3-X28']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"mc","stem":"도담이가 주장 펼치기에서 낸 근거는 무엇인가요?","options":[{"t":"도서부가 이번 학기에 고학년 이백 명에게 물은 설문","correct":true},{"t":"쉬는 시간만으로는 책을 고를 시간이 모자란다","mis":"K6-1-u3-X04"},{"t":"점심시간에도 도서실을 열어야 한다","mis":"K6-1-u3-X05"},{"t":"어떤 누리집에서 본 이야기","mis":"K6-1-u3-X28"}],"explanation":["시간이 모자란다는 것은 이유예요.","열어야 한다는 것은 주장이에요.","물어서 센 설문이 근거예요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#10','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',2,'mc','auto','서아의 첫 반론이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X26','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C13","difficulty":2,"kind":"mc","stem":"서아의 첫 반론이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"「그것도 모르십니까?」처럼 사람을 겨누었기 때문에","correct":true},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X26"},{"t":"주제와 이어졌기 때문에","mis":"K6-1-u3-X11"}],"explanation":["높임말은 써야 해요.","짧은 것은 문제가 아니에요.","사람을 겨누면 반론이 아니에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#11','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C14',2,'mc','auto','서아의 주장 다지기가 약한 까닭은 무엇인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X17','K6-1-u3-X22']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"서아의 주장 다지기가 약한 까닭은 무엇인가요?","options":[{"t":"반론에서 무너진 누리집 근거를 다시 꺼냈기 때문에","correct":true},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X15"},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"새 근거를 찾아 왔기 때문에","mis":"K6-1-u3-X22"}],"explanation":["짧은 것은 오히려 좋아요.","높임말은 써야 해요.","무너진 근거를 꺼내면 약해져요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#12','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C33',2,'mc','auto','지우의 판정이 알맞지 않은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X16','K6-1-u3-X18']::text[],false,'{"seq":12,"concept":"K6-1-u3-C33","difficulty":2,"kind":"mc","stem":"지우의 판정이 알맞지 않은 까닭은 무엇인가요?","options":[{"t":"기준 없이 평소 자기 생각과 같은 편을 골랐기 때문에","correct":true},{"t":"찬성 측을 골랐기 때문에","mis":"K6-1-u3-X17"},{"t":"짧게 말했기 때문에","mis":"K6-1-u3-X16"},{"t":"판정을 했기 때문에","mis":"K6-1-u3-X18"}],"explanation":["어느 편을 골랐는지가 문제가 아니에요.","길이가 문제가 아니에요.","평소 생각으로 정한 것이 문제예요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#13','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C34',2,'mc','auto','은솔이의 메모 가운데 되받을 거리로 쓰기 어려운 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"mc","stem":"은솔이의 메모 가운데 되받을 거리로 쓰기 어려운 것은 어느 것인가요?","options":[{"t":"반대 측 말투 — 목소리가 컸음.","correct":true},{"t":"찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","mis":"K6-1-u3-X12"},{"t":"반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","mis":"K6-1-u3-X08"},{"t":"반대 측이 꺼낸 다른 이야기 — 급식 줄.","mis":"K6-1-u3-X08"}],"explanation":["근거의 출처는 되받을 거리예요.","밝히지 않은 출처도 짚을 곳이에요.","말투는 되받을 거리가 아니에요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#14','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C22',2,'mc','auto','예상 반론에 미리 답변을 준비하는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X23','K6-1-u3-X16']::text[],false,'{"seq":14,"concept":"K6-1-u3-C22","difficulty":2,"kind":"mc","stem":"예상 반론에 미리 답변을 준비하는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"그 과정에서 내 근거의 약한 곳을 스스로 점검하게 되기 때문에","correct":true},{"t":"상대 원고를 미리 알 수 있기 때문에","mis":"K6-1-u3-X09"},{"t":"토론에서 반론하기를 건너뛰기 위해서","mis":"K6-1-u3-X23"},{"t":"판정단에게 점수를 받기 위해서","mis":"K6-1-u3-X16"}],"explanation":["상대 원고는 알 수 없어요.","반론하기는 건너뛰지 않아요.","내 근거의 약한 곳이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#15','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C18',2,'mc','auto','우리 반 토론 주제를 고를 때 따질 조건을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X20','K6-1-u3-X19']::text[],false,'{"seq":15,"concept":"K6-1-u3-C18","difficulty":2,"kind":"mc","stem":"우리 반 토론 주제를 고를 때 따질 조건을 바르게 말한 것은 어느 것인가요?","options":[{"t":"친구들이 관심 있고, 찬반이 갈리고, 양쪽 근거를 찾을 수 있고, 우리 힘으로 바꿀 수 있는가","correct":true},{"t":"답이 정해져 있고 확인이 쉬운가","mis":"K6-1-u3-X01"},{"t":"한쪽 편만 있는가","mis":"K6-1-u3-X20"},{"t":"우리가 바꿀 수 없는 먼 일인가","mis":"K6-1-u3-X19"}],"explanation":["답이 정해지면 토론이 안 돼요.","찬반이 갈려야 해요.","관심 · 찬반 · 근거 · 바꿔 볼 수 있음을 따져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#16','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C29',2,'mc','auto','경험을 근거로 쓰는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X31','K6-1-u3-X04']::text[],false,'{"seq":16,"concept":"K6-1-u3-C29","difficulty":2,"kind":"mc","stem":"경험을 근거로 쓰는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"느낌으로 두지 말고 세거나 재어서 정리해 내놓는다","correct":true},{"t":"나에게만 일어난 드문 일을 고른다","mis":"K6-1-u3-X32"},{"t":"경험은 근거가 될 수 없으니 쓰지 않는다","mis":"K6-1-u3-X31"},{"t":"생생하게 느낌만 말한다","mis":"K6-1-u3-X04"}],"explanation":["드문 일은 근거가 되기 어려워요.","경험도 근거가 될 수 있어요.","세거나 재어 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#17','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C24',3,'mc','auto','찬반 토론의 진행 순서로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":17,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"찬반 토론의 진행 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 펼치기 → 반대 측 반론과 찬성 측 답변 → 찬성 측 반론과 반대 측 답변 → 주장 다지기 → 판정","correct":true},{"t":"판정 → 주장 펼치기 → 반론 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"반론 → 주장 펼치기 → 판정 → 주장 다지기","mis":"K6-1-u3-X06"},{"t":"주장 펼치기 → 주장 다지기 → 판정 → 반론","mis":"K6-1-u3-X06"}],"explanation":["판정은 맨 끝이에요.","반론은 펼친 뒤에 해요.","두 편이 번갈아 반론하고 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#18','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C28',3,'mc','auto','사물함 토론에서 새얀이의 근거를 더 타당하게 바꾸는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X32','K6-1-u3-X30','K6-1-u3-X28']::text[],false,'{"seq":18,"concept":"K6-1-u3-C28","difficulty":3,"kind":"mc","stem":"사물함 토론에서 새얀이의 근거를 더 타당하게 바꾸는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"언제, 몇 명에게 물었는지 밝혀 우리 반이나 학년 전체에게 물어본다","correct":true},{"t":"친구 두 명의 말을 더 생생하게 꾸민다","mis":"K6-1-u3-X32"},{"t":"두 명에게 다섯 번씩 묻는다","mis":"K6-1-u3-X30"},{"t":"누리집 이야기를 덧붙인다","mis":"K6-1-u3-X28"}],"explanation":["생생하게 꾸며도 두 명이에요.","같은 사람에게 여러 번 물어도 그대로예요.","대상을 넓히고 때를 밝혀요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#19','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C12',3,'error','auto','반론에 대한 답변을 했어요. 알맞지 않은 답변을 한 친구는 누구인가요?',ARRAY['K6-1-u3-X13']::text[],false,'{"seq":19,"concept":"K6-1-u3-C12","difficulty":3,"kind":"error","stem":"반론에 대한 답변을 했어요. 알맞지 않은 답변을 한 친구는 누구인가요?","options":[{"t":"이안 — 「어쨌든 저희가 맞습니다. 맞으니까 맞습니다.」","correct":true,"mis_target":"K6-1-u3-X13"},{"t":"서윤 — 「그 점은 인정합니다. 다만 서로 다른 학년 사이의 일이 더 많았습니다.」","mis":"K6-1-u3-X13"},{"t":"하람 — 「조사한 때는 자료 맨 위에 적혀 있습니다.」","mis":"K6-1-u3-X13"}],"explanation":["서윤은 인정하고 다시 세웠어요.","하람은 물은 것에 곧바로 답했어요.","이안은 같은 말을 되풀이했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#20','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C36',3,'mc','auto','도서실 토론 뒤 세 친구의 말 가운데 가장 알맞게 마무리한 사람은 누구인가요?',ARRAY['K6-1-u3-X18','K6-1-u3-X40','K6-1-u3-X39']::text[],false,'{"seq":20,"concept":"K6-1-u3-C36","difficulty":3,"kind":"mc","stem":"도서실 토론 뒤 세 친구의 말 가운데 가장 알맞게 마무리한 사람은 누구인가요?","options":[{"t":"도담 — 상대 근거에서 미처 생각 못 한 점을 받아들이고 더 찾아보려 했다","correct":true},{"t":"서아 — 판정이 이상하다며 판정단 탓을 했다","mis":"K6-1-u3-X18"},{"t":"아무도 없다 — 토론 뒤에는 승패만 말하면 된다","mis":"K6-1-u3-X40"},{"t":"아무도 없다 — 생각이 바뀌면 진 것이다","mis":"K6-1-u3-X39"}],"explanation":["판정에는 승복해요.","승패만 남기지 않아요.","생각을 남기는 마무리가 좋아요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#21','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C40',3,'mc','auto','「옛 건물을 헐고 남은 터를 공원으로 만들어야 한다」를 두고 토론할 때 알맞은 태도는 어느 것인가요?',ARRAY['K6-1-u3-X42','K6-1-u3-X40']::text[],false,'{"seq":21,"concept":"K6-1-u3-C40","difficulty":3,"kind":"mc","stem":"「옛 건물을 헐고 남은 터를 공원으로 만들어야 한다」를 두고 토론할 때 알맞은 태도는 어느 것인가요?","options":[{"t":"서로 무엇을 더 중요하게 여기는지 관점의 차이로 보고 상대 생각을 낮추어 말하지 않는다","correct":true},{"t":"공원으로 만들자는 쪽이 옳다고 먼저 정해 둔다","mis":"K6-1-u3-X42"},{"t":"역사를 아끼는 쪽과 아끼지 않는 쪽으로 나눈다","mis":"K6-1-u3-X42"},{"t":"판정 뒤 상대 생각은 틀렸다고 말한다","mis":"K6-1-u3-X40"}],"explanation":["옳은 쪽을 먼저 정하지 않아요.","두 쪽 다 아낄 수 있어요.","관점의 차이로 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#22','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C43',3,'mc','auto','「밝고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「밝고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[발꼬]","correct":true},{"t":"[박꼬]","mis":"K6-1-u3-X44"},{"t":"[발고]","mis":"K6-1-u3-X44"},{"t":"[밝고]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#23','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C27',4,'mc','auto','반대 측 서아의 주장 펼치기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X05','K6-1-u3-X32']::text[],false,'{"seq":23,"concept":"K6-1-u3-C27","difficulty":4,"kind":"mc","stem":"반대 측 서아의 주장 펼치기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"이유는 그대로 두고, 「어떤 누리집」 대신 학교가 올해 낸 도서실 운영 안내처럼 누가 언제 냈는지 확인되는 자료를 근거로 든다","correct":true},{"t":"누리집 이야기를 「많은 누리집」으로 바꾼다","mis":"K6-1-u3-X29"},{"t":"근거를 빼고 이유만 여러 번 말한다","mis":"K6-1-u3-X05"},{"t":"자기 친구 한 명의 느낌을 근거로 더한다","mis":"K6-1-u3-X32"}],"explanation":["「많은」도 흐릿해요.","근거를 빼면 확인할 수 없어요.","출처가 분명한 자료로 바꿔요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#24','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C13',4,'essay','teacher','서아의 반론 두 군데에서 알맞지 않은 점을 찾아 쓰고, 찬성 측 근거를 겨누는 알맞은 반론으로 고쳐 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C13","difficulty":4,"kind":"essay","stem":"서아의 반론 두 군데에서 알맞지 않은 점을 찾아 쓰고, 찬성 측 근거를 겨누는 알맞은 반론으로 고쳐 쓰세요.","answer_guide":{"answer":"예: 첫째, 「그것도 모르십니까?」는 근거가 아니라 사람을 겨눈 말이다. 둘째, 「급식 줄이 더 문제」는 주장 펼치기에서 나온 내용과 상관없는 새 이야기이다. 고친 반론 — 「찬성 측 설문은 빌리고 싶다고 답한 학생 수를 보여 줍니다. 그런데 실제로 점심시간에 도서실에 올 수 있는 학생이 몇 명인지는 나와 있지 않습니다.」","scoring_points":["사람을 겨눈 점을 찾았는가","주제와 상관없는 이야기를 꺼낸 점을 찾았는가","찬성 측 근거를 겨누는 반론을 높임말로 썼는가"]},"explanation":["겨눈 곳이 어디인지 봐요.","주장 펼치기와 이어지는지 봐요.","근거를 겨누어 고쳐요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_a#25','kor',6,1,'u3','','g6_1_kor_u3_review_a','unit_review','K6-1-u3-C5',4,'essay','teacher','토론의 네 단계를 차례대로 쓰고, 각 단계에서 지켜야 할 절차나 규칙을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C5","difficulty":4,"kind":"essay","stem":"토론의 네 단계를 차례대로 쓰고, 각 단계에서 지켜야 할 절차나 규칙을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 주장 펼치기 — 주장과 이유, 근거를 함께 낸다. 반론하기 — 주장 펼치기에서 나온 내용에 대해서만 되받고, 사람이 아니라 근거를 겨눈다. 주장 다지기 — 같은 말을 되풀이하지 않고 남은 것만 추려 다시 세운다. 판정하기 — 판정단이 기준을 먼저 밝히고 토론에서 나온 내용만으로 정한다.","scoring_points":["네 단계를 차례대로 썼는가","단계마다 알맞은 규칙을 썼는가","판정에서 기준을 밝힌다는 점을 썼는가"]},"explanation":["네 단계의 이름을 차례로 써요.","단계마다 규칙을 하나씩 써요.","판정 기준을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#1','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C2',1,'ox','auto','토의는 편을 나누어 겨루고, 토론은 편 없이 방법을 모으는 말하기예요.',ARRAY['K6-1-u3-X02']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":1,"kind":"ox","stem":"토의는 편을 나누어 겨루고, 토론은 편 없이 방법을 모으는 말하기예요.","answer":"X","reason_options":[{"t":"반대로 토의는 편 없이 방법을 모으고, 토론은 찬반으로 나뉘어 겨루기 때문에","correct":true},{"t":"둘은 이름만 다르고 같은 말하기이기 때문에","mis":"K6-1-u3-X02"}],"mis":"K6-1-u3-X02","explanation":["두 말이 뒤바뀌었어요.","토의는 함께 방법을 모아요.","토론은 찬반으로 나뉘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#2','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C4',1,'mc','auto','내가 옳다고 내세우는 생각을 무엇이라고 하나요?',ARRAY['K6-1-u3-X04','K6-1-u3-X06']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"mc","stem":"내가 옳다고 내세우는 생각을 무엇이라고 하나요?","options":[{"t":"주장","correct":true},{"t":"근거","mis":"K6-1-u3-X04"},{"t":"이유","mis":"K6-1-u3-X04"},{"t":"판정","mis":"K6-1-u3-X06"}],"explanation":["근거는 자료예요.","이유는 까닭이에요.","내세우는 생각이 주장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#3','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C5',1,'mc','auto','토론의 마지막 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"mc","stem":"토론의 마지막 단계는 무엇인가요?","options":[{"t":"판정하기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"}],"explanation":["펼치기는 첫 단계예요.","반론은 둘째 단계예요.","판정은 맨 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#4','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C13',1,'mc','auto','반론으로 알맞은 말은 어느 것인가요?',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C13","difficulty":1,"kind":"mc","stem":"반론으로 알맞은 말은 어느 것인가요?","options":[{"t":"「그 자료는 조사한 때가 나와 있지 않습니다.」","correct":true},{"t":"「그것도 모르십니까?」","mis":"K6-1-u3-X14"},{"t":"「그런 게 어디 있습니까?」","mis":"K6-1-u3-X14"},{"t":"「준비를 안 하셨군요.」","mis":"K6-1-u3-X14"}],"explanation":["모르냐고 묻는 말은 사람을 겨눠요.","깎아내리는 말도 마찬가지예요.","근거의 빈 곳을 짚어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#5','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C15',1,'ox','auto','판정은 어느 쪽이 더 큰 목소리로 말했는지로 정해요.',ARRAY['K6-1-u3-X16']::text[],false,'{"seq":5,"concept":"K6-1-u3-C15","difficulty":1,"kind":"ox","stem":"판정은 어느 쪽이 더 큰 목소리로 말했는지로 정해요.","answer":"X","reason_options":[{"t":"미리 밝힌 기준으로 어느 쪽이 더 설득력 있었는지 정하기 때문에","correct":true},{"t":"목소리가 크면 자신감이 있다는 뜻이기 때문에","mis":"K6-1-u3-X16"}],"mis":"K6-1-u3-X16","explanation":["목소리 크기는 기준이 아니에요.","기준을 먼저 밝혀요.","더 설득력 있게 말한 쪽을 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#6','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C23',1,'mc','auto','양측 발언을 메모하며 듣고, 끝나면 잘한 곳을 짚어 주는 역할은 무엇인가요?',ARRAY['K6-1-u3-X25']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"mc","stem":"양측 발언을 메모하며 듣고, 끝나면 잘한 곳을 짚어 주는 역할은 무엇인가요?","options":[{"t":"청중","correct":true},{"t":"사회자","mis":"K6-1-u3-X25"},{"t":"판정단","mis":"K6-1-u3-X25"},{"t":"토론자","mis":"K6-1-u3-X25"}],"explanation":["사회자는 이끌어요.","판정단은 정해요.","듣고 짚어 주는 사람은 청중이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#7','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C26',1,'ox','auto','근거는 이유와 이어지는지, 출처가 분명한지, 구체적인지 따져 봐요.',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":7,"concept":"K6-1-u3-C26","difficulty":1,"kind":"ox","stem":"근거는 이유와 이어지는지, 출처가 분명한지, 구체적인지 따져 봐요.","answer":"O","reason_options":[{"t":"세 물음 가운데 하나만 걸려도 근거가 흔들리기 때문에","correct":true},{"t":"숫자만 들어 있으면 따질 필요가 없기 때문에","mis":"K6-1-u3-X35"}],"mis":"K6-1-u3-X35","explanation":["세 물음을 한 번씩 던져요.","숫자만 보고 넘어가지 않아요.","전체적으로 타당한지 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#8','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C43',1,'mc','auto','「젊다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「젊다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[점따]","correct":true},{"t":"[절따]","mis":"K6-1-u3-X44"},{"t":"[젊다]","mis":"K6-1-u3-X44"},{"t":"[저따]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 ㄷ이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#9','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C10',2,'mc','auto','서아가 든 근거의 문제로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X30','K6-1-u3-X17']::text[],false,'{"seq":9,"concept":"K6-1-u3-C10","difficulty":2,"kind":"mc","stem":"서아가 든 근거의 문제로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"어느 누리집인지 밝히지 않아 확인할 수 없다","correct":true},{"t":"이유가 하나도 없다","mis":"K6-1-u3-X05"},{"t":"너무 구체적이다","mis":"K6-1-u3-X30"},{"t":"높임말을 썼다","mis":"K6-1-u3-X17"}],"explanation":["서아도 이유는 말했어요.","구체적인 것은 문제가 아니에요.","출처를 밝히지 않았어요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#10','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C12',2,'mc','auto','도담이의 답변이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":10,"concept":"K6-1-u3-C12","difficulty":2,"kind":"mc","stem":"도담이의 답변이 알맞은 까닭은 무엇인가요?","options":[{"t":"「다들 운동장에 나간다」는 말이 설문 자료와 맞지 않음을 밝혔기 때문에","correct":true},{"t":"같은 말을 되풀이했기 때문에","mis":"K6-1-u3-X13"},{"t":"서아의 말투를 문제 삼았기 때문에","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼냈기 때문에","mis":"K6-1-u3-X11"}],"explanation":["되풀이하지 않았어요.","말투를 겨누지 않았어요.","자료로 반론이 타당하지 않음을 밝혔어요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#11','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C14',2,'mc','auto','도담이의 주장 다지기가 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"도담이의 주장 다지기가 알맞은 까닭은 무엇인가요?","options":[{"t":"반론에서도 흔들리지 않은 설문을 추려 짧게 다시 세웠기 때문에","correct":true},{"t":"처음 한 말을 그대로 되풀이했기 때문에","mis":"K6-1-u3-X15"},{"t":"상대 말투를 짚었기 때문에","mis":"K6-1-u3-X14"},{"t":"새로운 주제를 꺼냈기 때문에","mis":"K6-1-u3-X11"}],"explanation":["되풀이가 아니에요.","말투를 겨누지 않았어요.","남은 것을 추려 다시 세웠어요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#12','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C15',2,'mc','auto','나래의 판정이 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":12,"concept":"K6-1-u3-C15","difficulty":2,"kind":"mc","stem":"나래의 판정이 알맞은 까닭은 무엇인가요?","options":[{"t":"미리 정한 기준을 밝히고 그 기준으로 정했으며 잘한 곳도 짚었기 때문에","correct":true},{"t":"찬성 측이 옳다고 가려 주었기 때문에","mis":"K6-1-u3-X17"},{"t":"평소 자기 생각을 말했기 때문에","mis":"K6-1-u3-X24"},{"t":"목소리가 큰 쪽을 골랐기 때문에","mis":"K6-1-u3-X16"}],"explanation":["옳고 그름을 가린 것이 아니에요.","평소 생각을 넣지 않았어요.","기준을 밝히고 정했어요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#13','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C27',2,'mc','auto','은솔이의 메모로 반대 측 근거를 겨누는 반론을 만든다면 무엇을 짚어야 하나요?',ARRAY['K6-1-u3-X14','K6-1-u3-X30','K6-1-u3-X17']::text[],false,'{"seq":13,"concept":"K6-1-u3-C27","difficulty":2,"kind":"mc","stem":"은솔이의 메모로 반대 측 근거를 겨누는 반론을 만든다면 무엇을 짚어야 하나요?","options":[{"t":"어느 누리집인지 밝히지 않아 확인할 수 없다는 점","correct":true},{"t":"반대 측 목소리가 컸다는 점","mis":"K6-1-u3-X14"},{"t":"반대 측 근거가 너무 구체적이라는 점","mis":"K6-1-u3-X30"},{"t":"반대 측이 높임말을 썼다는 점","mis":"K6-1-u3-X17"}],"explanation":["목소리는 사람을 겨눠요.","구체적인 것은 문제가 아니에요.","출처가 확인되지 않는 점을 짚어요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#14','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C21',2,'mc','auto','설문 조사로 근거를 마련하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X29','K6-1-u3-X33']::text[],false,'{"seq":14,"concept":"K6-1-u3-C21","difficulty":2,"kind":"mc","stem":"설문 조사로 근거를 마련하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"우리 반이나 학년에 직접 물어 수를 세고, 언제 몇 명에게 물었는지 적는다","correct":true},{"t":"친구 한두 명에게만 물어 모두의 생각이라고 쓴다","mis":"K6-1-u3-X29"},{"t":"물은 때와 사람 수는 적지 않는다","mis":"K6-1-u3-X29"},{"t":"내 생각과 같은 답만 골라 센다","mis":"K6-1-u3-X33"}],"explanation":["한두 명은 모두가 아니에요.","때와 사람 수를 적어요.","치우치지 않게 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#15','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C32',2,'mc','auto','사회 문제 토론에서 「알려진 사실부터 함께 맞춰 본다」고 하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X16','K6-1-u3-X36']::text[],false,'{"seq":15,"concept":"K6-1-u3-C32","difficulty":2,"kind":"mc","stem":"사회 문제 토론에서 「알려진 사실부터 함께 맞춰 본다」고 하는 까닭은 무엇인가요?","options":[{"t":"아는 것이 적으면 토론이 겉돌기 쉽기 때문에","correct":true},{"t":"사실을 맞추면 토론할 필요가 없어지기 때문에","mis":"K6-1-u3-X01"},{"t":"판정 결과를 미리 정하기 위해서","mis":"K6-1-u3-X16"},{"t":"사실은 토론에 필요 없기 때문에","mis":"K6-1-u3-X36"}],"explanation":["사실을 맞춰도 생각은 갈려요.","판정은 토론 뒤에 해요.","사실을 알아야 겉돌지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#16','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C30',2,'mc','auto','근거 자료로 가장 믿을 만한 것은 어느 것인가요?',ARRAY['K6-1-u3-X33','K6-1-u3-X27']::text[],false,'{"seq":16,"concept":"K6-1-u3-C30","difficulty":2,"kind":"mc","stem":"근거 자료로 가장 믿을 만한 것은 어느 것인가요?","options":[{"t":"우리 시가 올해 낸, 주제와 직접 이어지는 조사 자료","correct":true},{"t":"물건을 팔려는 회사가 쓴 광고 글","mis":"K6-1-u3-X33"},{"t":"아주 오래전에 나온 자료","mis":"K6-1-u3-X33"},{"t":"주제와 비슷해 보이는 다른 나라 이야기","mis":"K6-1-u3-X27"}],"explanation":["광고 글은 치우쳐요.","오래된 자료는 지금과 다를 수 있어요.","공신력 · 최근 · 직접 이어짐을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#17','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C5',3,'error','auto','토론의 단계를 설명했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X05','K6-1-u3-X16']::text[],false,'{"seq":17,"concept":"K6-1-u3-C5","difficulty":3,"kind":"error","stem":"토론의 단계를 설명했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"도겸 — 「주장 다지기에서는 상대 근거의 허점을 처음으로 짚어.」","correct":true,"mis_target":"K6-1-u3-X06"},{"t":"하윤 — 「주장 펼치기에서는 주장 · 이유 · 근거를 함께 내.」","mis":"K6-1-u3-X05"},{"t":"지안 — 「판정하기에서는 판정단이 기준을 밝혀.」","mis":"K6-1-u3-X16"}],"explanation":["하윤은 펼치기를 바르게 말했어요.","지안은 판정하기를 바르게 말했어요.","허점을 짚는 것은 반론하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#18','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C26',3,'mc','auto','사물함 토론에서 온유의 근거가 타당한 까닭을 바르게 말한 것은 어느 것인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X31','K6-1-u3-X17']::text[],false,'{"seq":18,"concept":"K6-1-u3-C26","difficulty":3,"kind":"mc","stem":"사물함 토론에서 온유의 근거가 타당한 까닭을 바르게 말한 것은 어느 것인가요?","options":[{"t":"물건을 잃는 일이 있다는 이유와 이어지고, 지난달 · 백쉰 명이라는 조사가 밝혀져 있다","correct":true},{"t":"숫자가 크니 따져 볼 필요가 없다","mis":"K6-1-u3-X35"},{"t":"설문은 근거가 될 수 없다","mis":"K6-1-u3-X31"},{"t":"찬성 측이니 맞다","mis":"K6-1-u3-X17"}],"explanation":["숫자만 보지 않아요.","설문도 근거가 돼요.","이유와 이어지고 구체적이에요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#19','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C13',3,'mc','auto','반론할 때 높임말을 쓰고 공격적인 말투를 피하는 까닭은 무엇인가요?',ARRAY['K6-1-u3-X09','K6-1-u3-X16','K6-1-u3-X14']::text[],false,'{"seq":19,"concept":"K6-1-u3-C13","difficulty":3,"kind":"mc","stem":"반론할 때 높임말을 쓰고 공격적인 말투를 피하는 까닭은 무엇인가요?","options":[{"t":"토론은 공식적인 말하기이고, 말투가 거칠어지면 근거가 아니라 사람을 겨누게 되기 때문에","correct":true},{"t":"높임말을 쓰면 무조건 이기기 때문에","mis":"K6-1-u3-X09"},{"t":"판정단이 말투만 보기 때문에","mis":"K6-1-u3-X16"},{"t":"높임말을 쓰면 상대에게 지는 것이기 때문에","mis":"K6-1-u3-X14"}],"explanation":["이기려고 쓰는 것이 아니에요.","판정단은 기준을 봐요.","공식적인 말하기라 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#20','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C41',3,'mc','auto','은솔이의 말이 토론 뒤 나눌 이야기로 알맞은 까닭은 무엇인가요?',ARRAY['K6-1-u3-X40','K6-1-u3-X18']::text[],false,'{"seq":20,"concept":"K6-1-u3-C41","difficulty":3,"kind":"mc","stem":"은솔이의 말이 토론 뒤 나눌 이야기로 알맞은 까닭은 무엇인가요?","options":[{"t":"새롭게 안 사실과 다른 역할을 맡은 친구의 잘한 점을 말했기 때문에","correct":true},{"t":"승패를 분명히 말했기 때문에","mis":"K6-1-u3-X40"},{"t":"판정 결과를 바꾸자고 했기 때문에","mis":"K6-1-u3-X18"},{"t":"상대의 준비 부족을 짚었기 때문에","mis":"K6-1-u3-X40"}],"explanation":["은솔이는 승패를 말하지 않았어요.","판정을 바꾸자고 하지 않았어요.","새로 안 것과 잘한 친구를 말했어요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#21','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C38',3,'mc','auto','모둠이 모은 근거 가운데 준비표에 옮길 것을 고르는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X43','K6-1-u3-X30','K6-1-u3-X22']::text[],false,'{"seq":21,"concept":"K6-1-u3-C38","difficulty":3,"kind":"mc","stem":"모둠이 모은 근거 가운데 준비표에 옮길 것을 고르는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"같은 편끼리 바꾸어 읽고 세 물음을 던져 가장 센 두 가지만 고른다","correct":true},{"t":"모은 것을 하나도 빼지 않고 모두 옮긴다","mis":"K6-1-u3-X43"},{"t":"가장 긴 자료부터 옮긴다","mis":"K6-1-u3-X30"},{"t":"출처를 지우고 내용만 옮긴다","mis":"K6-1-u3-X22"}],"explanation":["약한 것까지 옮기면 흔들려요.","길이로 고르지 않아요.","세 물음으로 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#22','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C43',3,'mc','auto','「묽고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「묽고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[물꼬]","correct":true},{"t":"[묵꼬]","mis":"K6-1-u3-X44"},{"t":"[물고]","mis":"K6-1-u3-X44"},{"t":"[묽고]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄱ이 왔어요.","이때는 [ㄹ]로 소리 나요.","뒤의 ㄱ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#23','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C16',4,'mc','auto','두 판정단의 판정을 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X17','K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":23,"concept":"K6-1-u3-C16","difficulty":4,"kind":"mc","stem":"두 판정단의 판정을 견주어 평가한 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나래는 기준을 밝히고 토론에 나온 내용으로 정해 알맞고, 지우는 기준 없이 평소 생각으로 정해 알맞지 않다","correct":true},{"t":"두 사람 모두 찬성 측을 골랐으니 똑같이 알맞다","mis":"K6-1-u3-X17"},{"t":"지우가 솔직하게 자기 생각을 말해 더 알맞다","mis":"K6-1-u3-X24"},{"t":"판정은 누가 해도 결과가 같으니 따질 필요가 없다","mis":"K6-1-u3-X16"}],"explanation":["고른 편이 같아도 방법이 달라요.","평소 생각을 넣으면 안 돼요.","기준을 밝혔는지 봐요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#24','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C33',4,'essay','teacher','지우와 나래의 판정을 견주어 어느 판정이 알맞은지 까닭과 함께 쓰고, 판정단이 지켜야 할 점을 두 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C33","difficulty":4,"kind":"essay","stem":"지우와 나래의 판정을 견주어 어느 판정이 알맞은지 까닭과 함께 쓰고, 판정단이 지켜야 할 점을 두 가지 쓰세요.","answer_guide":{"answer":"예: 나래의 판정이 알맞다. 나래는 근거가 믿을 만한가와 반론에 알맞게 답했는가라는 기준을 먼저 밝히고, 그 기준으로 찬성 측이 더 설득력 있었다고 정했으며 반대 측이 잘한 곳도 짚었다. 지우는 기준 없이 원래 자기 생각과 같은 편을 골랐다. 판정단은 첫째, 판정 기준을 미리 정해 밝혀야 하고, 둘째, 자기 생각과 같은 편에 후하게 주지 않고 토론에서 나온 말과 자료만으로 판정해야 한다.","scoring_points":["알맞은 판정을 고르고 까닭을 썼는가","알맞지 않은 판정의 문제를 썼는가","판정단이 지킬 점 두 가지를 썼는가"]},"explanation":["두 판정을 견줘요.","기준을 밝혔는지 봐요.","공정함을 떠올려요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_b#25','kor',6,1,'u3','','g6_1_kor_u3_review_b','unit_review','K6-1-u3-C7',4,'essay','teacher','「토론은 겨루는 방식이지만 목적은 이기는 것이 아니다」라는 말을 설명하고, 이 단원에서 배운 태도 두 가지와 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C7","difficulty":4,"kind":"essay","stem":"「토론은 겨루는 방식이지만 목적은 이기는 것이 아니다」라는 말을 설명하고, 이 단원에서 배운 태도 두 가지와 이어 쓰세요.","answer_guide":{"answer":"예: 토론은 찬성과 반대로 나뉘어 겨루는 말하기이지만, 그렇게 겨루는 까닭은 더 합리적인 결정에 이르기 위해서이다. 그래서 상대를 누르려고 사람을 겨누지 않고 근거를 겨누어 반론해야 한다. 또 판정 결과에 승복하고, 토론 뒤에 생각이 바뀌는 것을 부끄러워하지 않으며 새로 알게 된 것을 나눈다.","scoring_points":["겨루는 방식과 목적을 구별해 설명했는가","근거를 겨누는 태도를 썼는가","승복하거나 생각을 나누는 태도를 썼는가"]},"explanation":["방식과 목적을 갈라요.","반론하는 태도를 떠올려요.","판정 뒤의 태도를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#1','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C2',1,'mc','auto','「우리 반 학급 문고에 어떤 책을 들일지 의견 모으기」는 토의와 토론 가운데 무엇인가요?',ARRAY['K6-1-u3-X02','K6-1-u3-X06']::text[],false,'{"seq":1,"concept":"K6-1-u3-C2","difficulty":1,"kind":"mc","stem":"「우리 반 학급 문고에 어떤 책을 들일지 의견 모으기」는 토의와 토론 가운데 무엇인가요?","options":[{"t":"토의","correct":true},{"t":"토론","mis":"K6-1-u3-X02"},{"t":"판정","mis":"K6-1-u3-X06"},{"t":"반론","mis":"K6-1-u3-X06"}],"explanation":["편이 갈리지 않아요.","판정 · 반론은 토론의 단계예요.","함께 방법을 모으니 토의예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#2','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C4',1,'ox','auto','이유는 밖에서 가져온 자료이고, 근거는 내 머릿속에서 나온 까닭이에요.',ARRAY['K6-1-u3-X04']::text[],false,'{"seq":2,"concept":"K6-1-u3-C4","difficulty":1,"kind":"ox","stem":"이유는 밖에서 가져온 자료이고, 근거는 내 머릿속에서 나온 까닭이에요.","answer":"X","reason_options":[{"t":"이유는 내가 생각한 까닭이고 근거는 밖에서 가져와 확인할 수 있는 자료이기 때문에","correct":true},{"t":"이유와 근거는 같은 말이기 때문에","mis":"K6-1-u3-X04"}],"mis":"K6-1-u3-X04","explanation":["두 말이 뒤바뀌었어요.","이유는 내 까닭이에요.","근거는 밖의 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#3','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',1,'mc','auto','자기편 주장을 정리해 다시 힘주어 말하는 단계는 무엇인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C14","difficulty":1,"kind":"mc","stem":"자기편 주장을 정리해 다시 힘주어 말하는 단계는 무엇인가요?","options":[{"t":"주장 다지기","correct":true},{"t":"주장 펼치기","mis":"K6-1-u3-X06"},{"t":"반론하기","mis":"K6-1-u3-X06"},{"t":"판정하기","mis":"K6-1-u3-X06"}],"explanation":["펼치기는 처음 내놓는 단계예요.","반론은 되받는 단계예요.","다시 세우는 단계는 주장 다지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#4','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',1,'mc','auto','상대의 주장에 맞서서 반대되는 자기 주장을 밝히는 말하기를 무엇이라고 하나요?',ARRAY['K6-1-u3-X06','K6-1-u3-X02']::text[],false,'{"seq":4,"concept":"K6-1-u3-C11","difficulty":1,"kind":"mc","stem":"상대의 주장에 맞서서 반대되는 자기 주장을 밝히는 말하기를 무엇이라고 하나요?","options":[{"t":"반론","correct":true},{"t":"판정","mis":"K6-1-u3-X06"},{"t":"주장 다지기","mis":"K6-1-u3-X06"},{"t":"토의","mis":"K6-1-u3-X02"}],"explanation":["판정은 판정단이 해요.","다지기는 자기편을 다시 세워요.","맞서서 되받는 것이 반론이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#5','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C16',1,'ox','auto','토론자는 판정 결과에 승복하는 태도를 지녀요.',ARRAY['K6-1-u3-X18']::text[],false,'{"seq":5,"concept":"K6-1-u3-C16","difficulty":1,"kind":"ox","stem":"토론자는 판정 결과에 승복하는 태도를 지녀요.","answer":"O","reason_options":[{"t":"판정은 정한 기준으로 공정하게 낸 결과이기 때문에","correct":true},{"t":"판정은 늘 틀리기 때문에","mis":"K6-1-u3-X18"}],"mis":"K6-1-u3-X18","explanation":["판정은 기준으로 정해요.","결과가 마음에 안 들 수 있어요.","그래도 승복해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#6','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C23',1,'ox','auto','청중은 토론에서 할 일이 없어요.',ARRAY['K6-1-u3-X37']::text[],false,'{"seq":6,"concept":"K6-1-u3-C23","difficulty":1,"kind":"ox","stem":"청중은 토론에서 할 일이 없어요.","answer":"X","reason_options":[{"t":"메모하며 듣고 인상 깊은 근거를 말하는 할 일이 있기 때문에","correct":true},{"t":"토론자만 말하기 때문에","mis":"K6-1-u3-X37"}],"mis":"K6-1-u3-X37","explanation":["청중이 가장 많아요.","청중에게도 할 일이 있어요.","메모하고 짚어 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#7','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C28',1,'ox','auto','자료 하나라도 언제 · 누구를 · 어떻게 조사했는지 자세하면 충분할 수 있어요.',ARRAY['K6-1-u3-X30']::text[],false,'{"seq":7,"concept":"K6-1-u3-C28","difficulty":1,"kind":"ox","stem":"자료 하나라도 언제 · 누구를 · 어떻게 조사했는지 자세하면 충분할 수 있어요.","answer":"O","reason_options":[{"t":"충분성은 자료의 개수가 아니라 구체적인 정도이기 때문에","correct":true},{"t":"자료는 개수가 많아야만 충분하기 때문에","mis":"K6-1-u3-X30"}],"mis":"K6-1-u3-X30","explanation":["개수가 많다고 충분한 것이 아니에요.","자세한지가 중요해요.","하나라도 자세하면 충분할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#8','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C43',1,'mc','auto','「닮다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「닮다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[담따]","correct":true},{"t":"[달따]","mis":"K6-1-u3-X44"},{"t":"[닮다]","mis":"K6-1-u3-X44"},{"t":"[다따]","mis":"K6-1-u3-X44"}],"explanation":["ㄻ 뒤에 ㄷ이 왔어요.","ㄻ은 [ㅁ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#9','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C9',2,'mc','auto','서아의 주장 펼치기에서 이유에 해당하는 것은 어느 것인가요?',ARRAY['K6-1-u3-X05','K6-1-u3-X04']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"mc","stem":"서아의 주장 펼치기에서 이유에 해당하는 것은 어느 것인가요?","options":[{"t":"도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문","correct":true},{"t":"점심시간에는 도서실을 닫아야 한다","mis":"K6-1-u3-X05"},{"t":"어떤 누리집에서 봤는데 다른 학교도 다 닫는다","mis":"K6-1-u3-X04"},{"t":"도서부가 고학년 이백 명에게 물은 설문","mis":"K6-1-u3-X04"}],"explanation":["닫아야 한다는 것은 주장이에요.","누리집 이야기는 근거로 든 것이에요.","그렇게 주장하는 까닭이 이유예요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#10','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',2,'mc','auto','서아의 마지막 말 「저는 요즘 급식 줄이 더 문제라고 봅니다.」의 문제는 무엇인가요?',ARRAY['K6-1-u3-X30','K6-1-u3-X17','K6-1-u3-X13']::text[],false,'{"seq":10,"concept":"K6-1-u3-C11","difficulty":2,"kind":"mc","stem":"서아의 마지막 말 「저는 요즘 급식 줄이 더 문제라고 봅니다.」의 문제는 무엇인가요?","options":[{"t":"주장 펼치기에서 나온 내용과 상관없는 새 이야기를 꺼냈다","correct":true},{"t":"근거를 너무 자세히 밝혔다","mis":"K6-1-u3-X30"},{"t":"높임말을 썼다","mis":"K6-1-u3-X17"},{"t":"상대 근거를 겨누었다","mis":"K6-1-u3-X13"}],"explanation":["근거를 밝히지도 않았어요.","높임말은 맞아요.","주제와 상관없는 말이에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#11','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',2,'ox','auto','주장 다지기에서는 무너진 근거도 다시 꺼내 힘주어 말해야 해요.',ARRAY['K6-1-u3-X15']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"ox","stem":"주장 다지기에서는 무너진 근거도 다시 꺼내 힘주어 말해야 해요.","answer":"X","reason_options":[{"t":"반론에서 확인된 것만 골라야 하고 무너진 근거를 꺼내면 오히려 약해지기 때문에","correct":true},{"t":"한 번 낸 근거는 끝까지 지켜야 하기 때문에","mis":"K6-1-u3-X15"}],"mis":"K6-1-u3-X15","explanation":["무너진 근거는 힘이 없어요.","확인된 것만 골라요.","추려서 다시 세워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#12','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C16',2,'ox','auto','나래의 판정은 도서실을 열자는 생각이 옳다는 뜻이에요.',ARRAY['K6-1-u3-X17']::text[],false,'{"seq":12,"concept":"K6-1-u3-C16","difficulty":2,"kind":"ox","stem":"나래의 판정은 도서실을 열자는 생각이 옳다는 뜻이에요.","answer":"X","reason_options":[{"t":"정한 기준으로 보아 찬성 측이 더 설득력 있게 말했다는 뜻이기 때문에","correct":true},{"t":"판정은 옳은 생각을 가려 주는 일이기 때문에","mis":"K6-1-u3-X17"}],"mis":"K6-1-u3-X17","explanation":["판정은 옳고 그름을 가리지 않아요.","기준으로 본 설득력이에요.","두 생각은 그대로 남아요."],"asset":{"type":"speech","turns":[{"who":"판정단 지우","text":"저는 원래 도서실을 열자는 생각이어서 찬성 측이 이겼다고 봅니다."},{"who":"판정단 나래","text":"저는 미리 정한 기준, 곧 근거가 믿을 만한가와 반론에 알맞게 답했는가로 보았습니다. 이 기준으로 찬성 측이 더 설득력 있었다고 판정합니다. 반대 측이 지키는 분의 쉬는 시간을 짚은 점은 좋았습니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#13','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C34',2,'ox','auto','은솔이처럼 발언을 그대로 옮기지 않고 핵심만 짧게 적는 것이 좋아요.',ARRAY['K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"ox","stem":"은솔이처럼 발언을 그대로 옮기지 않고 핵심만 짧게 적는 것이 좋아요.","answer":"O","reason_options":[{"t":"다음 말을 놓치지 않고 되받을 거리를 남길 수 있기 때문에","correct":true},{"t":"상대 말은 들을 필요가 없기 때문에","mis":"K6-1-u3-X08"}],"mis":"K6-1-u3-X08","explanation":["다 옮기면 다음 말을 놓쳐요.","상대 말은 잘 들어야 해요.","핵심만 짧게 적어요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#14','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C20',2,'mc','auto','토론 준비표에 쓸 차례로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X06','K6-1-u3-X21']::text[],false,'{"seq":14,"concept":"K6-1-u3-C20","difficulty":2,"kind":"mc","stem":"토론 준비표에 쓸 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"주장 → 이유 → 이유마다 근거 → 예상 반론과 답변","correct":true},{"t":"근거 → 판정 → 주장","mis":"K6-1-u3-X06"},{"t":"예상 반론 → 주장 → 판정","mis":"K6-1-u3-X06"},{"t":"주장 → 이유 하나 → 끝","mis":"K6-1-u3-X21"}],"explanation":["판정은 준비표에 쓰지 않아요.","이유는 두세 가지, 근거와 반론까지 준비해요.","주장 아래 이유, 이유 아래 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#15','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C37',2,'mc','auto','실천 토론에서 주제를 찾을 수 있는 갈래로 알맞게 짝 지은 것은 어느 것인가요?',ARRAY['K6-1-u3-X01','K6-1-u3-X06','K6-1-u3-X25']::text[],false,'{"seq":15,"concept":"K6-1-u3-C37","difficulty":2,"kind":"mc","stem":"실천 토론에서 주제를 찾을 수 있는 갈래로 알맞게 짝 지은 것은 어느 것인가요?","options":[{"t":"역사 · 환경 · 생활","correct":true},{"t":"연도 · 이름 · 길이","mis":"K6-1-u3-X01"},{"t":"판정 · 반론 · 다지기","mis":"K6-1-u3-X06"},{"t":"사회자 · 청중 · 판정단","mis":"K6-1-u3-X25"}],"explanation":["연도나 이름은 답이 하나예요.","그것은 토론의 단계예요.","역사 · 환경 · 생활에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#16','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C39',2,'mc','auto','원탁 토론과 찬반 토론의 같은 점은 무엇인가요?',ARRAY['K6-1-u3-X41']::text[],false,'{"seq":16,"concept":"K6-1-u3-C39","difficulty":2,"kind":"mc","stem":"원탁 토론과 찬반 토론의 같은 점은 무엇인가요?","options":[{"t":"두 토론 모두 근거를 들어 말한다","correct":true},{"t":"두 토론 모두 판정단이 승패를 정한다","mis":"K6-1-u3-X41"},{"t":"두 토론 모두 편을 나눈다","mis":"K6-1-u3-X41"},{"t":"두 토론 모두 사회자가 반드시 있다","mis":"K6-1-u3-X41"}],"explanation":["원탁 토론은 판정단을 두지 않아요.","원탁 토론은 편을 나누지 않아요.","근거를 들어 말하는 점은 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#17','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C24',3,'mc','auto','같은 편끼리 반론과 답변을 맞춰 두려고 단계 사이에 두는 시간을 무엇이라고 하나요?',ARRAY['K6-1-u3-X06','K6-1-u3-X23']::text[],false,'{"seq":17,"concept":"K6-1-u3-C24","difficulty":3,"kind":"mc","stem":"같은 편끼리 반론과 답변을 맞춰 두려고 단계 사이에 두는 시간을 무엇이라고 하나요?","options":[{"t":"협의 시간","correct":true},{"t":"판정 시간","mis":"K6-1-u3-X06"},{"t":"반론 시간","mis":"K6-1-u3-X06"},{"t":"쉬는 시간","mis":"K6-1-u3-X23"}],"explanation":["판정은 끝에 해요.","반론은 단계 이름이에요.","같은 편끼리 맞추는 시간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#18','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C26',3,'error','auto','사물함 토론의 두 근거를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X35','K6-1-u3-X30','K6-1-u3-X29']::text[],false,'{"seq":18,"concept":"K6-1-u3-C26","difficulty":3,"kind":"error","stem":"사물함 토론의 두 근거를 견주었어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"보미 — 「두 근거 모두 사람에게 물었으니 똑같이 타당해.」","correct":true,"mis_target":"K6-1-u3-X35"},{"t":"지호 — 「백쉰 명과 두 명은 같은 무게가 아니야.」","mis":"K6-1-u3-X30"},{"t":"은재 — 「새얀이는 언제 물었는지도 밝히지 않았어.」","mis":"K6-1-u3-X29"}],"explanation":["지호는 사람 수를 바르게 견주었어요.","은재는 때를 바르게 짚었어요.","물은 방법이 같아도 구체성이 달라요."],"asset":{"type":"passage","lines":["토론 주제 — 우리 반 사물함에 자물쇠를 달아야 한다.","찬성 측 온유 — 물건을 잃어버리는 일이 실제로 있기 때문입니다.","우리 학교 고학년 백쉰 명에게 지난달에 물어보니,","마흔여덟 명이 사물함에서 물건을 잃은 적이 있다고 답했습니다.","반대 측 새얀 — 열고 닫기가 번거롭기 때문입니다.","제 친구 두 명에게 물어보니 둘 다 불편할 것 같다고 했습니다."],"title":"두 근거 견주기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#19','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C11',3,'mc','auto','반론할 때 되받을 수 있는 범위로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X11','K6-1-u3-X14']::text[],false,'{"seq":19,"concept":"K6-1-u3-C11","difficulty":3,"kind":"mc","stem":"반론할 때 되받을 수 있는 범위로 알맞은 것은 어느 것인가요?","options":[{"t":"상대가 주장 펼치기에서 낸 주장 · 이유 · 근거","correct":true},{"t":"토론과 상관없는 요즘 일","mis":"K6-1-u3-X11"},{"t":"상대의 말투와 표정","mis":"K6-1-u3-X14"},{"t":"상대가 지난번 다른 토론에서 한 말","mis":"K6-1-u3-X11"}],"explanation":["상관없는 일은 꺼내지 않아요.","말투는 겨누지 않아요.","펼친 내용에 대해서만 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#20','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C33',3,'error','auto','판정단의 마음가짐을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X16']::text[],false,'{"seq":20,"concept":"K6-1-u3-C33","difficulty":3,"kind":"error","stem":"판정단의 마음가짐을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"지우 — 「나는 원래 찬성이니까 찬성 측에 점수를 더 줄 거야.」","correct":true,"mis_target":"K6-1-u3-X24"},{"t":"나래 — 「미리 정한 기준을 적어 두고 판정할게.」","mis":"K6-1-u3-X16"},{"t":"하람 — 「토론에서 나온 말과 자료만 볼게.」","mis":"K6-1-u3-X24"}],"explanation":["나래는 기준을 먼저 정했어요.","하람은 나온 내용만 봐요.","지우는 같은 편에 후하게 주려 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#21','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C39',3,'mc','auto','「우리 마을 하천을 어떻게 가꿀까」처럼 여러 생각을 모아야 하는 문제를 이야기할 때 알맞은 토론은 어느 것인가요?',ARRAY['K6-1-u3-X41','K6-1-u3-X03']::text[],false,'{"seq":21,"concept":"K6-1-u3-C39","difficulty":3,"kind":"mc","stem":"「우리 마을 하천을 어떻게 가꿀까」처럼 여러 생각을 모아야 하는 문제를 이야기할 때 알맞은 토론은 어느 것인가요?","options":[{"t":"모두가 대등하게 돌아가며 말하는 원탁 토론","correct":true},{"t":"찬성과 반대로 나뉘는 찬반 토론","mis":"K6-1-u3-X41"},{"t":"판정단이 승패를 정하는 토론","mis":"K6-1-u3-X41"},{"t":"한 사람만 말하는 연설","mis":"K6-1-u3-X03"}],"explanation":["둘로 갈리지 않는 문제예요.","승패를 정할 문제가 아니에요.","모두가 대등하게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#22','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C43',3,'error','auto','세 친구가 겹받침이 든 말을 읽었어요. 바르지 않게 읽은 친구는 누구인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"error","stem":"세 친구가 겹받침이 든 말을 읽었어요. 바르지 않게 읽은 친구는 누구인가요?","options":[{"t":"이안 — 「붉게」를 [북께]로 읽었다","correct":true,"mis_target":"K6-1-u3-X44"},{"t":"서아 — 「늙지」를 [늑찌]로 읽었다","mis":"K6-1-u3-X44"},{"t":"도담 — 「닮고」를 [담꼬]로 읽었다","mis":"K6-1-u3-X44"}],"explanation":["서아는 ㄺ을 [ㄱ]으로 읽었어요.","도담은 ㄻ을 [ㅁ]으로 읽었어요.","ㄺ 뒤에 ㄱ이 오면 [ㄹ] — [불께]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#23','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C14',4,'mc','auto','서아의 주장 다지기를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X14','K6-1-u3-X11']::text[],false,'{"seq":23,"concept":"K6-1-u3-C14","difficulty":4,"kind":"mc","stem":"서아의 주장 다지기를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「요컨대 저희가 지키려는 것은 지키는 분의 쉬는 시간입니다. 그 시간을 지킬 방법이 없다면 점심시간에는 닫아야 합니다.」","correct":true},{"t":"「다른 학교도 다 닫으니 우리도 닫아야 합니다.」를 두 번 말한다","mis":"K6-1-u3-X15"},{"t":"「찬성 측은 준비가 부족했습니다.」라고 말한다","mis":"K6-1-u3-X14"},{"t":"「그런데 급식 줄도 문제입니다.」를 덧붙인다","mis":"K6-1-u3-X11"}],"explanation":["무너진 근거를 되풀이하지 않아요.","상대를 깎아내리지 않아요.","남은 이유로 다시 세워요."],"asset":{"type":"speech","turns":[{"who":"찬성 측 도담","text":"요컨대 책을 읽고 싶은 학생이 많습니다. 백삼십 명이라는 설문은 반론에서도 흔들리지 않았습니다. 따라서 점심시간에도 도서실을 열어야 합니다."},{"who":"반대 측 서아","text":"처음에 말씀드린 대로 다른 학교도 다 닫는다는 점을 다시 말씀드립니다. 다른 학교도 다 닫으니 우리도 닫아야 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#24','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C26',4,'essay','teacher','도담이와 서아가 든 근거를 세 물음으로 따져 보고, 어느 쪽 근거가 더 타당한지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C26","difficulty":4,"kind":"essay","stem":"도담이와 서아가 든 근거를 세 물음으로 따져 보고, 어느 쪽 근거가 더 타당한지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 도담이의 근거는 책을 고를 시간이 모자란다는 이유와 이어지고, 도서부라는 출처가 분명하며, 이번 학기 · 고학년 이백 명이라는 조사 대상이 밝혀져 있다. 서아의 근거는 다른 학교도 다 닫는다는 것인데, 어느 누리집인지 몰라 출처가 분명하지 않고, 지키는 분의 쉬는 시간이라는 이유와도 곧바로 이어지지 않는다. 그래서 도담이의 근거가 더 타당하다.","scoring_points":["도담이의 근거를 세 물음으로 따졌는가","서아의 근거를 세 물음으로 따졌는가","더 타당한 쪽과 까닭을 썼는가"]},"explanation":["이어지는지 따져요.","출처를 따져요.","구체적인지 따져요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_c#25','kor',6,1,'u3','','g6_1_kor_u3_review_c','unit_review','K6-1-u3-C42',4,'essay','teacher','토론자에게 필요한 힘 가운데 내가 잘하는 것과 더 길러야 할 것을 하나씩 골라 까닭과 함께 쓰고, 기르기 위해 할 일을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C42","difficulty":4,"kind":"essay","stem":"토론자에게 필요한 힘 가운데 내가 잘하는 것과 더 길러야 할 것을 하나씩 골라 까닭과 함께 쓰고, 기르기 위해 할 일을 쓰세요.","answer_guide":{"answer":"예: 나는 상대 말을 끝까지 듣고 메모하는 것은 잘해서 상대 근거의 타당성을 따져 보는 힘이 있다. 그러나 반론을 받았을 때 당황해서 같은 말을 되풀이하곤 해서, 반론에 알맞게 답하는 힘을 더 길러야 한다. 그래서 다음 토론에서는 예상 반론을 미리 세 가지 적고 각각에 자료로 답하는 연습을 하겠다.","scoring_points":["잘하는 힘과 까닭을 썼는가","더 길러야 할 힘과 까닭을 썼는가","기르기 위한 구체적인 할 일을 썼는가"]},"explanation":["네 가지 힘을 떠올려요.","내 모습과 견줘요.","할 일을 구체적으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#1','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C1',1,'mc','auto','다음 가운데 찬반이 갈려 토론이 필요한 상황은 어느 것인가요?',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":1,"concept":"K6-1-u3-C1","difficulty":1,"kind":"mc","stem":"다음 가운데 찬반이 갈려 토론이 필요한 상황은 어느 것인가요?","options":[{"t":"공원 한쪽에 반려견 놀이터를 만들지 정하기","correct":true},{"t":"공원이 언제 문을 열었는지 알아보기","mis":"K6-1-u3-X01"},{"t":"공원 넓이를 재어 보기","mis":"K6-1-u3-X01"},{"t":"공원 지도 보는 법 익히기","mis":"K6-1-u3-X01"}],"explanation":["문을 연 때는 찾아보면 알아요.","넓이는 재면 알아요.","찬반이 갈리는 문제에서 토론해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#2','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C10',1,'mc','auto','다음 가운데 근거로 쓸 수 있는 자료는 무엇인가요?',ARRAY['K6-1-u3-X04','K6-1-u3-X05']::text[],false,'{"seq":2,"concept":"K6-1-u3-C10","difficulty":1,"kind":"mc","stem":"다음 가운데 근거로 쓸 수 있는 자료는 무엇인가요?","options":[{"t":"체육 교과 연구회가 낸 안전 지침","correct":true},{"t":"나누어 쓰면 더 재미없을 것 같다","mis":"K6-1-u3-X04"},{"t":"운동장이 좁아서 답답하다고 느낀다","mis":"K6-1-u3-X04"},{"t":"운동장은 나누어 써야 한다","mis":"K6-1-u3-X05"}],"explanation":["「같다」는 짐작이에요.","느낌은 근거가 아니에요.","누가 낸 자료인지 확인돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#3','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C5',1,'ox','auto','반론하기는 주장 펼치기보다 먼저 해요.',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":3,"concept":"K6-1-u3-C5","difficulty":1,"kind":"ox","stem":"반론하기는 주장 펼치기보다 먼저 해요.","answer":"X","reason_options":[{"t":"상대가 주장을 펼친 뒤에야 그 주장을 되받을 수 있기 때문에","correct":true},{"t":"먼저 되받아야 이기기 때문에","mis":"K6-1-u3-X06"}],"mis":"K6-1-u3-X06","explanation":["되받으려면 들을 것이 있어야 해요.","주장 펼치기가 먼저예요.","그다음 반론하기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#4','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C17',1,'mc','auto','토론에서 써야 하는 말은 어느 것인가요?',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":4,"concept":"K6-1-u3-C17","difficulty":1,"kind":"mc","stem":"토론에서 써야 하는 말은 어느 것인가요?","options":[{"t":"높임말","correct":true},{"t":"반말","mis":"K6-1-u3-X14"},{"t":"줄임말","mis":"K6-1-u3-X14"},{"t":"공격적인 말투","mis":"K6-1-u3-X14"}],"explanation":["반말은 공식적인 자리에 맞지 않아요.","줄임말도 맞지 않아요.","토론에서는 높임말을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#5','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C33',1,'mc','auto','판정단이 판정할 때 바탕으로 삼는 것은 무엇인가요?',ARRAY['K6-1-u3-X24','K6-1-u3-X38']::text[],false,'{"seq":5,"concept":"K6-1-u3-C33","difficulty":1,"kind":"mc","stem":"판정단이 판정할 때 바탕으로 삼는 것은 무엇인가요?","options":[{"t":"토론에서 실제로 나온 말과 자료","correct":true},{"t":"평소 자기 생각","mis":"K6-1-u3-X24"},{"t":"토론자의 옷차림","mis":"K6-1-u3-X38"},{"t":"친한 친구가 있는 편","mis":"K6-1-u3-X24"}],"explanation":["평소 생각은 넣지 않아요.","옷차림은 상관없어요.","나온 말과 자료만 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#6','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C19',1,'mc','auto','토론 주제가 정해지면 역할보다 먼저 할 일은 무엇인가요?',ARRAY['K6-1-u3-X20','K6-1-u3-X16']::text[],false,'{"seq":6,"concept":"K6-1-u3-C19","difficulty":1,"kind":"mc","stem":"토론 주제가 정해지면 역할보다 먼저 할 일은 무엇인가요?","options":[{"t":"모두가 자기 생각을 정하기","correct":true},{"t":"판정단 뽑기","mis":"K6-1-u3-X20"},{"t":"사회자 뽑기","mis":"K6-1-u3-X20"},{"t":"판정 결과 정하기","mis":"K6-1-u3-X16"}],"explanation":["판정단은 그다음에 뽑아요.","사회자도 그다음이에요.","자기 생각을 먼저 정해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#7','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C27',1,'mc','auto','다음 가운데 힘을 내지 못하는 근거는 무엇인가요?',ARRAY['K6-1-u3-X35']::text[],false,'{"seq":7,"concept":"K6-1-u3-C27","difficulty":1,"kind":"mc","stem":"다음 가운데 힘을 내지 못하는 근거는 무엇인가요?","options":[{"t":"언제 몇 명에게 물었는지 없는 「많은 사람」","correct":true},{"t":"교육청이 올해 낸 학교 시설 점검 자료","mis":"K6-1-u3-X35"},{"t":"우리 시가 지난해 시민 사백 명에게 물은 조사","mis":"K6-1-u3-X35"},{"t":"학생 회의가 지난 학기에 조사한 보건실 자료","mis":"K6-1-u3-X35"}],"explanation":["교육청 자료는 출처와 때가 있어요.","시의 조사는 대상도 밝혀요.","「많은 사람」은 흐릿해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#8','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C43',1,'mc','auto','「붉다」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":8,"concept":"K6-1-u3-C43","difficulty":1,"kind":"mc","stem":"「붉다」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[북따]","correct":true},{"t":"[불따]","mis":"K6-1-u3-X44"},{"t":"[붉다]","mis":"K6-1-u3-X44"},{"t":"[부따]","mis":"K6-1-u3-X44"}],"explanation":["ㄺ 뒤에 ㄷ이 왔어요.","ㄺ은 [ㄱ]으로 소리 나요.","뒤의 ㄷ은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#9','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C9',2,'ox','auto','도담이의 주장 펼치기에는 주장 · 이유 · 근거가 모두 있어요.',ARRAY['K6-1-u3-X05']::text[],false,'{"seq":9,"concept":"K6-1-u3-C9","difficulty":2,"kind":"ox","stem":"도담이의 주장 펼치기에는 주장 · 이유 · 근거가 모두 있어요.","answer":"O","reason_options":[{"t":"열자는 주장, 책 고를 시간이 모자라다는 이유, 도서부 설문이라는 근거를 냈기 때문에","correct":true},{"t":"주장만 분명하면 되기 때문에","mis":"K6-1-u3-X05"}],"mis":"K6-1-u3-X05","explanation":["주장을 냈어요.","이유를 냈어요.","확인할 수 있는 근거도 냈어요."],"asset":{"type":"speech","turns":[{"who":"사회자 하람","text":"지금부터 「점심시간에도 학교 도서실을 열어야 한다」라는 주제로 토론을 시작하겠습니다. 찬성 측부터 주장을 펼쳐 주십시오."},{"who":"찬성 측 도담","text":"점심시간에도 도서실을 열어야 합니다. 쉬는 시간만으로는 책을 고를 시간이 모자라기 때문입니다. 도서부가 이번 학기에 고학년 이백 명에게 물어보니, 백삼십 명이 점심시간에 책을 빌리고 싶다고 답했습니다."},{"who":"반대 측 서아","text":"점심시간에는 도서실을 닫아야 합니다. 도서실을 지키는 분도 쉬는 시간이 있어야 하기 때문입니다. 어떤 누리집에서 봤는데 다른 학교도 다 닫는다고 합니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#10','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C11',2,'ox','auto','도담이가 누리집의 이름과 쓴 때를 물은 것은 알맞은 반론이에요.',ARRAY['K6-1-u3-X14']::text[],false,'{"seq":10,"concept":"K6-1-u3-C11","difficulty":2,"kind":"ox","stem":"도담이가 누리집의 이름과 쓴 때를 물은 것은 알맞은 반론이에요.","answer":"O","reason_options":[{"t":"근거의 출처가 분명한지를 겨누었기 때문에","correct":true},{"t":"상대를 곤란하게 하려는 말이기 때문에","mis":"K6-1-u3-X14"}],"mis":"K6-1-u3-X14","explanation":["사람을 겨누지 않았어요.","근거를 겨누었어요.","출처를 묻는 것은 알맞은 반론이에요."],"asset":{"type":"speech","turns":[{"who":"반대 측 서아","text":"그것도 모르십니까? 점심시간에는 다들 운동장에 나갑니다."},{"who":"찬성 측 도담","text":"말씀 잘 들었습니다. 다만 저희 설문에서 백삼십 명이 빌리고 싶다고 답했습니다. 다들 운동장에 나간다는 말은 저희 자료와 맞지 않습니다."},{"who":"찬성 측 도담","text":"반대 측께 묻겠습니다. 다른 학교도 다 닫는다는 누리집은 어디이고, 언제 쓴 글입니까?"},{"who":"반대 측 서아","text":"누리집 이름은 적어 두지 못했습니다. 그런데 저는 요즘 급식 줄이 더 문제라고 봅니다."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#11','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C14',2,'mc','auto','주장 다지기를 할 때 알맞은 말하기 방법은 어느 것인가요?',ARRAY['K6-1-u3-X15','K6-1-u3-X07','K6-1-u3-X26']::text[],false,'{"seq":11,"concept":"K6-1-u3-C14","difficulty":2,"kind":"mc","stem":"주장 다지기를 할 때 알맞은 말하기 방법은 어느 것인가요?","options":[{"t":"짧은 문장으로, 「요컨대 · 따라서」를 써서, 또박또박 힘 있게","correct":true},{"t":"길게 늘여서 같은 말을 여러 번","mis":"K6-1-u3-X15"},{"t":"상대 말을 끊고 빠르게","mis":"K6-1-u3-X07"},{"t":"목소리를 높여 한꺼번에 여러 가지를","mis":"K6-1-u3-X26"}],"explanation":["길게 늘이면 중심이 흐려져요.","말차례를 지켜요.","짧고 또박또박 힘 있게 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#12','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C35',2,'mc','auto','판정 기준 가운데 「태도」에서 보는 것은 어느 것인가요?',ARRAY['K6-1-u3-X16','K6-1-u3-X45','K6-1-u3-X38']::text[],false,'{"seq":12,"concept":"K6-1-u3-C35","difficulty":2,"kind":"mc","stem":"판정 기준 가운데 「태도」에서 보는 것은 어느 것인가요?","options":[{"t":"규칙을 지키고 상대 말을 경청하며 예의 바르게 참여했는가","correct":true},{"t":"누가 더 오래 말했는가","mis":"K6-1-u3-X16"},{"t":"누가 더 큰 소리로 말했는가","mis":"K6-1-u3-X45"},{"t":"누가 옷을 단정하게 입었는가","mis":"K6-1-u3-X38"}],"explanation":["말한 길이는 기준이 아니에요.","목소리 크기도 아니에요.","규칙 · 경청 · 예의를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#13','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C34',2,'mc','auto','토론자가 상대 발언을 메모하는 가장 큰 까닭은 무엇인가요?',ARRAY['K6-1-u3-X38','K6-1-u3-X16','K6-1-u3-X08']::text[],false,'{"seq":13,"concept":"K6-1-u3-C34","difficulty":2,"kind":"mc","stem":"토론자가 상대 발언을 메모하는 가장 큰 까닭은 무엇인가요?","options":[{"t":"들은 것 가운데 가장 약한 곳을 골라 되받기 위해서","correct":true},{"t":"상대 말투를 흉내 내기 위해서","mis":"K6-1-u3-X38"},{"t":"판정단에게 보여 주기 위해서","mis":"K6-1-u3-X16"},{"t":"준비한 원고를 다시 읽기 위해서","mis":"K6-1-u3-X08"}],"explanation":["말투는 메모할 거리가 아니에요.","판정단은 스스로 판정해요.","가장 약한 곳을 되받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#14','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C21',2,'ox','auto','전문가의 말을 근거로 쓸 때에는 누구의 말인지 반드시 적어 둬요.',ARRAY['K6-1-u3-X22']::text[],false,'{"seq":14,"concept":"K6-1-u3-C21","difficulty":2,"kind":"ox","stem":"전문가의 말을 근거로 쓸 때에는 누구의 말인지 반드시 적어 둬요.","answer":"O","reason_options":[{"t":"누구의 말인지 밝혀야 확인할 수 있는 근거가 되기 때문에","correct":true},{"t":"전문가의 말은 누구 것이든 똑같기 때문에","mis":"K6-1-u3-X22"}],"mis":"K6-1-u3-X22","explanation":["전문가의 말도 근거가 돼요.","누구의 말인지 밝혀야 해요.","그래야 확인할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#15','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C1',2,'ox','auto','「우리 학교 도서실에 책이 몇 권 있는가」는 토론 주제로 알맞아요.',ARRAY['K6-1-u3-X01']::text[],false,'{"seq":15,"concept":"K6-1-u3-C1","difficulty":2,"kind":"ox","stem":"「우리 학교 도서실에 책이 몇 권 있는가」는 토론 주제로 알맞아요.","answer":"X","reason_options":[{"t":"찾아보면 곧바로 확인되는 물음이라 찬반이 갈리지 않기 때문에","correct":true},{"t":"수를 따지는 문제는 모두 좋은 토론 주제이기 때문에","mis":"K6-1-u3-X01"}],"mis":"K6-1-u3-X01","explanation":["세어 보면 답이 나와요.","찬반이 갈리지 않아요.","토론 주제가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#16','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C31',2,'mc','auto','근거를 말로 내놓을 때 알맞은 첫마디는 어느 것인가요?',ARRAY['K6-1-u3-X34','K6-1-u3-X29','K6-1-u3-X04']::text[],false,'{"seq":16,"concept":"K6-1-u3-C31","difficulty":2,"kind":"mc","stem":"근거를 말로 내놓을 때 알맞은 첫마디는 어느 것인가요?","options":[{"t":"「우리 시 교통 안전과가 지난해 낸 자료에 따르면」","correct":true},{"t":"「어디서 봤는데」","mis":"K6-1-u3-X34"},{"t":"「다들 아시겠지만」","mis":"K6-1-u3-X29"},{"t":"「제 느낌에는」","mis":"K6-1-u3-X04"}],"explanation":["「어디서 봤는데」는 자료를 흔들어요.","「다들」은 흐릿해요.","누가 언제 낸 자료인지 먼저 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#17','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C5',3,'mc','auto','「상대 근거의 허점을 짚고 그에 답하는」 일과 「남은 것만 추려 다시 강조하는」 일이 바르게 짝 지어진 것은 어느 것인가요?',ARRAY['K6-1-u3-X06']::text[],false,'{"seq":17,"concept":"K6-1-u3-C5","difficulty":3,"kind":"mc","stem":"「상대 근거의 허점을 짚고 그에 답하는」 일과 「남은 것만 추려 다시 강조하는」 일이 바르게 짝 지어진 것은 어느 것인가요?","options":[{"t":"반론하기 — 주장 다지기","correct":true},{"t":"주장 펼치기 — 판정하기","mis":"K6-1-u3-X06"},{"t":"주장 다지기 — 반론하기","mis":"K6-1-u3-X06"},{"t":"판정하기 — 주장 펼치기","mis":"K6-1-u3-X06"}],"explanation":["허점을 짚는 것은 반론하기예요.","다시 강조하는 것은 주장 다지기예요.","순서가 곧 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#18','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C27',3,'mc','auto','「저희 이모께서 운전할 때 답답하다고 하셨습니다.」가 근거로 약한 까닭은 무엇인가요?',ARRAY['K6-1-u3-X31','K6-1-u3-X17','K6-1-u3-X30']::text[],false,'{"seq":18,"concept":"K6-1-u3-C27","difficulty":3,"kind":"mc","stem":"「저희 이모께서 운전할 때 답답하다고 하셨습니다.」가 근거로 약한 까닭은 무엇인가요?","options":[{"t":"한 사람의 느낌이라 제한 속도와 사고 사이의 관계를 보여 주지 못하기 때문에","correct":true},{"t":"이모는 어른이라 근거가 될 수 없기 때문에","mis":"K6-1-u3-X31"},{"t":"높임말을 썼기 때문에","mis":"K6-1-u3-X17"},{"t":"너무 자세하기 때문에","mis":"K6-1-u3-X30"}],"explanation":["어른이라서가 아니에요.","높임말은 문제가 아니에요.","이유와 이어지지 않는 느낌이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#19','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C12',3,'mc','auto','반론을 받았을 때 답변하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K6-1-u3-X13','K6-1-u3-X14','K6-1-u3-X16']::text[],false,'{"seq":19,"concept":"K6-1-u3-C12","difficulty":3,"kind":"mc","stem":"반론을 받았을 때 답변하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"반론이 타당하지 않음을 밝히거나, 인정할 것은 인정하고 다시 세운다","correct":true},{"t":"못 들은 척하거나 같은 말을 되풀이한다","mis":"K6-1-u3-X13"},{"t":"상대의 말투를 짚거나 화제를 바꾼다","mis":"K6-1-u3-X14"},{"t":"판정단에게 대신 답해 달라고 한다","mis":"K6-1-u3-X16"}],"explanation":["되풀이는 답변이 아니에요.","화제를 바꾸지 않아요.","물은 지점에 곧바로 답해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#20','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C36',3,'ox','auto','토론이 끝난 뒤 생각이 더 굳어졌다고 말하는 것도 토론을 제대로 한 표시예요.',ARRAY['K6-1-u3-X39']::text[],false,'{"seq":20,"concept":"K6-1-u3-C36","difficulty":3,"kind":"ox","stem":"토론이 끝난 뒤 생각이 더 굳어졌다고 말하는 것도 토론을 제대로 한 표시예요.","answer":"O","reason_options":[{"t":"생각이 바뀌든 굳어지든 상대 근거와 견주어 다시 살펴본 결과이기 때문에","correct":true},{"t":"생각은 처음부터 끝까지 변하면 안 되기 때문에","mis":"K6-1-u3-X39"}],"mis":"K6-1-u3-X39","explanation":["바뀌는 것도 괜찮아요.","굳어지는 것도 괜찮아요.","다시 살펴본 것이 중요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#21','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C40',3,'error','auto','성곽 토론 뒤에 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K6-1-u3-X42']::text[],false,'{"seq":21,"concept":"K6-1-u3-C40","difficulty":3,"kind":"error","stem":"성곽 토론 뒤에 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"윤슬 — 「되살리자는 쪽은 역사를 모르는 거야.」","correct":true,"mis_target":"K6-1-u3-X42"},{"t":"가람 — 「찬성 측은 배움의 기회를 더 중요하게 여겼어.」","mis":"K6-1-u3-X42"},{"t":"도윤 — 「반대 측은 남은 것의 진짜 모습을 더 중요하게 여겼어.」","mis":"K6-1-u3-X42"}],"explanation":["가람은 관점을 바르게 정리했어요.","도윤도 관점을 바르게 정리했어요.","윤슬은 상대를 낮추어 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#22','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C43',3,'mc','auto','「긁다」와 「긁고」를 바르게 읽은 것은 어느 것인가요?',ARRAY['K6-1-u3-X44']::text[],false,'{"seq":22,"concept":"K6-1-u3-C43","difficulty":3,"kind":"mc","stem":"「긁다」와 「긁고」를 바르게 읽은 것은 어느 것인가요?","options":[{"t":"[극따] · [글꼬]","correct":true},{"t":"[글따] · [극꼬]","mis":"K6-1-u3-X44"},{"t":"[극따] · [극꼬]","mis":"K6-1-u3-X44"},{"t":"[글따] · [글꼬]","mis":"K6-1-u3-X44"}],"explanation":["ㄷ 앞에서는 [ㄱ]으로 소리 나요.","ㄱ 앞에서는 [ㄹ]로 소리 나요.","뒤 자음은 된소리가 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#23','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C34',4,'mc','auto','은솔이의 메모를 가장 알맞게 고친 것은 어느 것인가요?',ARRAY['K6-1-u3-X12','K6-1-u3-X38','K6-1-u3-X08']::text[],false,'{"seq":23,"concept":"K6-1-u3-C34","difficulty":4,"kind":"mc","stem":"은솔이의 메모를 가장 알맞게 고친 것은 어느 것인가요?","options":[{"t":"「반대 측 말투」 줄을 빼고, 「찬성 측 답변이 닿지 않은 물음」 같은 되받을 거리를 적는다","correct":true},{"t":"모든 발언을 한 글자도 빠짐없이 옮겨 적는다","mis":"K6-1-u3-X12"},{"t":"양측 옷차림도 덧붙여 적는다","mis":"K6-1-u3-X38"},{"t":"메모를 지우고 준비한 원고만 본다","mis":"K6-1-u3-X08"}],"explanation":["다 옮기면 다음 말을 놓쳐요.","옷차림은 되받을 거리가 아니에요.","되받을 거리를 남겨요."],"asset":{"type":"passage","lines":["찬성 측 주장 — 점심시간에도 도서실을 열어야 한다.","찬성 측 이유 — 쉬는 시간만으로는 책 고를 시간이 모자란다.","찬성 측 근거 — 도서부, 이번 학기, 고학년 이백 명 설문.","반대 측 근거 — 어떤 누리집(어디인지 밝히지 않음).","반대 측이 꺼낸 다른 이야기 — 급식 줄.","반대 측 말투 — 목소리가 컸음."],"title":"청중 은솔이의 메모"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#24','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C36',4,'essay','teacher','토론 뒤 서아 · 은솔 · 도담의 말을 견주어 평가하고, 토론을 어떻게 마무리하면 좋을지 내 생각을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K6-1-u3-C36","difficulty":4,"kind":"essay","stem":"토론 뒤 서아 · 은솔 · 도담의 말을 견주어 평가하고, 토론을 어떻게 마무리하면 좋을지 내 생각을 쓰세요.","answer_guide":{"answer":"예: 서아는 판정단 탓을 해서 판정에 승복하지 않았고 남는 것이 승패뿐이다. 은솔이는 새롭게 안 사실과 사회자의 잘한 점을 말해 알맞다. 도담이는 상대가 짚은 점을 받아들이고 더 찾아보려 해서 생각을 남겼다. 나는 토론이 끝나면 판정에 승복하고, 새로 안 것과 다른 역할을 맡은 친구의 잘한 점을 나누며, 생각이 바뀌거나 굳어진 곳을 말하는 것이 좋은 마무리라고 생각한다.","scoring_points":["서아의 말이 알맞지 않은 까닭을 썼는가","은솔 · 도담의 말이 알맞은 까닭을 썼는가","바람직한 마무리를 내 생각으로 썼는가"]},"explanation":["세 친구의 말을 견줘요.","승패와 생각 가운데 무엇이 남는지 봐요.","내 생각을 써요."],"asset":{"type":"speech","turns":[{"who":"서아","text":"판정이 이상해. 우리가 진 건 판정단 탓이야."},{"who":"은솔","text":"나는 도서부 설문 자료를 처음 알았어. 사회를 맡은 하람이가 말차례를 잘 지켜 줬어."},{"who":"도담","text":"반대 측이 말한 지키는 분의 쉬는 시간은 미처 생각 못 했어. 도서부가 돌아가며 돕는 방법을 찾아봐야겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_kor_u3_review_d#25','kor',6,1,'u3','','g6_1_kor_u3_review_d','unit_review','K6-1-u3-C43',4,'essay','teacher','겹받침 ㄺ이 있는 낱말 하나를 골라 뒤에 ㄷ이 올 때와 ㄱ이 올 때 어떻게 다르게 읽는지 예를 들어 설명하세요.','{}'::text[],false,'{"seq":25,"concept":"K6-1-u3-C43","difficulty":4,"kind":"essay","stem":"겹받침 ㄺ이 있는 낱말 하나를 골라 뒤에 ㄷ이 올 때와 ㄱ이 올 때 어떻게 다르게 읽는지 예를 들어 설명하세요.","answer_guide":{"answer":"예: 「밝다」는 [박따]로 읽는다. ㄺ 뒤에 ㄷ이 오면 ㄺ은 [ㄱ]으로 소리 나고 뒤의 ㄷ은 된소리가 되기 때문이다. 「밝고」는 [발꼬]로 읽는다. ㄺ 뒤에 ㄱ이 오면 [ㄹ]로 소리 나고 뒤의 ㄱ이 된소리가 되기 때문이다.","scoring_points":["ㄺ이 있는 낱말을 골라 두 경우를 바르게 읽었는가","ㄷ 앞에서 [ㄱ]으로 소리 나는 까닭을 썼는가","ㄱ 앞에서 [ㄹ]로 소리 나는 까닭을 썼는가"]},"explanation":["ㄺ 낱말을 골라요.","ㄷ 앞에서 읽어요.","ㄱ 앞에서 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
